// lay.* = what the patient says, verbatim. vit = "Befunde der Pflege". brief = model document for Teil 2 (full sentences, Präteritum, Konjunktiv I).
// kw = expected points per Oberarzt question (regex alternatives; the first alternative is the label). vn/geb/cm/kg/ha = Patientendaten.
const P3_FSP_OVER={
f9:{vn:"Aylin",geb:"14.03.2003",cm:168,kg:62,ha:"Frau Doktor Seitz in Neuenheim",sys:"gi",scale:7,
 vit:"RR 118/72 mmHg · HF 104/min · AF 18/min · SpO₂ 98 % · Temp. 38,2 °C",
 lay:{open:"Ich habe seit gestern Abend Bauchschmerzen. Erst war es um den Nabel herum, jetzt tut es rechts unten weh.",
  pmh:"Nein, eigentlich bin ich gesund. Im Krankenhaus war ich nur einmal als Kind.",ops:"Als Kind hat man mir die Mandeln rausgenommen, sonst nichts.",
  meds:"Nur die Pille. Sonst nehme ich nichts.",all:"Ja, gegen Penicillin. Als Kind habe ich davon einen Ausschlag am ganzen Körper bekommen.",
  fam:"Meine Mutter hat Gallensteine. Sonst sind bei uns alle gesund, soweit ich weiß.",nox:"Ich rauche nicht. Am Wochenende trinke ich mal ein Glas Wein.",drugs:"Nein, um Gottes willen.",
  soc:"Ich studiere auf Lehramt und wohne in einer WG. Ich habe einen festen Freund.",
  char:"Am Anfang war es so ein dumpfes Drücken, jetzt ist es eher ein Stechen.",rad:"Nein, der Schmerz bleibt rechts unten, er zieht nirgendwohin.",
  mod:"Wenn ich huste oder das Auto über eine Bodenwelle fährt, ist es kaum auszuhalten. Am besten geht es, wenn ich still liege und die Beine anziehe.",
  prev:"Nein, so etwas hatte ich noch nie.",self:"Ich habe gestern Abend einen Kamillentee getrunken, das hat nichts gebracht. Tabletten habe ich keine genommen.",
  vacc:"Ich glaube, ich habe alles. Tetanus wurde vor ein paar Jahren aufgefrischt.",reise:"Nein, ich war die letzten Monate nur in Heidelberg.",
  veg:{appetit:"Seit gestern habe ich gar keinen Appetit.",gewicht:"Nein, mein Gewicht ist gleich geblieben.",stuhl:"Der Stuhlgang war gestern noch normal, heute war ich noch nicht.",wasser:"Beim Wasserlassen ist alles normal, es brennt nicht.",schlaf:"Heute Nacht habe ich wegen der Schmerzen kaum geschlafen.",fieber:"Heute Morgen hatte ich 38,2."},
  gyn:"Meine letzte Periode war vor ungefähr drei Wochen, ganz normal. Schwanger bin ich nicht – glaube ich jedenfalls."},
 brief:"Frau Demir ist eine 23-jährige Patientin, die sich mit seit dem Vorabend bestehenden Bauchschmerzen in unserer Notaufnahme vorstellte. Die Schmerzen hätten periumbilikal begonnen und seien in der Nacht in den rechten Unterbauch gewandert. Sie seien bei Erschütterung verstärkt und hätten eine Intensität von 7/10. Begleitend bestünden Übelkeit, einmaliges Erbrechen und Inappetenz; die Patientin habe am Morgen eine Temperatur von 38,2 °C gemessen. Miktion und Stuhlgang seien unauffällig. Die letzte Menstruation sei vor drei Wochen gewesen.\nAn Vorerkrankungen sind keine bekannt. Z. n. Tonsillektomie in der Kindheit. Medikation: orales Kontrazeptivum. Es besteht eine Penicillinallergie (Exanthem). Nikotinkonsum wurde verneint, Alkohol gelegentlich. In der Familienanamnese findet sich eine Cholezystolithiasis der Mutter. Die Patientin ist Studentin und lebt in einer Wohngemeinschaft.\nDie Anamnese deutet am ehesten auf eine akute Appendizitis hin. Differenzialdiagnostisch kommen eine Adnexitis, eine rupturierte Ovarialzyste, eine Extrauteringravidität und ein Harnwegsinfekt in Betracht. Zur weiteren Abklärung empfehlen wir: körperliche Untersuchung, Labor (Blutbild, CRP), Urinstatus mit Schwangerschaftstest, Abdomensonographie; bei Bestätigung chirurgisches Konsil zur Appendektomie.",
 kw:[["Adnexitis","Ovarial","Extrauterin|Eileiter","Schwangerschaftstest|hCG","Sonograph|Ultraschall|transvaginal"],["Exanthem|Ausschlag|keine Anaphylaxie","Cephalosporin|Cefuroxim|Cefazolin","Kreuzallergie|Kreuzreaktion","Metronidazol|Alternative|Clindamycin"],["Peritonitis|Abwehrspannung|bretthart","Fieber|septisch","Leukozytose|CRP","freie Flüssigkeit|Abszess","Schmerz.{0,20}(nachl|Besserung)|diffus"]],
 terms:["Appendizitis","Abwehrspannung","Loslassschmerz","Extrauteringravidität","Leukozytose"]},

f10:{vn:"Elif",geb:"02.07.1992",cm:165,kg:68,ha:"Herr Doktor Krämer in Kirchheim",sys:"nephro-uro",scale:7,
 vit:"RR 112/68 mmHg · HF 108/min · AF 20/min · SpO₂ 97 % · Temp. 39,1 °C",
 lay:{open:"Ich habe seit zwei Tagen hohes Fieber und Schüttelfrost, und rechts im Rücken tut es weh.",
  pmh:"Ich habe öfter mal eine Blasenentzündung, zwei- bis dreimal im Jahr. Sonst bin ich gesund.",ops:"Nein, operiert worden bin ich noch nie. Im Krankenhaus war ich nur zur Geburt meines Sohnes.",
  meds:"Regelmäßig nehme ich nichts. Wenn ich Schmerzen habe, nehme ich mal eine Ibuprofen.",all:"Nein, Allergien habe ich keine, soweit ich weiß.",
  fam:"Meine Mutter hat Zucker, sie nimmt Tabletten dafür. Mein Vater ist gesund.",nox:"Ich rauche nicht. Alkohol trinke ich gar nicht.",drugs:"Nein, nie.",
  soc:"Ich bin Verkäuferin in einer Bäckerei. Ich bin verheiratet, wir haben einen Sohn, der ist vier.",
  char:"Es ist ein dumpfer, starker Schmerz, der die ganze Zeit da ist.",rad:"Es zieht ein bisschen nach vorne in den Bauch, aber nicht bis in die Leiste.",
  mod:"Wenn ich mich bewege oder jemand auf die Stelle klopft, wird es schlimmer. Die Wärmflasche hat ein wenig geholfen.",
  prev:"Blasenentzündungen kenne ich, aber so schlimm mit Fieber und Rückenschmerzen war es noch nie.",self:"Ich habe gestern zwei Ibuprofen genommen, da ging das Fieber kurz runter. Und viel Blasentee.",
  vacc:"Die normalen Impfungen habe ich alle, glaube ich.",reise:"Nein, wir waren dieses Jahr nicht weg.",
  veg:{appetit:"Ich habe gar keinen Appetit, mir ist die ganze Zeit schlecht.",wasser:"Es brennt beim Wasserlassen, und ich muss ständig auf die Toilette, aber es kommt immer nur wenig. Der Urin ist trüb und riecht streng.",stuhl:"Der Stuhlgang ist normal.",schlaf:"Ich schlafe kaum, wegen dem Schüttelfrost.",fieber:"Gestern Abend hatte ich fast 40 Grad. Und ich habe richtig gezittert.",durst:"Trinken fällt mir schwer, weil mir so übel ist."},
  gyn:"Meine letzte Regel war vor zwei Wochen. Ich habe eine Spirale, schwanger bin ich also nicht."},
 brief:"Frau Yilmaz ist eine 34-jährige Patientin, die sich mit seit zwei Tagen bestehendem Fieber bis 40 °C, Schüttelfrost und rechtsseitigen Flankenschmerzen vorstellte. Drei Tage zuvor hätten Dysurie und Pollakisurie begonnen. Die Schmerzen seien dumpf und dauerhaft und hätten eine Intensität von 7/10. Begleitend bestehe Übelkeit; die Trinkmenge sei reduziert. Die Patientin habe zweimal Ibuprofen eingenommen. Eine Schwangerschaft sei bei liegender Spirale unwahrscheinlich.\nAn Vorerkrankungen sind rezidivierende Zystitiden (zwei- bis dreimal pro Jahr) bekannt. Voroperationen wurden verneint. Keine Dauermedikation, Ibuprofen bei Bedarf. Allergien sind nicht bekannt. Nikotin- und Alkoholkonsum wurden verneint. Die Mutter leide an Diabetes mellitus Typ 2. Die Patientin ist Verkäuferin, verheiratet und hat einen vierjährigen Sohn.\nDie Anamnese spricht am ehesten für eine akute Pyelonephritis rechts. Differenzialdiagnostisch kommen ein infizierter Harnstau bei Urolithiasis, eine Cholezystitis und eine Adnexitis in Betracht. Wir empfehlen: Urinstatus und Urinkultur, Blutkulturen, Labor (Blutbild, CRP, Kreatinin), Schwangerschaftstest, Sonographie der Nieren, intravenöse Flüssigkeit und Antibiose mit Ceftriaxon sowie die stationäre Aufnahme.",
 kw:[["Schwangerschaft","Harnstau|Obstruktion|Stein","Mann|männlich|Diabetes|Immunsuppression|anatomisch","stationär|intravenös|i\\.\\s?v\\.","Bildgebung|Sonograph"],["Harnstau|gestaute Niere|Nierenbecken.{0,12}erweitert|Hydronephrose","infiziert|Urosepsis","Entlastung|Harnleiterschiene|Doppel-J|Nephrostomie"],["fieberfrei|entfiebert|klinische Besserung","24|48","Antibiogramm|Resistogramm|Kultur","Ciprofloxacin|Cefpodoxim|Cotrimoxazol|oral"]],
 terms:["Pyelonephritis","Dysurie","Pollakisurie","Harnstau","Urinkultur"]},

f11:{vn:"Horst",geb:"19.05.1954",cm:174,kg:81,ha:"Herr Doktor Bauer in Wieblingen",sys:"pulmo",
 vit:"RR 148/86 mmHg · HF 112/min · AF 28/min · SpO₂ 84 % unter Raumluft · Temp. 38,1 °C",
 lay:{open:"Ich kriege seit drei Tagen immer schlechter Luft, jetzt sogar im Sitzen. Und ich huste gelb-grünen Schleim ab.",
  pmh:"Ich habe seit zehn Jahren eine Raucherlunge. Letztes Jahr war ich deswegen zweimal im Krankenhaus. Außerdem habe ich hohen Blutdruck, und 2019 hat man mir am Herzen so ein Röhrchen eingesetzt.",
  ops:"Richtig operiert worden bin ich nie. Nur das Röhrchen am Herzen, das ging über die Leiste.",
  meds:"Zwei Sprays für die Lunge, eins morgens und eins morgens und abends, und ein blaues für den Notfall. Dazu ASS, eine Blutdrucktablette und abends eine fürs Cholesterin.",
  all:"Nein, Allergien habe ich keine.",fam:"Mein Bruder ist an Lungenkrebs gestorben, mein Vater hatte einen Herzinfarkt.",
  nox:"Ich habe vor fünf Jahren aufgehört. Davor über dreißig Jahre, gut anderthalb Schachteln am Tag. Alkohol trinke ich kaum, mal ein Bier am Sonntag.",drugs:"Nein, so etwas habe ich nie angerührt.",
  soc:"Ich war Schlosser, jetzt bin ich Rentner. Ich wohne mit meiner Frau im zweiten Stock, einen Aufzug haben wir nicht.",
  mod:"Jede Bewegung macht es schlimmer, schon der Gang zur Toilette. Im Sitzen, nach vorne gebeugt, geht es am besten. Das Notfallspray hilft nur noch ein paar Minuten.",
  prev:"Ja, letztes Jahr zweimal, da musste ich auch ins Krankenhaus. Aber so schlimm wie jetzt war es noch nicht.",self:"Ich habe das blaue Spray immer wieder genommen, bestimmt zehnmal am Tag. Viel gebracht hat es nicht.",
  vacc:"Gegen Grippe lasse ich mich jedes Jahr impfen, gegen Corona auch. Ob ich die Impfung gegen Lungenentzündung habe, weiß ich nicht.",reise:"Nein, ich komme ja kaum noch die Treppe runter.",
  veg:{appetit:"Der Appetit ist schlecht, das Essen strengt mich an.",gewicht:"Ich habe im letzten halben Jahr vielleicht zwei, drei Kilo abgenommen.",schlaf:"Heute Nacht konnte ich nur im Sitzen schlafen.",fieber:"Meine Frau hat gestern gemessen, da waren es 38 Grad.",stuhl:"Der Stuhlgang ist normal.",wasser:"Beim Wasserlassen ist alles in Ordnung."}},
 brief:"Herr Wagner ist ein 72-jähriger Patient, der sich mit seit drei Tagen zunehmender Dyspnoe, zuletzt auch in Ruhe, in unserer Notaufnahme vorstellte. Er berichtete, der Husten habe zugenommen und der Auswurf sei nun gelb-grün. In der vergangenen Nacht habe er nur im Sitzen schlafen können; das Bedarfsspray helfe kaum noch. Die Ehefrau habe am Vortag eine Temperatur von 38 °C gemessen.\nAn Vorerkrankungen sind eine COPD (GOLD 3) seit zehn Jahren mit zwei Exazerbationen im letzten Jahr, eine arterielle Hypertonie und eine koronare Herzkrankheit mit Stentimplantation 2019 bekannt. Medikation: Tiotropium 1-0-0, Salmeterol/Fluticason 1-0-1, Salbutamol bei Bedarf, ASS 100 mg, Ramipril 5 mg, Atorvastatin 40 mg. Allergien sind nicht bekannt. Der Patient habe vor fünf Jahren das Rauchen beendet (ca. 50 Packungsjahre). Der Bruder sei an einem Bronchialkarzinom verstorben, der Vater habe einen Myokardinfarkt erlitten. Der Patient ist Rentner und lebt mit seiner Ehefrau im zweiten Stock ohne Aufzug.\nDie Anamnese deutet auf eine akute, am ehesten infektbedingte Exazerbation der COPD hin. Differenzialdiagnostisch sind eine Pneumonie, eine kardiale Dekompensation und eine Lungenembolie zu bedenken. Wir empfehlen: Blutgasanalyse, kontrollierte Sauerstoffgabe mit Zielsättigung 88–92 %, Inhalation mit Salbutamol/Ipratropium, Prednisolon, Röntgen-Thorax, Labor und bei respiratorischer Azidose eine nichtinvasive Beatmung.",
 kw:[["pH|Azidose","pCO2|Hyperkapnie|hyperkapnisch","7,35","Atemfrequenz|Erschöpfung|Atemmuskulatur","trotz.{0,25}Therapie|keine Besserung"],["Hyperkapnie|CO2-Narkose|CO2-Retention","Atemantrieb","88","Ventilation.{0,10}Perfusion|Haldane|hypoxisch"],["Infiltrat|Röntgen","einseitig.{0,20}Bein|Thrombose|D-Dimer|plötzlich","Ödeme|BNP|Stauung|Orthopnoe","Troponin|EKG"]],
 terms:["Dyspnoe","Exazerbation","Sputum","Hyperkapnie","Blutgasanalyse"]},

f12:{vn:"Werner",geb:"23.01.1958",cm:178,kg:84,ha:"Frau Doktor Hahn in Dossenheim",sys:"neuro",
 vit:"RR 162/94 mmHg · HF 78/min, rhythmisch · AF 14/min · SpO₂ 97 % · Temp. 36,7 °C · BZ 142 mg/dl · GCS 15",
 lay:{open:"Heute Mittag konnte ich auf einmal nicht mehr richtig sprechen, und mein rechter Arm war ganz schwach. Nach zwanzig Minuten war alles wieder weg.",
  pmh:"Ich habe seit fünfzehn Jahren hohen Blutdruck und seit acht Jahren Zucker. Das Cholesterin ist auch zu hoch.",ops:"Nein, operiert worden bin ich noch nie.",
  meds:"Eine Tablette für den Blutdruck morgens, Metformin morgens und abends und abends eine fürs Cholesterin.",
  all:"Vor Jahren habe ich nach einem Kontrastmittel einen Hautausschlag bekommen. Ganz sicher bin ich nicht, ob es daran lag.",
  fam:"Meine Mutter hatte mit 75 einen Schlaganfall. Mein Vater hatte Zucker.",nox:"Ich habe nie geraucht. Abends trinke ich ein, zwei Gläser Wein.",drugs:"Nein, natürlich nicht.",
  soc:"Ich war Lehrer, jetzt bin ich pensioniert. Ich lebe mit meiner Frau zusammen und fahre noch selbst Auto.",
  mod:"Es kam ganz plötzlich, mitten beim Essen, und ging von allein wieder weg. Ich habe nichts dagegen getan.",prev:"Nein, das ist mir zum ersten Mal passiert.",
  self:"Nein, ich habe nichts genommen. Meine Frau wollte gleich herfahren.",vacc:"Grippe und Corona ja, die anderen stehen im Impfpass.",reise:"Nein, wir waren zuletzt im Frühjahr an der Ostsee.",
  veg:{appetit:"Der Appetit ist gut.",gewicht:"Mein Gewicht ist gleich geblieben.",schlaf:"Ich schlafe gut.",stuhl:"Alles normal.",wasser:"Nachts muss ich einmal raus, sonst ist alles normal.",fieber:"Nein, Fieber habe ich nicht."}},
 brief:"Herr Müller ist ein 68-jähriger Patient, der sich nach einer vorübergehenden Sprachstörung mit Schwäche des rechten Armes vorstellte. Er berichtete, die Symptomatik habe am Mittag plötzlich beim Essen begonnen und etwa zwanzig Minuten angehalten; dabei sei ihm die Gabel aus der rechten Hand gefallen. Inzwischen sei er beschwerdefrei. Kopfschmerzen, Sehstörungen oder ein Krampfereignis wurden verneint. Ähnliche Ereignisse habe es bisher nicht gegeben.\nAn Vorerkrankungen bestehen eine arterielle Hypertonie seit 15 Jahren, ein Diabetes mellitus Typ 2 seit acht Jahren und eine Hypercholesterinämie. Voroperationen wurden verneint. Medikation: Ramipril 10 mg 1-0-0, Metformin 1000 mg 1-0-1, Simvastatin 20 mg 0-0-1. Der Patient gab eine fragliche Kontrastmittelallergie (Exanthem) an. Er sei Nichtraucher und trinke abends ein bis zwei Gläser Wein. Die Mutter habe mit 75 Jahren einen Schlaganfall erlitten. Der Patient ist pensionierter Lehrer, verheiratet und fährt selbst Auto.\nDie Anamnese spricht für eine transitorische ischämische Attacke im linken Mediastromgebiet. Differenzialdiagnostisch kommen ein Hirninfarkt mit Rückbildung, ein fokaler Anfall mit Todd-Parese, eine Migräne mit Aura und eine Hypoglykämie in Betracht. Wir empfehlen: Blutzucker, cCT bzw. MRT, EKG mit Monitoring, Duplexsonographie der Halsgefäße, ASS und die Aufnahme auf die Stroke Unit.",
 kw:[["Alter|60","Blutdruck|140","Klinik|Parese|Sprachstörung","Dauer|10|60","Diabetes","hohes Risiko|Stroke Unit|stationär"],["Bildgebung|cCT|MRT","EKG|Monitoring|Vorhofflimmern","Duplex|Halsgefäße|Karotis","Labor|Blutzucker|Lipide","Echokardiograph"],["duale|Clopidogrel","21 Tage|drei Wochen|kurzzeitig","Hochrisiko|ABCD2|kleiner Schlaganfall|minor","Blutungsrisiko","Vorhofflimmern.{0,30}Antikoagul"]],
 terms:["transitorische ischämische Attacke","Aphasie","Parese","Hypertonie","Thrombozytenaggregationshemmer"]},

f13:{vn:"Erwin",geb:"08.09.1947",cm:170,kg:74,ha:"Herr Doktor Vogel in Schriesheim",sys:"endo",
 vit:"RR 138/80 mmHg · HF 88/min · AF 16/min · SpO₂ 97 % · Temp. 36,4 °C · BZ 32 → 118 mg/dl nach Glukose · GCS 15",
 lay:{open:"Ich weiß gar nicht richtig, was passiert ist. Die Sanitäter haben gesagt, mein Zucker war viel zu niedrig.",
  pmh:"Ich habe seit zwanzig Jahren Zucker und hohen Blutdruck. Und die Nieren arbeiten nicht mehr so gut, sagt mein Hausarzt.",ops:"Ich habe links eine neue Hüfte bekommen, das ist ein paar Jahre her.",
  meds:"Morgens eine Zuckertablette, die heißt Glime-irgendwas, und Metformin morgens und abends. Dazu zwei Tabletten für den Blutdruck. Die Namen stehen auf meinem Plan, der ist im Geldbeutel.",
  all:"Nein, Allergien habe ich keine.",fam:"Mein Bruder hat auch Zucker. Meine Eltern sind beide alt geworden.",nox:"Ich rauche nicht. Alkohol trinke ich gar nicht.",drugs:"Nein, nie im Leben.",
  soc:"Ich war Landwirt, jetzt bin ich in Rente. Meine Frau ist gestorben, ich lebe allein auf dem Hof. Mein Sohn wohnt im Nachbarort.",
  mod:"Ich habe heute das Mittagessen ausgelassen, weil ich keinen Hunger hatte. Die Tabletten habe ich aber wie immer genommen.",prev:"Zittrig und schwitzig war ich schon ein paarmal vor dem Essen. Aber umgekippt bin ich noch nie.",
  self:"Nein. Die Sanitäter haben mir etwas in die Vene gespritzt, danach war ich wieder da.",vacc:"Grippe jedes Jahr, das macht mein Hausarzt.",reise:"Nein, ich komme vom Hof nicht weg.",
  veg:{appetit:"In den letzten Tagen habe ich wenig Hunger.",gewicht:"Ich glaube, ich habe ein bisschen abgenommen, die Hose rutscht.",schlaf:"Ich schlafe gut.",stuhl:"Der ist normal.",wasser:"Ich muss nachts zweimal raus, das ist schon lange so.",fieber:"Nein, Fieber habe ich nicht.",durst:"Nein, nicht besonders."}},
 brief:"Herr Keller ist ein 79-jähriger Patient, der vom Rettungsdienst nach einer Bewusstseinstrübung in unsere Notaufnahme gebracht wurde. Vor Ort sei ein Blutzucker von 32 mg/dl gemessen worden; nach intravenöser Glukosegabe sei der Patient rasch aufgeklart. Er berichtete, er habe am Morgen seine Medikamente wie gewohnt eingenommen, das Mittagessen jedoch ausgelassen. Eine Nachbarin habe ihn am Nachmittag verschwitzt und verwirrt aufgefunden. Ähnliche Episoden mit Zittern und Schwitzen vor den Mahlzeiten seien bereits vorgekommen.\nAn Vorerkrankungen bestehen ein Diabetes mellitus Typ 2 seit 20 Jahren, eine chronische Niereninsuffizienz Stadium 3b und eine arterielle Hypertonie. Z. n. Hüft-TEP links. Medikation: Glimepirid 3 mg 1-0-0, Metformin 1000 mg 1-0-1, Candesartan 16 mg 1-0-0, Bisoprolol 5 mg 1-0-0. Allergien sind nicht bekannt. Nikotin- und Alkoholkonsum wurden verneint. Der Bruder leide ebenfalls an Diabetes. Der Patient ist verwitweter Landwirt im Ruhestand und lebt allein; der Sohn wohne im Nachbarort.\nEs handelt sich um eine schwere Hypoglykämie unter Sulfonylharnstoff bei eingeschränkter Nierenfunktion und ausgelassener Mahlzeit. Differenzialdiagnostisch sind ein Schlaganfall und ein Infekt als Auslöser zu bedenken. Wir empfehlen die stationäre Überwachung für mindestens 24 Stunden mit engmaschigen Blutzuckerkontrollen, das Absetzen von Glimepirid, die Kontrolle der Nierenwerte und eine Umstellung der antidiabetischen Therapie.",
 kw:[["lange Wirkdauer|Halbwertszeit|wirkt.{0,15}lange","Glimepirid|Sulfonylharnstoff","Niereninsuffizienz|Kumulation|Niere","Rezidiv|erneut","24"],["Kumulation|Ausscheidung|renal","Metformin.{0,40}(eGFR|kontraindiziert|Dosis|pausier)","Betablocker.{0,60}(maskier|Warnsymptom|verschleier)|maskier","Gegenregulation|Tachykardie|Zittern"],["Glimepirid absetzen|Sulfonylharnstoff absetzen|absetzen","DPP-4|Sitagliptin|Linagliptin","HbA1c","7,5|8|weniger streng|individuell","Hypoglykämie vermeiden|Sicherheit"]],
 terms:["Hypoglykämie","Sulfonylharnstoff","Niereninsuffizienz","Diabetes mellitus","Bewusstseinstrübung"]},

f14:{vn:"Claudia",geb:"30.04.1980",cm:166,kg:87,ha:"Frau Doktor Engel in Eppelheim",sys:"pulmo",scale:6,
 vit:"RR 112/70 mmHg · HF 118/min · AF 26/min · SpO₂ 91 % · Temp. 37,4 °C",
 lay:{open:"Ich bekomme seit heute Morgen ganz plötzlich schlecht Luft, und beim Einatmen sticht es rechts in der Brust.",
  pmh:"Eigentlich bin ich gesund. Ich habe Krampfadern, und ich weiß, dass ich zu viel wiege.",ops:"Nein, operiert worden bin ich noch nie.",
  meds:"Nur die Pille, die nehme ich seit zehn Jahren.",all:"Nein, keine.",fam:"Meine Mutter hatte nach einer Operation eine Thrombose im Bein. Mein Vater hat hohen Blutdruck.",
  nox:"Ich rauche, so zehn Zigaretten am Tag, seit ich Anfang zwanzig bin. Alkohol trinke ich selten.",drugs:"Nein.",
  soc:"Ich arbeite im Büro, ich sitze den ganzen Tag am Schreibtisch. Ich bin geschieden und habe zwei Kinder.",
  char:"Es ist ein scharfes Stechen, wie mit einem Messer, immer wenn ich tief Luft hole.",rad:"Nein, es bleibt rechts an der Seite.",
  mod:"Beim tiefen Einatmen und beim Husten sticht es. Wenn ich ganz flach atme, geht es.",prev:"Nein, so etwas hatte ich noch nie. Auch eine Thrombose hatte ich noch nie.",
  self:"Nein, ich bin gleich hergekommen.",vacc:"Ich bin geimpft, vor der Reise habe ich auch Hepatitis auffrischen lassen.",
  reise:"Ja, ich bin vor einer Woche aus Thailand zurückgekommen. Der Flug hat zwölf Stunden gedauert.",
  veg:{appetit:"Normal.",gewicht:"Unverändert.",schlaf:"Bis heute habe ich gut geschlafen.",fieber:"Nein, Fieber habe ich nicht gemessen. Ich glaube nicht.",stuhl:"Normal.",wasser:"Normal."},
  gyn:"Meine Regel kommt regelmäßig, die letzte war vor zehn Tagen. Schwanger bin ich nicht, ich nehme ja die Pille."},
 brief:"Frau Schneider ist eine 46-jährige Patientin, die sich mit am Morgen plötzlich aufgetretener Dyspnoe und atemabhängigen rechtsthorakalen Schmerzen vorstellte. Die Beschwerden hätten beim Treppensteigen begonnen; begleitend habe sie Herzrasen bemerkt. Das rechte Bein sei seit einigen Tagen geschwollen und schmerze in der Wade. Eine Woche zuvor sei sie von einer Fernreise mit zwölfstündigem Flug zurückgekehrt. Fieber, Husten und Hämoptysen wurden verneint.\nAn Vorerkrankungen bestehen eine Adipositas und eine Varikosis. Voroperationen wurden verneint. Medikation: kombiniertes orales Kontrazeptivum seit zehn Jahren. Allergien sind nicht bekannt. Die Patientin rauche etwa zehn Zigaretten pro Tag seit 25 Jahren. Die Mutter habe postoperativ eine Thrombose erlitten. Die Patientin ist Bürokauffrau mit sitzender Tätigkeit, geschieden und hat zwei Kinder.\nDie Anamnese deutet mit hoher klinischer Wahrscheinlichkeit auf eine Lungenembolie bei tiefer Beinvenenthrombose rechts hin. Differenzialdiagnostisch kommen eine Pneumonie mit Pleuritis, ein Pneumothorax und ein akutes Koronarsyndrom in Betracht. Wir empfehlen: Monitoring, Sauerstoffgabe, sofortige therapeutische Antikoagulation, CT-Pulmonalisangiographie, Kompressionssonographie der Beinvenen, EKG, Troponin und Echokardiographie sowie das Absetzen des Kontrazeptivums.",
 kw:[["hohe.{0,20}Wahrscheinlichkeit|Wells","D-Dimer.{0,60}(Ausschluss|nur bei niedrig|nicht sinnvoll|ändert nichts)|Ausschluss","direkt.{0,20}(CT|Bildgebung)|CT-Angiographie|CTPA","keine Verzögerung|Zeit"],["Schock|Hypotonie|hämodynamisch instabil","Hochrisiko|massive","Rechtsherzbelastung","Reanimation|Kreislaufstillstand"],["drei Monate|3 Monate|mindestens drei","provoziert|Auslöser|Risikofaktor","Pille absetzen|Kontrazeptivum absetzen|absetzen","verlänger|unprovoziert|Rezidiv","DOAK|Apixaban|Rivaroxaban"]],
 terms:["Lungenembolie","Thrombose","Antikoagulation","Dyspnoe","Tachykardie"]},

f15:{vn:"Hildegard",geb:"11.02.1942",cm:158,kg:54,ha:"Herr Doktor Maier in Handschuhsheim",sys:"muskulo",scale:8,
 vit:"RR 152/84 mmHg · HF 92/min, arrhythmisch · AF 18/min · SpO₂ 96 % · Temp. 36,6 °C · NRS 8/10",
 lay:{open:"Ich bin heute Vormittag in der Küche hingefallen. Seitdem tut die rechte Hüfte furchtbar weh, und ich kann nicht mehr aufstehen.",
  pmh:"Mein Herz schlägt unregelmäßig, dafür nehme ich einen Blutverdünner. Dann habe ich hohen Blutdruck, und die Knochen sind dünn. Und mein Sohn sagt, ich werde ein bisschen vergesslich.",
  ops:"Nein, operiert worden bin ich noch nie. Vor einem halben Jahr bin ich schon einmal gestürzt, aber da war nichts gebrochen.",
  meds:"Das Marcumar, das nehme ich so, wie es im Ausweis steht. Dann morgens zwei Blutdrucktabletten und Vitamin D für die Knochen.",
  all:"Ja, Novalgin vertrage ich nicht. Da ist mir einmal der Kreislauf weggesackt.",fam:"Meine Mutter hat sich im Alter auch den Oberschenkelhals gebrochen. Sonst weiß ich von nichts.",
  nox:"Ich habe nie geraucht, und Alkohol trinke ich nicht, höchstens ein Gläschen Sekt an Weihnachten.",drugs:"Aber nein, Herr Doktor.",
  soc:"Ich war Schneiderin. Mein Mann ist gestorben, ich wohne allein im ersten Stock. Mein Sohn kommt zweimal in der Woche, und morgens kommt der Pflegedienst. Draußen gehe ich mit dem Rollator.",
  char:"Es ist ein starker, stechender Schmerz, tief in der Leiste.",rad:"Es zieht in den Oberschenkel, bis zum Knie.",
  mod:"Sobald ich das Bein bewege, ist es nicht auszuhalten. Wenn ich ganz still liege, geht es einigermaßen.",prev:"Gestürzt bin ich vor einem halben Jahr schon einmal, aber gebrochen habe ich mir noch nie etwas.",
  self:"Nein, ich habe nichts genommen. Ich lag ja auf dem Boden, bis mein Nachbar kam.",vacc:"Gegen Grippe ja. Ob ich gegen Tetanus geimpft bin, weiß ich nicht mehr, das ist lange her.",reise:"Nein, ich verreise nicht mehr.",
  veg:{appetit:"Ich esse nicht mehr viel, aber das ist schon länger so.",gewicht:"Ich bin eher dünner geworden.",schlaf:"Ich schlafe schlecht, ich bin nachts oft wach.",stuhl:"Ich neige zu Verstopfung.",wasser:"Ich muss nachts zwei-, dreimal zur Toilette.",fieber:"Nein."},
  gyn:"Das ist bei mir schon vierzig Jahre vorbei. Ich habe ein Kind, meinen Sohn."},
 brief:"Frau Schmidt ist eine 84-jährige Patientin, die nach einem häuslichen Sturz mit starken Schmerzen in der rechten Hüfte vom Rettungsdienst eingeliefert wurde. Sie berichtete, sie sei am Vormittag in der Küche über einen Teppich gestolpert und auf die rechte Seite gefallen; danach habe sie nicht mehr aufstehen können. Die Schmerzen seien stechend, strahlten in den Oberschenkel aus und hätten eine Stärke von 8/10. Ein Kopfanprall und eine Bewusstlosigkeit wurden verneint; Schwindel oder Herzrasen vor dem Sturz habe sie nicht bemerkt.\nAn Vorerkrankungen bestehen ein Vorhofflimmern, eine arterielle Hypertonie, eine Osteoporose und eine leichte Demenz; vor sechs Monaten sei sie bereits ohne Fraktur gestürzt. Voroperationen wurden verneint. Medikation: Phenprocoumon nach INR, Bisoprolol 2,5 mg 1-0-0, Amlodipin 5 mg 1-0-0, Vitamin D 1000 IE 1-0-0. Es besteht eine Unverträglichkeit von Metamizol (Kreislaufreaktion). Nikotin- und Alkoholkonsum wurden verneint. Die Mutter habe im Alter eine Schenkelhalsfraktur erlitten. Die Patientin ist verwitwet, lebt allein im ersten Stock, wird morgens vom Pflegedienst versorgt und ist am Rollator mobil.\nDie Anamnese spricht für eine Schenkelhalsfraktur rechts unter oraler Antikoagulation. Differenzialdiagnostisch kommen eine pertrochantäre Fraktur, eine Beckenringfraktur und eine Hüftprellung in Betracht; die Sturzursache ist zu klären. Wir empfehlen: Analgesie mit Piritramid, Röntgen von Becken und Hüfte in zwei Ebenen, Labor mit INR und Hb, EKG, Pausieren von Phenprocoumon und die operative Versorgung innerhalb von 24 Stunden.",
 kw:[["Mortalität|Sterblichkeit","Komplikationen|Pneumonie|Thrombose|Dekubitus","Immobil|Mobilisation|frühe Belastung","Delir","Leitlinie|24"],["INR","Vitamin K","PPSB|Prothrombinkomplex","pausieren|absetzen","Bridging|Heparin|Rücksprache"],["Synkope|Rhythmus|EKG","Medikamente|Orthostase|Blutdruck","Sehen|Stolperfalle|Teppich","Orientierung|Angehörige|Brille|Hörgerät|Tag-Nacht","Flüssigkeit|Schmerztherapie|keine Benzodiazepine"]],
 terms:["Schenkelhalsfraktur","Osteoporose","Vorhofflimmern","Antikoagulation","Endoprothese"]},

f16:{vn:"Markus",geb:"06.06.1991",cm:183,kg:82,ha:"Herr Doktor Scholz in Leimen",sys:"allgemein",
 vit:"RR 96/58 mmHg · HF 122/min · AF 24/min · SpO₂ 93 % · Temp. 36,8 °C (nach Adrenalin i.m. durch den Notarzt)",
 lay:{open:"Mich hat vor einer halben Stunde eine Wespe am Hals gestochen. Danach hat alles gejuckt, die Lippen sind dick geworden, und mir wurde schwindelig.",
  pmh:"Ich habe Heuschnupfen und ein bisschen Asthma. Vor zwei Jahren hat mich eine Biene gestochen, da ist der ganze Arm dick geworden.",ops:"Nein, noch nie.",
  meds:"Ich habe ein Asthmaspray für den Notfall, und im Frühjahr nehme ich eine Allergietablette.",
  all:"Auf Bienen- und Wespenstiche reagiere ich wohl, aber bisher ist immer nur die Stelle dick geworden. Medikamente vertrage ich alle.",
  fam:"Meine Mutter hat Asthma. Mein Vater ist gesund.",nox:"Ich rauche nicht. Nach der Arbeit trinke ich ab und zu ein Bier.",drugs:"Nein.",
  soc:"Ich bin Gärtner im Landschaftsbau, ich arbeite den ganzen Tag draußen. Ich bin verheiratet und habe ein Kind.",
  mod:"Nach der Spritze vom Notarzt ist es schnell besser geworden. Nur der Hals fühlt sich noch eng an.",prev:"So schlimm noch nie. Nach dem Bienenstich vor zwei Jahren war nur der Arm geschwollen.",
  self:"Ich selbst habe nichts genommen. Der Notarzt hat mir eine Spritze in den Oberschenkel gegeben.",vacc:"Tetanus muss ich als Gärtner haben, das wurde letztes Jahr aufgefrischt.",reise:"Nein.",
  veg:{appetit:"Normal.",gewicht:"Gleich.",schlaf:"Gut.",stuhl:"Normal.",wasser:"Normal.",fieber:"Nein, Fieber habe ich nicht."}},
 brief:"Herr Fischer ist ein 35-jähriger Patient, der vom Notarzt nach einem Wespenstich am Hals eingeliefert wurde. Er berichtete, wenige Minuten nach dem Stich hätten generalisierter Juckreiz und Quaddeln eingesetzt, anschließend seien die Lippen angeschwollen. Ihm sei schwarz vor Augen geworden, sodass er sich habe hinsetzen müssen. Nach intramuskulärer Adrenalingabe durch den Notarzt habe sich der Zustand gebessert; es bestehe noch ein Engegefühl im Hals. Luftnot und Bewusstlosigkeit wurden verneint.\nAn Vorerkrankungen bestehen eine allergische Rhinitis und ein leichtes Asthma bronchiale; vor zwei Jahren sei es nach einem Bienenstich zu einer ausgeprägten Lokalreaktion gekommen. Voroperationen wurden verneint. Medikation: Salbutamol bei Bedarf, Cetirizin saisonal. Medikamentenallergien sind nicht bekannt. Der Patient sei Nichtraucher und trinke gelegentlich Bier. Die Mutter leide an Asthma. Er ist Gärtner im Landschaftsbau, verheiratet und hat ein Kind.\nEs handelt sich um eine Anaphylaxie Grad III auf Wespengift. Differenzialdiagnostisch kommen eine vasovagale Synkope und ein Asthmaanfall in Betracht. Wir empfehlen: Monitoring, Sauerstoff, Volumengabe, Dimetinden und Prednisolon intravenös, die Bestimmung der Serumtryptase, eine Überwachung für mindestens acht Stunden sowie die Verordnung eines Notfallsets mit Adrenalin-Autoinjektor und die allergologische Abklärung.",
 kw:[["Grad III|Grad 3","Kreislauf|Schock|Hypotonie|Bewusstseinstrübung","Haut.{0,30}(allein|nur).{0,15}Grad I|Urtikaria","Bronchospasmus|Larynx|Atemweg","Grad IV.{0,20}Stillstand|Kreislaufstillstand"],["Resorption|schnell|Oberschenkel","Sicherheit|Rhythmusstörung|Nebenwirkung","i\\.\\s?v\\..{0,60}(Monitoring|Intensiv|titrier|Reanimation|refraktär)|titrier","0,5|0,3"],["biphasisch","6|8|12|24","Notfallset|Autoinjektor","Anaphylaxie-Pass|Allergiepass|Schulung","Hyposensibilisierung|Immuntherapie|Allergolog"]],
 terms:["Anaphylaxie","Urtikaria","Angioödem","Adrenalin","Hyposensibilisierung"]},

fx1:{vn:"Georg",geb:"27.03.1948",cm:172,kg:79,ha:"Frau Doktor Winter in Buchen",sys:"infekt",
 vit:"RR 88/52 mmHg · HF 124/min · AF 26/min · SpO₂ 92 % · Temp. 39,4 °C · GCS 13",
 lay:{open:"Ich habe seit gestern hohes Fieber und Schüttelfrost. Und das Wasser kommt schon seit Tagen kaum noch.",
  pmh:"Die Prostata ist seit Jahren vergrößert. Dann habe ich hohen Blutdruck und Zucker.",ops:"Ich bin rechts am Leistenbruch operiert worden, das ist lange her.",
  meds:"Abends eine Kapsel für die Prostata, Metformin morgens und abends und morgens zwei Tabletten für den Blutdruck.",all:"Nein, keine.",
  fam:"Mein Bruder hatte mit siebzig Prostatakrebs. Mein Vater ist an einem Schlaganfall gestorben.",
  nox:"Ich habe vor dreißig Jahren aufgehört zu rauchen, davor war es eine Schachtel am Tag. Abends trinke ich ein Bier.",drugs:"Nein.",
  soc:"Ich war Landwirt, jetzt bin ich in Rente. Ich lebe mit meiner Frau auf dem Hof bei Buchen.",
  char:"Es ist ein starker Druck unten im Bauch, als ob die Blase gleich platzt.",rad:"Nein, es drückt nur unten in der Mitte.",
  mod:"Wenn ich versuche, Wasser zu lassen, wird der Druck noch schlimmer. Besser macht es nichts.",prev:"Probleme mit dem Wasserlassen habe ich schon lange. Aber Fieber und Schüttelfrost hatte ich dabei noch nie.",
  self:"Meine Frau hat mir gestern eine Paracetamol gegeben, das Fieber kam aber wieder.",vacc:"Grippe ja, jedes Jahr.",reise:"Nein.",
  veg:{appetit:"Seit gestern esse ich nichts mehr.",gewicht:"Das ist gleich geblieben.",wasser:"Es kommt nur noch tröpfchenweise, und es brennt seit drei Tagen. Nachts muss ich fünf-, sechsmal raus.",stuhl:"Der ist normal.",schlaf:"Schlecht, ich muss ja dauernd raus.",fieber:"Gestern Abend hatte ich über 39 und habe im Bett richtig geklappert.",durst:"Ich habe wenig getrunken, damit ich nicht so oft muss."}},
 brief:"Herr Hoffmann ist ein 78-jähriger Patient, der in Begleitung seiner Ehefrau mit seit dem Vortag bestehendem hohem Fieber, Schüttelfrost und zunehmender Verwirrtheit vorgestellt wurde. Er berichtete, das Wasserlassen sei seit längerer Zeit erschwert; der Urin komme nur noch tröpfchenweise, nachts müsse er fünf- bis sechsmal zur Toilette. Seit drei Tagen bestünden zusätzlich Brennen beim Wasserlassen und ein starker Druck im Unterbauch. Seit dem Morgen sei er so schwach, dass er kaum stehen könne. Laut Ehefrau rede er seit dem Morgen wirr.\nAn Vorerkrankungen bestehen eine benigne Prostatahyperplasie, eine arterielle Hypertonie und ein Diabetes mellitus Typ 2. Z. n. Leistenhernien-Operation rechts. Medikation: Tamsulosin 0,4 mg 0-0-1, Metformin 1000 mg 1-0-1, Ramipril 5 mg 1-0-0, Amlodipin 5 mg 1-0-0. Allergien sind nicht bekannt. Der Patient sei seit 30 Jahren Nichtraucher (ca. 20 Packungsjahre) und trinke abends ein Bier. Der Bruder sei an einem Prostatakarzinom erkrankt, der Vater an einem Schlaganfall verstorben. Der Patient ist Landwirt im Ruhestand und lebt mit seiner Ehefrau.\nDie Anamnese und die Vitalparameter sprechen für eine Urosepsis bei akutem Harnverhalt und benigner Prostatahyperplasie. Differenzialdiagnostisch kommen eine akute Prostatitis, eine Pyelonephritis mit Harnstau und eine Pneumonie in Betracht. Wir empfehlen: Blutkulturen und Urinkultur, Laktat, Labor, sofortige Volumengabe und Antibiose mit Piperacillin/Tazobactam, Sonographie, Harnableitung, Pausieren von Metformin und ein urologisches Konsil.",
 kw:[["Blutkulturen","Laktat","Antibio|Piperacillin","Volumen|30 ml|Flüssigkeit","eine Stunde|erste Stunde|sofort","Fokus"],["Fokus|Fokussanierung|Herd","Harnverhalt|Abfluss|Stau","Katheter|Ableitung|suprapubisch","ohne.{0,30}(wirkt|reicht).{0,20}nicht|Antibiotikum allein"],["Laktatazidose","Niere|Nierenversagen|Kreatinin","Sepsis|Hypoperfusion|Schock","stabil|Nierenfunktion.{0,20}(normal|erholt)|48"]],
 terms:["Urosepsis","Harnverhalt","Prostatahyperplasie","Blutkultur","Dysurie"]},

fx2:{vn:"Jana",geb:"15.08.2004",cm:171,kg:57,ha:"Frau Doktor Roth in Freiburg",sys:"endo",scale:5,
 vit:"RR 98/60 mmHg · HF 124/min · AF 30/min, tief · SpO₂ 99 % · Temp. 36,9 °C · BZ 512 mg/dl · GCS 14",
 lay:{open:"Mir ist seit zwei Tagen furchtbar schlecht, ich muss mich dauernd übergeben und habe Bauchweh. Heute bin ich ganz benebelt.",
  pmh:"Eigentlich bin ich gesund. Nur die Schilddrüse arbeitet zu wenig, das weiß ich seit zwei Jahren.",ops:"Nein, ich bin noch nie operiert worden.",
  meds:"Nur eine kleine Schilddrüsentablette morgens.",all:"Von Pflastern bekomme ich rote, juckende Haut. Sonst nichts.",
  fam:"Meine Mutter hat Zucker, seit sie jung ist. Sie muss Insulin spritzen. Mein Vater hat hohen Blutdruck.",nox:"Ich rauche nicht. Alkohol trinke ich selten, ich mache ja Leistungssport.",drugs:"Nein, gar nichts.",
  soc:"Ich studiere Sport und Biologie auf Lehramt und wohne in einer WG. Ich spiele Handball im Verein.",
  char:"Es ist so ein Krampfen und Drücken im ganzen Bauch.",rad:"Nein, es ist überall im Bauch, nicht an einer bestimmten Stelle.",
  mod:"Nach dem Erbrechen ist es kurz besser, dann kommt es wieder. Essen kann ich gar nichts.",prev:"Nein, so etwas hatte ich noch nie.",
  self:"Ich habe eine Tablette gegen Übelkeit aus der Apotheke genommen, die kam aber gleich wieder raus.",vacc:"Ich bin komplett geimpft, das wurde fürs Studium geprüft.",reise:"Nein, ich war nur im Trainingslager im Schwarzwald.",
  veg:{appetit:"Bis vor ein paar Tagen hatte ich ständig Hunger. Jetzt kriege ich nichts runter.",gewicht:"Ich habe in den letzten Wochen ungefähr sechs Kilo abgenommen, ohne es zu wollen.",wasser:"Ich muss dauernd aufs Klo, auch nachts drei-, viermal.",stuhl:"Der ist normal.",schlaf:"Schlecht, weil ich nachts so oft raus muss.",fieber:"Nein, Fieber habe ich nicht.",durst:"Ja, ich habe seit Wochen ständig Durst. Ich trinke bestimmt vier, fünf Liter am Tag."},
  gyn:"Meine letzte Periode war vor zwei Wochen. Ich nehme keine Pille, aber schwanger bin ich nicht, da bin ich sicher."},
 brief:"Frau Lindner ist eine 22-jährige Patientin, die sich mit seit zwei Tagen bestehender Übelkeit, rezidivierendem Erbrechen und diffusen Bauchschmerzen vorstellte. Sie berichtete, sie leide seit einigen Wochen unter starkem Durst mit einer Trinkmenge von vier bis fünf Litern pro Tag und häufigem Wasserlassen; zudem habe sie ungewollt etwa sechs Kilogramm abgenommen. Am Morgen sei ihrer Mitbewohnerin eine auffällig tiefe Atmung mit süßlichem Geruch aufgefallen; die Patientin fühle sich benommen. Fieber und Durchfall wurden verneint.\nAn Vorerkrankungen ist eine Hashimoto-Thyreoiditis bekannt. Voroperationen wurden verneint. Medikation: L-Thyroxin 50 µg 1-0-0. Es besteht eine Pflasterunverträglichkeit. Nikotin- und Drogenkonsum wurden verneint, Alkohol selten. Die Mutter leide seit der Jugend an Diabetes mellitus Typ 1. Die Patientin ist Studentin, lebt in einer Wohngemeinschaft und betreibt Leistungssport.\nDie Anamnese und der Blutzucker von 512 mg/dl sprechen für eine diabetische Ketoazidose bei Erstmanifestation eines Diabetes mellitus Typ 1. Differenzialdiagnostisch kommen ein akutes Abdomen, eine Gastroenteritis und eine Intoxikation in Betracht; eine Schwangerschaft ist auszuschließen. Wir empfehlen: venöse Blutgasanalyse mit Kalium, Ketone, Labor, EKG, Volumengabe, Insulin über Perfusor erst nach Kenntnis des Kaliumwertes, Kaliumsubstitution und die Aufnahme auf die Überwachungsstation.",
 kw:[["Insulin.{0,40}Kalium.{0,25}(Zelle|intrazellulär|senkt)|Kalium.{0,30}in die Zelle|verschiebt","Hypokaliämie","Rhythmusstörung|Arrhythmie","3,5|3,3","Gesamtkörperkalium|Kaliummangel"],["pH","Bikarbonat","Ketone|Ketonkörper","Anionenlücke","nicht.{0,20}Blutzucker|Blutzucker allein"],["Hirnödem","zu schnell|Osmolarität","langsam|50|100","Kinder|junge"]],
 terms:["Ketoazidose","Polyurie","Polydipsie","Kussmaul-Atmung","Hyperglykämie"]},

fx3:{vn:"Dragan",geb:"04.10.1957",cm:176,kg:88,ha:"Herr Doktor Haas in Stuttgart-Ost",sys:"kardio",
 vit:"RR 128/84 mmHg · HF 72/min · AF 16/min · SpO₂ 97 % · Temp. 36,6 °C",
 lay:{open:"Ich bin heute beim Treppensteigen kurz ohnmächtig geworden. Vorher war mir eng in der Brust.",
  pmh:"Ich habe hohen Blutdruck und zu viel Cholesterin. Und der Hausarzt hat vor Jahren mal gesagt, er hört ein Geräusch am Herzen. Darum habe ich mich nie gekümmert.",ops:"Man hat mir die Gallenblase rausgenommen, das ist bestimmt fünfzehn Jahre her.",
  meds:"Morgens eine Tablette für den Blutdruck und abends eine fürs Cholesterin.",all:"Nein, keine.",
  fam:"Mein Vater ist mit 72 ganz plötzlich gestorben, es hieß, es war das Herz. Meine Mutter hatte Zucker.",
  nox:"Ich habe vor zehn Jahren aufgehört zu rauchen. Davor dreißig Jahre lang eine Schachtel am Tag. Alkohol trinke ich kaum.",drugs:"Nein.",
  soc:"Ich war Busfahrer, jetzt bin ich in Rente. Ich lebe mit meiner Frau zusammen. Ich fahre sie dreimal die Woche zur Dialyse.",
  char:"Es war ein Engegefühl, wie ein Ring um die Brust. Jetzt ist es weg.",rad:"Nein, es ist nirgendwohin gezogen.",
  mod:"Es kommt bei Anstrengung, vor allem beim Treppensteigen. Wenn ich stehen bleibe, wird es besser.",prev:"Umgefallen bin ich noch nie. Aber schwindelig war mir beim Treppensteigen schon zweimal, und die Luft geht mir in letzter Zeit schneller aus.",
  self:"Nein, nichts.",vacc:"Grippe und Corona, ja.",reise:"Nein.",
  veg:{appetit:"Gut.",gewicht:"Unverändert.",schlaf:"Ich schlafe gut, flach, mit einem Kissen.",stuhl:"Normal.",wasser:"Normal.",fieber:"Nein."}},
 brief:"Herr Petrović ist ein 69-jähriger Patient, der sich nach einer Synkope unter Belastung vorstellte. Er berichtete, er habe am Vormittag zwei Einkaufstaschen in den dritten Stock getragen; oben habe er ein thorakales Engegefühl verspürt, dann sei ihm schwarz vor Augen geworden. Laut einer Nachbarin sei er etwa eine halbe Minute bewusstlos gewesen, ohne Zuckungen, und danach sofort wieder orientiert gewesen. Zungenbiss und Einnässen wurden verneint. In den letzten Wochen bestünden eine zunehmende Belastungsdyspnoe und zweimalig Schwindel beim Treppensteigen.\nAn Vorerkrankungen bestehen eine arterielle Hypertonie und eine Hypercholesterinämie; ein vor Jahren erwähntes Herzgeräusch sei nie abgeklärt worden. Z. n. Cholezystektomie. Medikation: Candesartan 16 mg 1-0-0, Atorvastatin 20 mg 0-0-1. Allergien sind nicht bekannt. Der Patient sei seit zehn Jahren Nichtraucher (30 Packungsjahre). Der Vater sei mit 72 Jahren plötzlich verstorben. Der Patient ist Busfahrer im Ruhestand, verheiratet und fährt regelmäßig Auto.\nDie Anamnese spricht für eine kardiale Belastungssynkope, am ehesten bei hochgradiger Aortenklappenstenose. Differenzialdiagnostisch kommen eine rhythmogene Synkope, eine Myokardischämie und eine Lungenembolie in Betracht. Wir empfehlen: Monitoring, 12-Kanal-EKG, Labor mit Troponin, zeitnahe Echokardiographie, die stationäre Aufnahme mit Telemetrie, ein kardiologisches Konsil und die Aufklärung über das Fahrverbot bis zur Abklärung.",
 kw:[["Belastung|unter Anstrengung","im Liegen|ohne Prodrom|keine Vorzeichen","Brustschmerz|Palpitation|Herzrasen","Herzerkrankung|EKG.{0,20}auffällig|strukturell","plötzlicher Herztod|Familienanamnese"],["Systolikum|systolisches","Karotiden|Fortleitung","zweiter Herzton|2\\. Herzton|abgeschwächt","rau|spindelförmig|Crescendo","Pulsus parvus|tardus"],["Vorlast","Blutdruckabfall|Hypotonie|Kollaps","fixiert|Auswurf.{0,15}nicht steigern|Herzzeitvolumen","Koronarperfusion|Synkope"]],
 terms:["Synkope","Aortenklappenstenose","Belastungsdyspnoe","Systolikum","Echokardiographie"]},

fx4:{vn:"Leon",geb:"21.09.2024",cm:88,kg:11.6,ha:"Frau Doktor Öztürk in Mannheim-Neckarstadt",sys:"paed",
 vit:"HF 148/min · AF 34/min · RR 88/54 mmHg · SpO₂ 98 % · Temp. 38,3 °C · Rekap-Zeit 3 s · Gewicht 11,6 kg (U7: 12,4 kg)",
 lay:{open:"Leon hat seit gestern Durchfall und spuckt alles wieder aus. Heute ist er ganz schlapp, und die Windel ist fast trocken.",
  name:"Ich bin der Vater, Emre Kaya. Mein Sohn heißt Leon Kaya.",dob:"Leon ist am einundzwanzigsten Neunten zweitausendvierundzwanzig geboren. Er ist gerade zwei geworden.",
  size:"Bei der letzten Untersuchung war er 88 Zentimeter groß und hat zwölf Kilo vierhundert gewogen. Das steht im gelben Heft.",
  pmh:"Nein, er war bisher immer gesund. Die Geburt war ganz normal, er kam pünktlich.",ops:"Nein, er ist noch nie operiert worden und war noch nie im Krankenhaus.",
  meds:"Er bekommt sonst nichts. Gestern habe ich ihm einmal ein Fieberzäpfchen gegeben.",all:"Nein, nichts bekannt.",
  vacc:"Er hat alle Impfungen, nur die Schluckimpfung gegen Rotaviren hat er damals nicht bekommen. Das Heft habe ich dabei.",
  fam:"Bei uns in der Familie gibt es nichts Besonderes.",nox:"Bei uns zu Hause raucht niemand.",drugs:"Nein, natürlich nicht.",
  soc:"Wir wohnen in Mannheim, er hat eine große Schwester, fünf Jahre. Er geht in die Kita, da haben gerade viele Kinder Magen-Darm. Ich bin Elektriker, meine Frau ist Verkäuferin.",
  char:"Ich glaube, der Bauch tut ihm weh, er zieht die Beine an und weint. Aber der Bauch ist weich.",mod:"Wenn er trinkt, kommt es nach ein paar Minuten wieder raus. In kleinen Schlucken habe ich es noch nicht probiert.",
  prev:"Er hatte schon mal einen Tag Durchfall, aber so schlimm war es noch nie.",self:"Nur das Fieberzäpfchen gestern Abend. Und wir haben ihm Tee und Apfelschorle angeboten.",reise:"Nein, wir waren nicht weg.",
  veg:{appetit:"Er will nichts essen und kaum trinken.",gewicht:"Zu Hause haben wir ihn nicht gewogen. Aber er kommt mir leichter vor.",stuhl:"Seit gestern Abend ganz wässrig, sechs-, siebenmal. Blut habe ich keins gesehen.",wasser:"Heute Morgen war die Windel fast trocken.",schlaf:"Er ist so müde, er schläft fast nur noch.",fieber:"Gestern Abend hatte er 38,5.",durst:"Er will nicht trinken, das ist ja das Problem."}},
 brief:"Leon Kaya ist ein zweijähriger Junge, der von seinem Vater mit seit dem Vortag bestehendem Erbrechen und wässrigen Durchfällen vorgestellt wurde. Der Vater berichtete, Leon habe etwa achtmal erbrochen und sechs- bis siebenmal wässrigen Stuhl ohne Blutbeimengung abgesetzt. Er verweigere das Trinken; seit dem Morgen sei die Windel nahezu trocken, das Kind sei schläfrig und weine ohne Tränen. Die Temperatur habe maximal 38,5 °C betragen. In der Kindertagesstätte seien derzeit mehrere Kinder an einer Gastroenteritis erkrankt.\nVorerkrankungen sind nicht bekannt; die Geburt sei termingerecht und komplikationslos gewesen. Voroperationen wurden verneint. Keine Dauermedikation; am Vortag einmalig Paracetamol-Zäpfchen 125 mg. Allergien sind nicht bekannt. Der Impfstatus sei laut Vater vollständig, mit Ausnahme der Rotavirus-Impfung. Die Familienanamnese ist unauffällig. Leon lebt mit den Eltern und einer fünfjährigen Schwester in einem Nichtraucherhaushalt.\nDie Anamnese und der Gewichtsverlust von 12,4 kg auf 11,6 kg sprechen für eine akute, am ehesten virale Gastroenteritis mit mittelschwerer Dehydratation. Differenzialdiagnostisch sind ein Harnwegsinfekt, eine Invagination und eine Appendizitis zu bedenken. Wir empfehlen: Blutzuckerkontrolle, orale Rehydratation mit einer Rehydratationslösung in kleinen Portionen, bei Misserfolg Rehydratation über eine Magensonde oder intravenös sowie eine Hygieneberatung der Eltern.",
 kw:[["Gewichtsverlust|Gewicht","Rekapillarisierung|Rekap","Schleimhäute|Tränen|Fontanelle|Hautturgor","Urin|Windel","Bewusstsein|Vigilanz|schläfrig","Herzfrequenz|Tachykardie"],["Studien|Leitlinie|gleich wirksam|gleichwertig","Glukose.{0,20}Natrium|Kotransport|Darm.{0,20}resorbiert","weniger Komplikationen|kein Zugang|Venenzugang","kleine Mengen|löffelweise|Spritze"],["gallig|grün","Blut im Stuhl|blutig","harter Bauch|Abwehrspannung|Invagination","Bewusstseinsstörung|Lethargie|Nackensteifigkeit","hohes Fieber|Schock"]],
 terms:["Gastroenteritis","Dehydratation","Rehydratation","Rekapillarisierungszeit","Invagination"]},

fx5:{vn:"Petra",geb:"12.12.1962",cm:164,kg:92,ha:"Herr Doktor Brandl in Kassel",sys:"derma",scale:6,
 vit:"RR 136/82 mmHg · HF 104/min · AF 18/min · SpO₂ 97 % · Temp. 38,9 °C · BZ 236 mg/dl",
 lay:{open:"Mein linkes Bein ist seit zwei Tagen knallrot, heiß und tut weh. Und ich habe Fieber.",
  pmh:"Ich habe Zucker und schwache Venen in beiden Beinen. Und vor drei Jahren hatte ich so eine Rose schon einmal, am rechten Bein. Dass ich zu viel wiege, weiß ich selbst.",ops:"Nein, operiert worden bin ich noch nie.",
  meds:"Zwei verschiedene Zuckertabletten, Metformin morgens und abends und noch eine morgens. Stützstrümpfe habe ich auch, aber ehrlich gesagt ziehe ich die selten an.",
  all:"Als Kind habe ich nach einem Penicillin-Saft einen Ausschlag bekommen. Seitdem heißt es, ich bin allergisch, aber getestet hat das nie jemand.",
  fam:"Meine Mutter hatte ein offenes Bein. Mein Vater hatte Zucker.",nox:"Ich rauche zehn Zigaretten am Tag, seit vierzig Jahren. Am Wochenende trinke ich ein Glas Wein oder zwei.",drugs:"Nein.",
  soc:"Ich bin Friseurin, ich stehe den ganzen Tag. Ich bin verheiratet.",
  char:"Es brennt und spannt, als ob die Haut zu eng wäre.",rad:"Nein, es ist nur am Unterschenkel.",
  mod:"Wenn ich das Bein herunterhängen lasse, pocht und schmerzt es. Hochlegen und Kühlen tut gut.",prev:"Ja, vor drei Jahren am anderen Bein. Damals habe ich Antibiotika bekommen.",
  self:"Ich habe gekühlt und eine Ibuprofen genommen. Besser ist es nicht geworden.",vacc:"Das weiß ich nicht genau. Tetanus ist bestimmt zehn Jahre her.",reise:"Nein.",
  veg:{appetit:"Wenig, seit ich Fieber habe.",gewicht:"Das ist gleich geblieben.",schlaf:"Letzte Nacht schlecht, wegen dem Schüttelfrost.",stuhl:"Normal.",wasser:"Normal.",fieber:"Gestern Abend hatte ich 39 Grad und Schüttelfrost.",durst:"Ich habe etwas mehr Durst als sonst."},
  gyn:"Die Wechseljahre habe ich hinter mir. Ich habe keine Kinder."},
 brief:"Frau Krüger ist eine 63-jährige Patientin, die sich mit einer seit zwei Tagen bestehenden schmerzhaften Rötung und Überwärmung des linken Unterschenkels vorstellte. Sie berichtete, die Rötung habe am Schienbein begonnen und sich rasch auf nahezu den gesamten Unterschenkel ausgebreitet; die Ränder seien scharf begrenzt. Am Vorabend habe sie Fieber von 39 °C und Schüttelfrost gehabt. Zwischen den Zehen bestehe seit Monaten eine juckende, eingerissene Haut, die nie behandelt worden sei. Luftnot und Wadenschmerzen wurden verneint.\nAn Vorerkrankungen bestehen eine Adipositas, ein Diabetes mellitus Typ 2 und eine chronische venöse Insuffizienz beidseits; Z. n. Erysipel rechts vor drei Jahren. Voroperationen wurden verneint. Medikation: Metformin 1000 mg 1-0-1, Sitagliptin 100 mg 1-0-0; Kompressionsstrümpfe würden selten getragen. Die Patientin gab eine fragliche Penicillinallergie an (Exanthem in der Kindheit, nie abgeklärt). Sie rauche zehn Zigaretten pro Tag und trinke am Wochenende Alkohol. Die Mutter habe an einem Ulcus cruris gelitten. Die Patientin ist Friseurin mit stehender Tätigkeit und verheiratet.\nDie Anamnese spricht für ein Erysipel des linken Unterschenkels mit Eintrittspforte bei Tinea pedis. Differenzialdiagnostisch kommen eine tiefe Beinvenenthrombose, eine Phlegmone und eine nekrotisierende Fasziitis in Betracht. Wir empfehlen: Markierung der Rötung, Labor und Blutkulturen, gegebenenfalls Kompressionssonographie, intravenöse Antibiose (bei unklarer Allergie Cefazolin), Hochlagerung und Kühlung, Thromboseprophylaxe sowie die Behandlung der Fußmykose.",
 kw:[["scharf begrenzt|flammend","Fieber|Schüttelfrost","Thrombose.{0,60}(Schwellung|Wade|Sonograph|keine Rötung)|Kompressionssonograph","Schmerz.{0,30}(außer Verhältnis|unverhältnismäßig|stärkste)|Fasziitis.{0,60}Schmerz","Nekrosen|Blasen|Krepitation|septisch|chirurgisch"],["genau.{0,15}(erfragen|Anamnese)|Reaktionstyp|welche Reaktion","keine Anaphylaxie|nur Exanthem|Ausschlag","Cephalosporin|Cefazolin","Testung|Allergolog|abklären"],["Fußpilz|Tinea|Eintrittspforte","Kompression|Strümpfe","Hautpflege","Blutzucker|Diabetes.{0,15}einstell","Gewicht|Lymphödem|Rezidivprophylaxe"]],
 terms:["Erysipel","Tinea pedis","Phlegmone","venöse Insuffizienz","Rezidiv"]},

fx6:{vn:"Andreas",geb:"03.03.1980",cm:180,kg:90,ha:"Herr Doktor Nowak in Dortmund-Hörde",sys:"nephro-uro",scale:9,
 vit:"RR 158/94 mmHg · HF 102/min · AF 20/min · SpO₂ 98 % · Temp. 36,8 °C · NRS 9/10",
 lay:{open:"Ich habe seit drei Stunden wahnsinnige Schmerzen hier rechts in der Seite. Das kommt in Wellen und zieht bis in die Leiste.",
  pmh:"Ich hatte vor zwei Jahren einen Gichtanfall im großen Zeh. Die Harnsäure ist zu hoch, sagt der Hausarzt. Sonst bin ich gesund.",ops:"Nein, noch nie.",
  meds:"Ich soll morgens eine Tablette gegen die Harnsäure nehmen. Ehrlich gesagt vergesse ich die oft.",all:"Nein, keine.",
  fam:"Mein Vater hatte Nierensteine, mehrmals.",nox:"Ich rauche nicht. Abends trinke ich zwei, drei Bier.",drugs:"Nein.",
  soc:"Ich bin Kfz-Mechatroniker. Ich bin verheiratet und habe zwei Kinder. In der Werkstatt ist es im Sommer heiß, und ich trinke zu wenig.",
  char:"Es ist ein krampfartiger Schmerz, der kommt und geht. Wenn er kommt, weiß ich nicht, wohin mit mir.",rad:"Ja, er zieht nach vorne in die Leiste und bis in den Hoden.",
  mod:"Es hilft gar nichts, keine Lage ist gut. Ich muss die ganze Zeit herumlaufen.",prev:"Nein, so etwas hatte ich noch nie. Nur die Gicht damals im Zeh.",
  self:"Ich habe heute früh eine Ibuprofen genommen, die habe ich aber gleich wieder erbrochen.",vacc:"Ja, alles, was man braucht.",reise:"Nein.",
  veg:{appetit:"Im Moment kann ich nicht ans Essen denken.",gewicht:"Unverändert.",wasser:"Vorhin war der Urin rötlich. Brennen tut es nicht.",stuhl:"Normal, gestern zuletzt.",schlaf:"Bis heute früh um fünf habe ich gut geschlafen.",fieber:"Gemessen habe ich nicht, aber ich glaube nicht.",durst:"Ich trinke zu wenig, das weiß ich."}},
 brief:"Herr Schulz ist ein 46-jähriger Patient, der sich mit seit drei Stunden bestehenden heftigsten, kolikartigen Schmerzen in der rechten Flanke vorstellte. Er berichtete, die Schmerzen hätten gegen fünf Uhr morgens plötzlich begonnen, träten wellenförmig auf und strahlten in die rechte Leiste und den Hoden aus. Er könne nicht still liegen. Begleitend habe er zweimal erbrochen und eine rötliche Verfärbung des Urins bemerkt. Fieber und Dysurie wurden verneint. Die Trinkmenge sei bei der Arbeit gering. Die Schmerzstärke wurde mit 9/10 angegeben.\nAn Vorerkrankungen bestehen eine Hyperurikämie und ein Gichtanfall vor zwei Jahren. Voroperationen wurden verneint. Medikation: Allopurinol 100 mg 1-0-0, das unregelmäßig eingenommen werde. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint; der Patient trinke abends zwei bis drei Bier. Der Vater habe an Nierensteinen gelitten. Der Patient ist Kfz-Mechatroniker, verheiratet und hat zwei Kinder.\nDie Anamnese spricht für eine Nierenkolik rechts bei Urolithiasis, möglicherweise bei einem Harnsäurestein. Differenzialdiagnostisch kommen eine Pyelonephritis, eine Appendizitis, eine Hodentorsion und ein rupturiertes Bauchaortenaneurysma in Betracht. Wir empfehlen: Analgesie mit einem NSAR oder Metamizol, Urinstatus, Labor mit Kreatinin und Harnsäure, Sonographie, bei unklarem Befund eine native Niedrigdosis-CT, anschließend Tamsulosin und eine urologische Vorstellung.",
 kw:[["Fieber|Infekt|infizierte Harnstauung","Einzelniere|beidseits|Anurie","Nierenversagen|Kreatinin","nicht beherrschbar|therapierefraktär","Harnleiterschiene|Doppel-J|Nephrostomie|Entlastung"],["Aortenaneurysma|Bauchaorta|BAA","rupturiert|Ruptur","Sonograph|CT"],["Harnsäure|Urat","röntgennegativ|nicht schattengebend|nicht sichtbar","Gicht|Hyperurikämie","CT|Sonograph","Alkalisierung|Urin-pH|Litholyse"]],
 terms:["Urolithiasis","Nierenkolik","Hämaturie","Hyperurikämie","Harnstau"]},

fx7:{vn:"Ingrid",geb:"25.06.1945",cm:160,kg:71,ha:"Herr Doktor Lorenz in Würzburg",sys:"kardio",
 vit:"RR 168/96 mmHg · HF 128/min, arrhythmisch · AF 26/min · SpO₂ 88 % · Temp. 36,7 °C",
 lay:{open:"Ich bekomme seit fünf Tagen immer schlechter Luft, nachts kann ich nur noch im Sitzen schlafen. Die Beine sind dick, und das Herz rast.",
  pmh:"Ich habe ein schwaches Herz, das weiß ich seit ein paar Jahren. Dazu hohen Blutdruck, und die Nieren sind nicht mehr die besten. Und beide Knie sind verschlissen.",ops:"Nein, operiert worden bin ich nie. Die Knie wollte man machen, aber ich habe mich nicht getraut.",
  meds:"Eine Wassertablette, eine neue Herztablette, eine für den Blutdruck und eine, die das Herz langsamer macht. Die Wassertablette habe ich aber seit einer Woche weggelassen. Und für die Knie nehme ich Ibuprofen, zuletzt fast jeden Tag.",
  all:"Nein, keine.",fam:"Meine Mutter hatte auch ein schwaches Herz.",nox:"Ich rauche nicht. Alkohol trinke ich gar nicht.",drugs:"Nein, wo denken Sie hin.",
  soc:"Ich war Hauswirtschaftslehrerin. Ich bin Witwe und lebe allein, im Erdgeschoss. Meine Tochter wohnt in der Nähe. Ich mache noch alles selbst.",
  mod:"Im Liegen ist es am schlimmsten, dann ringe ich nach Luft. Aufrecht sitzen hilft. Und jede Bewegung strengt mich an, sogar das Anziehen.",
  prev:"Dicke Beine hatte ich schon öfter. Aber so schlecht Luft habe ich noch nie bekommen.",self:"Nein. Die Wassertablette habe ich ja gerade weggelassen, weil ich zum Geburtstag meiner Enkelin wollte.",
  vacc:"Grippe und Corona, ja, immer.",reise:"Nein, nur zum Geburtstag nach Nürnberg, mit dem Zug.",
  veg:{appetit:"Wenig, ich habe ein Völlegefühl.",gewicht:"Ich habe drei Kilo mehr auf der Waage als letzte Woche.",schlaf:"Ich brauche drei Kissen, sonst wache ich auf und kriege keine Luft.",stuhl:"Normal.",wasser:"Seit ich die Wassertablette weglasse, muss ich viel seltener. Nachts aber zweimal.",fieber:"Nein.",durst:"Wegen der Hitze habe ich viel getrunken."},
  gyn:"Das ist lange vorbei. Ich habe eine Tochter."},
 brief:"Frau Becker ist eine 81-jährige Patientin, die sich mit seit fünf Tagen zunehmender Dyspnoe vorstellte. Sie berichtete, die Luftnot sei zunächst nur beim Treppensteigen, inzwischen bereits beim Anziehen aufgetreten; nachts könne sie nur noch mit drei Kissen schlafen. Die Beine seien geschwollen, und sie habe drei Kilogramm zugenommen. Seit Tagen bestünden Herzrasen und Herzstolpern. Die Patientin gab an, sie habe das Diuretikum seit einer Woche nicht eingenommen und wegen Knieschmerzen fast täglich Ibuprofen genommen. Brustschmerzen und Fieber wurden verneint.\nAn Vorerkrankungen bestehen eine Herzinsuffizienz mit erhaltener Ejektionsfraktion, eine arterielle Hypertonie, eine chronische Niereninsuffizienz Stadium 3a und eine Gonarthrose beidseits. Voroperationen wurden verneint. Medikation: Torasemid 10 mg 1-0-0 (pausiert), Empagliflozin 10 mg 1-0-0, Ramipril 5 mg 1-0-0, Bisoprolol 2,5 mg 1-0-0, Ibuprofen 400 mg bei Bedarf. Allergien sind nicht bekannt. Nikotin- und Alkoholkonsum wurden verneint. Die Mutter habe ebenfalls an einer Herzinsuffizienz gelitten. Die Patientin ist verwitwet und lebt selbstständig allein.\nDie Anamnese spricht für eine akut dekompensierte Herzinsuffizienz, ausgelöst durch das Absetzen des Diuretikums, die NSAR-Einnahme und ein mögliches neu aufgetretenes tachykardes Vorhofflimmern. Differenzialdiagnostisch kommen ein akutes Koronarsyndrom, eine Pneumonie und eine Lungenembolie in Betracht. Wir empfehlen: Oberkörperhochlagerung, Sauerstoffgabe, Furosemid intravenös, EKG, Labor mit Troponin und NT-proBNP, Röntgen-Thorax, Echokardiographie, das Absetzen von Ibuprofen und die Prüfung einer Antikoagulation.",
 kw:[["Medikamente.{0,30}(abgesetzt|Adhärenz|nicht genommen)|Adhärenz|Diuretikum","Rhythmus|Vorhofflimmern","Ischämie|Infarkt|Koronar","Infekt|Pneumonie","NSAR|Ibuprofen","Trinkmenge|Salz|Hypertonie|Anämie|Schilddrüse"],["Natrium|Wasserretention|Flüssigkeitsretention","Nierenfunktion|Nierendurchblutung|Prostaglandin","Wirkung.{0,25}(Diuretika|ACE-Hemmer).{0,20}(abschwäch|vermindert)|Triple Whammy","Blutdruck"],["CHA2DS2-VASc|CHA2DS2","Alter|weiblich|Hypertonie|Herzinsuffizienz","Blutungsrisiko|HAS-BLED","DOAK|Apixaban|Edoxaban","Nierenfunktion|Dosis"]],
 terms:["Herzinsuffizienz","Orthopnoe","Ödem","Vorhofflimmern","Diuretikum"]},

fx8:{vn:"Stefan",geb:"17.01.1977",cm:182,kg:95,ha:"Frau Doktor Albrecht in Hannover-List",sys:"gi",scale:9,
 vit:"RR 104/66 mmHg · HF 116/min · AF 22/min · SpO₂ 95 % · Temp. 38,0 °C",
 lay:{open:"Ich habe seit gestern Nacht ganz schlimme Schmerzen im Oberbauch, wie ein Gürtel, bis in den Rücken. Und ich muss mich ständig übergeben.",
  pmh:"Ich habe hohen Blutdruck. Und vor zwei Jahren hat man im Ultraschall gesehen, dass die Leber verfettet ist. Die Blutfette sind auch zu hoch.",ops:"Nein, operiert worden bin ich noch nie.",
  meds:"Nur eine Blutdrucktablette am Morgen.",all:"Nein, keine.",fam:"Mein Vater ist an einer Leberzirrhose gestorben, er hat getrunken. Meine Mutter hat Gallensteine.",
  nox:"Ich rauche, ungefähr fünfzehn Zigaretten am Tag. Und ich trinke jeden Abend drei, vier Bier, am Wochenende mehr. Das letzte war gestern gegen elf.",drugs:"Nein, Drogen nehme ich nicht.",
  soc:"Ich bin Vertriebsleiter und viel unterwegs. Ich bin geschieden und lebe allein.",
  char:"Es ist ein bohrender, ganz tiefer Schmerz, der nicht weggeht.",rad:"Ja, er zieht wie ein Gürtel nach beiden Seiten und in den Rücken.",
  mod:"Vorgebeugt sitzen geht noch am besten. Flach auf dem Rücken liegen kann ich gar nicht. Nach dem Erbrechen wird es auch nicht besser.",
  prev:"Vor einem Jahr hatte ich so etwas schon einmal, aber viel schwächer. Da bin ich nicht zum Arzt gegangen.",self:"Ich habe heute Nacht eine Schmerztablette genommen, Ibuprofen. Die hat nichts gebracht.",
  vacc:"Das Übliche. Für die Dienstreisen habe ich Hepatitis A und B.",reise:"Nur dienstlich in Deutschland unterwegs.",
  veg:{appetit:"Ich habe seit gestern nichts im Magen behalten.",gewicht:"Unverändert, eher zu viel.",stuhl:"Seit gestern hatte ich keinen Stuhlgang, der Bauch ist aufgebläht.",wasser:"Der Urin ist dunkel, ich habe wenig getrunken.",schlaf:"Heute Nacht habe ich gar nicht geschlafen.",fieber:"Ich fühle mich heiß, gemessen habe ich nicht.",durst:"Ja, aber alles kommt wieder raus."}},
 brief:"Herr Wolff ist ein 49-jähriger Patient, der sich mit seit der vergangenen Nacht bestehenden stärksten, gürtelförmigen Oberbauchschmerzen mit Ausstrahlung in den Rücken vorstellte. Er berichtete, die Beschwerden hätten nach einer Betriebsfeier mit reichlichem Essen und Alkoholkonsum begonnen. Er habe mehrfach erbrochen, ohne dass eine Besserung eingetreten sei; in vornübergebeugter Haltung seien die Schmerzen am erträglichsten. Die Schmerzstärke wurde mit 9/10 angegeben. Eine ähnliche, schwächere Episode habe es vor einem Jahr gegeben. Seit dem Vortag habe er keinen Stuhlgang gehabt.\nAn Vorerkrankungen bestehen eine arterielle Hypertonie, eine Steatosis hepatis und eine Hypertriglyzeridämie. Voroperationen wurden verneint. Medikation: Amlodipin 10 mg 1-0-0. Allergien sind nicht bekannt. Der Patient rauche 15 Zigaretten pro Tag und trinke täglich drei bis vier Bier, zuletzt am Vorabend gegen 23 Uhr. Der Vater sei an einer äthyltoxischen Leberzirrhose verstorben, die Mutter leide an Gallensteinen. Der Patient ist Vertriebsleiter, geschieden und lebt allein.\nDie Anamnese spricht für eine akute, am ehesten alkoholtoxische Pankreatitis. Differenzialdiagnostisch kommen eine biliäre Pankreatitis, ein perforiertes Ulkus, ein Hinterwandinfarkt und eine Mesenterialischämie in Betracht. Wir empfehlen: Labor mit Lipase, Leberwerten, Triglyzeriden, Kalzium und Laktat, EKG und Troponin, Abdomensonographie, kontrollierte Volumengabe, Analgesie, frühe orale Ernährung nach Verträglichkeit und eine Überwachung auf Alkoholentzugssymptome.",
 kw:[["zwei von drei|2 von 3","typischer Schmerz|gürtelförmig","Lipase.{0,25}(dreifach|3-fach|3fach)|dreifach","Bildgebung|Sonograph","CT.{0,50}(nicht sofort|erst|72|48|unklar|Komplikation)|kein CT"],["biliär.{0,60}(ERCP|Cholangitis|Stein)|ERCP","Cholezystektomie","Alkoholkarenz|Abstinenz|Entzug","Rezidiv"],["Entzug|Entzugssyndrom","Delir|Krampfanfall","Tremor|Schwitzen|Unruhe|Tachykardie","Benzodiazepin|Lorazepam|Diazepam|Clomethiazol","Thiamin|Vitamin B1","CIWA|Score|überwach"]],
 terms:["Pankreatitis","Lipase","Steatosis hepatis","Alkoholentzug","Emesis"]},

fx9:{vn:"David",geb:"09.05.2007",cm:185,kg:76,ha:"Herr Doktor Petersen in Bremen-Walle",sys:"infekt",scale:9,
 vit:"RR 102/60 mmHg · HF 124/min · AF 24/min · SpO₂ 96 % · Temp. 39,6 °C · GCS 14",
 lay:{open:"Ich habe seit heute Mittag Kopfschmerzen wie noch nie, hohes Fieber, und ich kann den Kopf nicht mehr nach vorne beugen.",
  pmh:"Nein, ich bin gesund. Ich war noch nie richtig krank.",ops:"Nein, noch nie.",
  meds:"Ich nehme normalerweise nichts. Heute habe ich zweimal eine Ibuprofen genommen.",all:"Nein, keine.",
  vacc:"Meine Mutter sagt, ich habe alles bekommen, was die Kinderärztin gemacht hat. Den Impfpass habe ich nicht dabei, ich weiß nicht, was da drinsteht.",
  fam:"In meiner Familie sind alle gesund.",nox:"Ich rauche nicht. Am Wochenende trinke ich mit den Jungs ein paar Bier.",drugs:"Ab und zu mal einen Joint, auf einer Party. Sonst nichts.",
  soc:"Ich mache eine Ausbildung zum Industriemechaniker. Ich wohne im Wohnheim, wir sind zu viert auf dem Zimmer. Ich habe eine Freundin.",
  char:"Es ist ein Druck im ganzen Kopf, als ob er gleich platzt.",rad:"Es zieht in den Nacken, der ist ganz steif.",
  mod:"Licht ist unerträglich, und wenn ich den Kopf bewege, wird es schlimmer. Im dunklen Zimmer still liegen ist am besten. Die Tabletten haben nichts geholfen.",
  prev:"Nein, noch nie. Ich habe sonst fast nie Kopfschmerzen.",self:"Zweimal Ibuprofen, das hat nichts gebracht.",
  reise:"Nein, ich war nicht weg. Bei uns im Wohnheim ist aber, glaube ich, noch einer krank.",
  veg:{appetit:"Mir ist dauernd schlecht, ich habe nichts gegessen.",gewicht:"Gleich.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Ich will nur schlafen, ich bin total müde.",fieber:"Vorhin waren es fast 40 Grad."}},
 brief:"Herr Okafor ist ein 19-jähriger Patient, der sich mit seit dem Mittag bestehenden stärksten Kopfschmerzen, Fieber bis 40 °C und Nackensteifigkeit vorstellte. Er berichtete, die Kopfschmerzen seien die stärksten seines Lebens (9/10); begleitend bestünden Übelkeit und eine ausgeprägte Lichtscheu. Am Nachmittag habe er an den Beinen kleine rote Punkte bemerkt, die am Morgen noch nicht vorhanden gewesen seien. Laut einem Freund spreche er verlangsamt. Zweimalig eingenommenes Ibuprofen habe keine Besserung gebracht. Ein Trauma und ein Auslandsaufenthalt wurden verneint.\nVorerkrankungen und Voroperationen sind nicht bekannt. Keine Dauermedikation. Allergien sind nicht bekannt. Der Impfstatus ist unklar, der Impfausweis liegt nicht vor. Nikotinkonsum wurde verneint; der Patient trinke am Wochenende Alkohol und konsumiere gelegentlich Cannabis. Die Familienanamnese ist unauffällig. Er ist Auszubildender und lebt in einem Wohnheim mit Mehrbettzimmern.\nDie Anamnese deutet auf eine bakterielle Meningitis, am ehesten durch Meningokokken, mit beginnender Bewusstseinsstörung hin. Differenzialdiagnostisch kommen eine virale Meningoenzephalitis, eine Subarachnoidalblutung und eine Sepsis anderer Ursache in Betracht. Wir empfehlen: sofortige Isolierung, Blutkulturen, Dexamethason und unmittelbar anschließend Ceftriaxon plus Ampicillin, danach Lumbalpunktion (bei Bewusstseinsstörung zuvor cCT), die Meldung an das Gesundheitsamt und die Chemoprophylaxe enger Kontaktpersonen.",
 kw:[["Zeit|Verzögerung|Prognose|Letalität","Blutkulturen.{0,20}vor|nach.{0,15}Blutkulturen","CT.{0,60}(Bewusstsein|fokal|Krampf|Hirndruck|Immunsuppression)|Bewusstseinsstörung","Herniation|Einklemmung"],["Entzündung|Hirnödem","Hörschäden|Letalität|Komplikationen|Pneumokokken","vor oder mit|gleichzeitig|vor der ersten"],["Gesundheitsamt|Meldepflicht|melden","enge Kontaktpersonen|Haushalt|Zimmer|Freundin","Rifampicin|Ciprofloxacin|Ceftriaxon","Personal.{0,40}(Intubation|Absaugen|ungeschützt)|Isolierung"]],
 terms:["Meningitis","Meningismus","Petechien","Photophobie","Lumbalpunktion"]},

fx10:{vn:"Michael",geb:"28.02.1982",cm:181,kg:78,ha:"Frau Doktor Sommer in Neu-Ulm",sys:"psych",
 vit:"RR 132/84 mmHg · HF 82/min · AF 14/min · SpO₂ 98 % · Temp. 36,6 °C",
 lay:{open:"Meine Frau wollte, dass ich herkomme. Mir geht es seit Wochen schlecht, und in den letzten Tagen denke ich, dass ich nicht mehr leben will.",
  pmh:"Körperlich bin ich gesund. Vor acht Jahren, nach dem Tod meines Vaters, hatte ich schon einmal eine Depression. Damals war ich bei einer Therapeutin.",ops:"Nein, noch nie.",
  meds:"Ich nehme keine Medikamente. Abends nehme ich seit Wochen Baldrian, aber der hilft nicht.",all:"Nein, keine.",
  fam:"Mein Vater hatte Depressionen. Er hat sich mit 58 das Leben genommen.",
  nox:"Ich rauche nicht. Aber ich trinke in letzter Zeit zu viel, abends ungefähr eine Flasche Wein. Sonst kann ich nicht abschalten.",drugs:"Nein, Drogen nehme ich keine.",
  soc:"Ich bin Bauingenieur. Vor zwei Monaten ist mir gekündigt worden. Ich bin verheiratet, wir haben zwei Kinder, neun und zwölf, und ein Haus bei Ulm.",
  mod:"Morgens ist es am schlimmsten. Gegen Abend wird es ein bisschen leichter. Es gibt nichts, was wirklich hilft.",prev:"Ja, vor acht Jahren. Aber solche Gedanken wie jetzt hatte ich damals nicht.",
  self:"Nur den Baldrian. Und den Wein, wenn ich ehrlich bin.",vacc:"Ja, ich bin geimpft.",reise:"Nein.",
  suiz:"Ich denke oft, dass es für alle besser wäre, wenn ich nicht mehr da wäre. Einen Plan habe ich nicht, und ich habe auch noch nie versucht, mir etwas anzutun. Aber die Gedanken werden lauter, und das macht mir Angst.",
  veg:{appetit:"Ich habe kaum Appetit, ich esse nur, weil meine Frau darauf besteht.",gewicht:"Ich habe bestimmt vier Kilo abgenommen.",schlaf:"Ich schlafe kaum. Um vier Uhr bin ich wach und grüble.",stuhl:"Normal.",wasser:"Normal.",fieber:"Nein."}},
 brief:"Herr Jansen ist ein 44-jähriger Patient, der in Begleitung seiner Ehefrau mit seit etwa drei Monaten zunehmender gedrückter Stimmung vorgestellt wurde. Er berichtete, er könne sich über nichts mehr freuen, schlafe kaum, erwache gegen vier Uhr morgens und grüble; seit dem Verlust seines Arbeitsplatzes fühle er sich als Versager. In den letzten Tagen habe er zunehmend den Gedanken, dass es für alle besser wäre, wenn er nicht mehr da wäre. Konkrete Pläne oder Vorbereitungen wurden verneint, ebenso frühere Suizidversuche; die Gedanken würden jedoch drängender und machten ihm Angst. Appetit und Gewicht seien vermindert.\nAn Vorerkrankungen ist eine depressive Episode vor acht Jahren bekannt, die ambulant psychotherapeutisch behandelt worden sei. Voroperationen wurden verneint. Keine Dauermedikation; abends Baldrian ohne Wirkung. Allergien sind nicht bekannt. Der Patient sei Nichtraucher, trinke seit einigen Wochen jedoch etwa eine Flasche Wein pro Abend; Drogenkonsum wurde verneint. Der Vater habe an Depressionen gelitten und sich mit 58 Jahren suizidiert. Der Patient ist Bauingenieur, seit zwei Monaten arbeitslos, verheiratet und hat zwei Kinder.\nEs besteht der Verdacht auf eine schwere depressive Episode mit akuter Suizidalität. Differenzialdiagnostisch kommen eine Anpassungsstörung, eine bipolare Störung, eine alkoholbedingte Störung und eine organische Ursache wie eine Hypothyreose in Betracht. Wir empfehlen: den Patienten nicht allein zu lassen, eine körperliche Untersuchung und ein Basislabor mit TSH, ein psychiatrisches Konsil und die stationäre Aufnahme auf freiwilliger Basis.",
 kw:[["direkt|offen|konkret","Gedanken.{0,40}Pläne|Pläne|Vorbereitungen","erhöht.{0,25}nicht|nicht erhöht|kein erhöhtes|entlastet|Entlastung","frühere Versuche|Suizidversuch"],["männlich","Arbeitsplatzverlust|Kündigung|arbeitslos","Alkohol","Familie|Suizid des Vaters|familiär","frühere Depression|Vorgeschichte","Kinder|Ehefrau|Hilfe sucht|Schutzfaktor"],["nicht allein lassen|überwachen","Psychiater|psychiatrisch","Eigengefährdung|akute Gefahr","PsychKHG|Unterbringung|richterlich|gegen den Willen","dokumentier"]],
 terms:["Depression","Suizidalität","Anhedonie","Insomnie","Antidepressivum"]},

fx11:{vn:"Selin",geb:"05.11.1995",cm:167,kg:79,ha:"Frau Doktor Weiß in Leipzig-Gohlis",sys:"gyn",scale:6,
 vit:"RR 172/112 mmHg · HF 96/min · AF 18/min · SpO₂ 97 % · Temp. 36,8 °C · Urin-Stix: Eiweiß +++",
 lay:{open:"Ich bin in der 33. Woche schwanger. Seit heute Morgen habe ich Schmerzen rechts oben im Bauch, Kopfschmerzen und so ein Flimmern vor den Augen.",
  pmh:"Nein, ich war immer gesund. Auch die Schwangerschaft war bis jetzt ganz normal, nur der Blutdruck war beim letzten Mal ein bisschen hoch.",ops:"Nein, ich bin noch nie operiert worden.",
  meds:"Folsäure, Jod und Eisentabletten, die hat mir die Frauenärztin aufgeschrieben. Heute habe ich zweimal eine Paracetamol genommen.",all:"Nein, keine.",
  fam:"Meine Mutter hatte in ihrer ersten Schwangerschaft auch zu hohen Blutdruck, eine Schwangerschaftsvergiftung hat man das genannt. Mein Vater hat hohen Blutdruck.",
  nox:"Ich rauche nicht, und seit ich schwanger bin, trinke ich keinen Tropfen Alkohol.",drugs:"Nein, nie.",
  soc:"Ich bin Grundschullehrerin, im Moment bin ich schon im Mutterschutz. Ich bin verheiratet.",
  char:"Es ist ein starker Druck unter den Rippen, rechts.",rad:"Ja, es strahlt nach hinten in den Rücken aus.",
  mod:"Es ist die ganze Zeit da, egal wie ich liege. Die Kopfschmerzen gehen auch mit Paracetamol nicht weg.",prev:"Nein, das ist ganz neu. Ich hatte in der Schwangerschaft bisher keine Probleme.",
  self:"Zweimal Paracetamol, 500 Milligramm. Es hat nicht geholfen.",vacc:"Ich habe alle Impfungen, auch Keuchhusten und Grippe in der Schwangerschaft.",reise:"Nein.",
  veg:{appetit:"Mir ist etwas übel, ich habe heute kaum gegessen.",gewicht:"Ich habe in den letzten zwei Wochen drei Kilo zugenommen, das kam mir viel vor. Die Hände und das Gesicht sind geschwollen, der Ehering passt nicht mehr.",stuhl:"Normal.",wasser:"Ich muss oft, aber das ist in der Schwangerschaft ja so. Es brennt nicht.",schlaf:"Ich schlafe schlecht, wegen dem Bauch.",fieber:"Nein, Fieber habe ich nicht."},
  gyn:"Es ist meine erste Schwangerschaft, ich bin in der 33. Woche. Die letzte Vorsorge war vor zwei Wochen. Das Baby bewegt sich, aber weniger als sonst. Blutungen oder Wehen habe ich nicht."},
 brief:"Frau Arslan ist eine 31-jährige Erstgravida in der 33. Schwangerschaftswoche, die sich mit seit dem Morgen bestehenden rechtsseitigen Oberbauchschmerzen, Kopfschmerzen und Augenflimmern vorstellte. Sie berichtete, die Schmerzen seien drückend und strahlten in den Rücken aus; die Kopfschmerzen hätten sich auf Paracetamol nicht gebessert. In den letzten Tagen seien Hände und Gesicht angeschwollen, und sie habe in zwei Wochen drei Kilogramm zugenommen. Die Kindsbewegungen seien vorhanden, jedoch vermindert. Blutungen, Wehen und ein Fruchtwasserabgang wurden verneint. Bei der letzten Vorsorge vor zwei Wochen sei der Blutdruck grenzwertig erhöht gewesen.\nVorerkrankungen und Voroperationen sind nicht bekannt; der bisherige Schwangerschaftsverlauf sei laut Mutterpass unauffällig gewesen. Medikation: Folsäure, Jodid, Eisen; am Aufnahmetag zweimal Paracetamol 500 mg. Allergien sind nicht bekannt. Nikotin- und Alkoholkonsum wurden verneint. Die Mutter habe in der ersten Schwangerschaft eine Präeklampsie gehabt. Die Patientin ist Grundschullehrerin und verheiratet.\nDie Anamnese, der Blutdruck von 172/112 mmHg und die Proteinurie sprechen für eine schwere Präeklampsie mit Verdacht auf ein HELLP-Syndrom. Differenzialdiagnostisch kommen eine Cholezystitis, eine akute Schwangerschaftsfettleber und eine Pyelonephritis in Betracht. Wir empfehlen: sofortige Hinzuziehung der Geburtshilfe, CTG, Labor mit Thrombozyten, Leberwerten und Hämolyseparametern, eine vorsichtige Blutdrucksenkung, Magnesium intravenös zur Krampfprophylaxe und die Verlegung in ein Perinatalzentrum.",
 kw:[["Blutdruck|160|110","Proteinurie|Eiweiß","Kopfschmerz|Sehstörung|Oberbauchschmerz|zentralnervös","Hämolyse|LDH|Haptoglobin","Leberwerte|Transaminasen|GOT|GPT","Thrombozyten|Thrombozytopenie"],["Krampfprophylaxe|Eklampsie|Krampfanfall","Reflexe|Patellarsehnenreflex","Atemfrequenz|Atemdepression","Urinausscheidung|Diurese","Calciumgluconat|Antidot"],["Plazenta|uteroplazentar|Durchblutung","Kind|fetal|Fetus","langsam|nicht unter|150|Zielbereich","Hirnblutung|mütterliches Risiko"]],
 terms:["Präeklampsie","Proteinurie","HELLP-Syndrom","Eklampsie","Kardiotokographie"]},

fx12:{vn:"Gertrud",geb:"14.07.1940",cm:156,kg:58,ha:"Herr Doktor Franke in Bamberg",sys:"endo",
 vit:"RR 146/78 mmHg · HF 84/min, arrhythmisch · AF 16/min · SpO₂ 96 % · Temp. 36,2 °C · BZ 38 → 126 mg/dl · GCS 14",
 lay:{open:"Ich weiß gar nicht genau, was passiert ist. Die Schwester vom Pflegedienst hat mich heute früh im Sessel gefunden, ich war wohl ganz durcheinander und nass geschwitzt.",
  pmh:"Ich habe seit fünfundzwanzig Jahren Zucker und muss spritzen. Die Nieren sind schwach, das Herz schlägt unregelmäßig, und die Knochen sind dünn, da ist mir schon ein Wirbel gebrochen. Mit dem Gedächtnis ist es auch nicht mehr wie früher.",
  ops:"Nein, operiert worden bin ich nie. Den Wirbel hat man nicht operiert.",
  meds:"Ich spritze morgens und abends Insulin, morgens vierundzwanzig Einheiten und abends sechzehn. Dann einen Blutverdünner morgens und abends, eine Herztablette, eine Wassertablette, einmal in der Woche eine Tablette für die Knochen und Vitamin D.",
  all:"Codein vertrage ich nicht, davon wird mir übel, und ich werde ganz wirr im Kopf.",fam:"Meine Eltern sind schon lange tot. Woran sie gestorben sind, weiß ich nicht mehr genau.",
  nox:"Ich habe nie geraucht, und Alkohol trinke ich nicht.",drugs:"Nein, aber nein.",
  soc:"Ich war Buchhalterin. Mein Mann ist gestorben, ich wohne allein in meiner Wohnung. Zweimal am Tag kommt der Pflegedienst und schaut nach dem Zucker. Mein Sohn ruft jeden Tag an.",
  mod:"Ich habe seit vier Tagen Magen-Darm und fast nichts gegessen, nur Zwieback und Tee. Das Insulin habe ich aber weiter gespritzt, wie immer.",
  prev:"Zittrig war ich gestern Abend schon. Aber so wie heute war es noch nie.",self:"Nein. Die Schwester hat mir Traubenzucker gegeben, und dann kam der Krankenwagen.",
  vacc:"Gegen Grippe, ja. Das andere weiß mein Hausarzt.",reise:"Nein, ich komme nicht mehr weg.",
  veg:{appetit:"Seit vier Tagen esse ich fast nichts.",gewicht:"Ich habe bestimmt abgenommen in den Tagen.",stuhl:"Ich hatte vier Tage Durchfall, seit gestern ist es besser.",wasser:"Normal.",schlaf:"Ich schlafe wenig, aber das ist im Alter so.",fieber:"Nein, Fieber hatte ich keins.",durst:"Ich habe Tee getrunken, aber nicht viel."},
  gyn:"Ach, das ist fünfzig Jahre her. Ich habe einen Sohn."},
 brief:"Frau Zimmermann ist eine 86-jährige Patientin, die vom Pflegedienst am Morgen verwirrt und schweißgebadet aufgefunden und mit einem Blutzucker von 38 mg/dl eingeliefert wurde. Nach Glukosegabe klarte sie auf. Sie berichtete, sie leide seit vier Tagen an einem Magen-Darm-Infekt mit Durchfall und habe kaum gegessen; das Insulin habe sie dennoch in unveränderter Dosis weitergespritzt. Bereits am Vorabend sei sie zittrig gewesen. Fieber, Brustschmerzen und ein Sturz wurden verneint.\nAn Vorerkrankungen bestehen ein insulinpflichtiger Diabetes mellitus Typ 2 seit 25 Jahren, eine chronische Niereninsuffizienz Stadium 3b, ein Vorhofflimmern, eine Osteoporose mit Wirbelkörperfraktur und eine leichte kognitive Störung. Voroperationen wurden verneint. Medikation: Mischinsulin 24 IE morgens und 16 IE abends, Apixaban 2,5 mg 1-0-1, Bisoprolol 2,5 mg 1-0-0, Torasemid 5 mg 1-0-0, Alendronsäure 70 mg einmal wöchentlich, Vitamin D. Es besteht eine Unverträglichkeit von Codein. Nikotin- und Alkoholkonsum wurden verneint. Die Familienanamnese ist nicht erhebbar. Die Patientin ist verwitwet, lebt allein und wird zweimal täglich vom Pflegedienst betreut.\nEs handelt sich um eine schwere Hypoglykämie unter fortgeführter Insulintherapie bei verminderter Nahrungsaufnahme und eingeschränkter Nierenfunktion. Differenzialdiagnostisch sind eine Sepsis und ein Schlaganfall zu bedenken. Wir empfehlen: Glukoseinfusion mit engmaschigen Blutzuckerkontrollen, Labor mit Elektrolyten und Kreatinin, EKG, die stationäre Überwachung, eine Reduktion der Insulindosis mit einem weniger strengen HbA1c-Ziel sowie eine Schulung zu den Regeln bei Krankheit.",
 kw:[["Mischinsulin|Verzögerungsinsulin|wirkt.{0,15}(weiter|Stunden)","Niereninsuffizienz|Kumulation","Rezidiv|erneut","Infusion|Glukose 10","Kontrollen|engmaschig"],["Niereninsuffizienz","Nahrungsaufnahme|unregelmäßig|Essen","Wahrnehmung|Hypoglykämiewahrnehmung|Betablocker","kognitiv|Demenz","strenge Einstellung|HbA1c zu niedrig|Übertherapie"],["7,5|8|8,5","Lebenserwartung|Komorbidität|geriatrisch","Hypoglykämie vermeiden|Sicherheit","Symptomfreiheit|Lebensqualität"]],
 terms:["Hypoglykämie","Insulin","Gastroenteritis","Niereninsuffizienz","Vorhofflimmern"]}
};

// ===== P3 · the eight FSP cases of p9_klinik2.js made reachable (keyed by name; they had no id, no hpi, no questions) =====
// Same schema as P3_FSP_OVER; additionally id, sex, hpi (lay, first person), fam, patientQs, oberarztQs, traps.
const P3_FSP_OVER_P9={
"Herr Thomas Richter":{id:"fk1",sex:"m",vn:"Thomas",geb:"12.04.1972",cm:179,kg:96,ha:"Herr Doktor Lenz in Sandhausen",sys:"kardio",scale:8,
 hpi:"Ich war heute früh beim Abladen, da hat es auf einmal in der Brust gedrückt, als ob jemand auf mir sitzt. Das geht jetzt seit drei Stunden nicht weg. Es zieht in den linken Arm, bis in die Finger. Ich bin ganz nass geschwitzt, und mir ist ein bisschen übel. Luft bekomme ich auch schlechter als sonst.",
 fam:"Vater Myokardinfarkt mit 60; Mutter Diabetes mellitus Typ 2",
 vit:"RR 156/94 mmHg · HF 98/min · AF 20/min · SpO₂ 95 % · Temp. 36,7 °C · NRS 8/10",
 patientQs:["Ist das ein Herzinfarkt?","Muss ich jetzt operiert werden?","Kann ich danach noch Lkw fahren? Davon lebt meine Familie."],
 oberarztQs:["Welche Maßnahmen ergreifen Sie in den ersten zehn Minuten?","Wie unterscheiden Sie STEMI, NSTEMI und instabile Angina pectoris?","Welche Differenzialdiagnosen des akuten Brustschmerzes sind lebensbedrohlich?"],
 traps:"Time matters: an ECG within ten minutes is what examiners want to hear first. With the patient say 'Herzinfarkt' and 'Herzkatheter', not 'Myokardinfarkt' and 'Koronarangiographie'. The lorry question is a real trap: professional drivers have a long driving ban after an infarction – do not promise anything, say that the cardiologists and the Betriebsarzt decide.",
 lay:{open:"Ich habe seit drei Stunden einen starken Druck auf der Brust. Das zieht in den linken Arm, und ich schwitze wie verrückt.",
  pmh:"Ich habe hohen Blutdruck, sonst bin ich eigentlich gesund.",ops:"Nein, operiert worden bin ich noch nie.",meds:"Eine Blutdrucktablette am Morgen. Ramipril heißt die, glaube ich.",all:"Nein, Allergien habe ich keine.",
  fam:"Mein Vater hatte mit sechzig einen Herzinfarkt. Meine Mutter hat Zucker.",nox:"Ich rauche, eine Schachtel am Tag, seit dreißig Jahren. Alkohol nur am Wochenende, ein paar Bier.",drugs:"Nein. Als Fahrer kann ich mir das gar nicht leisten.",
  soc:"Ich bin Lkw-Fahrer und arbeite im Schichtdienst. Ich bin verheiratet und habe zwei Kinder.",
  char:"Es ist ein Druck, eine Enge, wie ein Schraubstock.",rad:"Ja, in den linken Arm, bis in die Finger. Und ein bisschen in den Unterkiefer.",
  mod:"Es ist immer gleich, egal ob ich sitze, liege oder tief atme. Besser wird es durch nichts.",prev:"In den letzten Wochen hatte ich beim Treppensteigen manchmal so ein Druckgefühl, das ging nach ein paar Minuten wieder weg. So wie heute war es noch nie.",
  self:"Nein, ich habe nichts genommen. Mein Kollege hat gleich den Notruf gewählt.",vacc:"Das Übliche, glaube ich.",reise:"Ich fahre nur innerhalb von Deutschland.",
  veg:{appetit:"Normal, eher zu gut.",gewicht:"Ich habe in den letzten Jahren zugenommen.",schlaf:"Durch die Schichten schlafe ich unregelmäßig.",stuhl:"Normal.",wasser:"Normal.",fieber:"Nein."}},
 brief:"Herr Richter ist ein 54-jähriger Patient, der sich mit seit drei Stunden bestehenden drückenden retrosternalen Schmerzen vorstellte. Er berichtete, die Beschwerden hätten bei körperlicher Arbeit plötzlich begonnen, strahlten in den linken Arm und den Unterkiefer aus und seien lage- und atemunabhängig; die Stärke betrage 8/10. Begleitend bestünden Kaltschweißigkeit, Übelkeit und leichte Luftnot. In den letzten Wochen habe er bei Belastung wiederholt ein kurzes thorakales Druckgefühl bemerkt.\nAn Vorerkrankungen ist eine arterielle Hypertonie bekannt. Voroperationen wurden verneint. Medikation: Ramipril 5 mg 1-0-0. Allergien sind nicht bekannt. Der Patient rauche seit 30 Jahren eine Schachtel pro Tag (30 Packungsjahre) und trinke am Wochenende Alkohol. Der Vater habe mit 60 Jahren einen Myokardinfarkt erlitten. Der Patient ist Lkw-Fahrer im Schichtdienst, verheiratet und hat zwei Kinder.\nDie Anamnese spricht für ein akutes Koronarsyndrom. Differenzialdiagnostisch kommen eine Lungenembolie, eine Aortendissektion und ein Pneumothorax in Betracht. Wir empfehlen: 12-Kanal-EKG innerhalb von zehn Minuten, Monitoring, Troponin im Verlauf, ASS und Heparin nach Rücksprache sowie die umgehende Vorstellung in der Kardiologie zur Koronarangiographie.",
 kw:[["EKG|12-Kanal","zehn Minuten|10 Minuten","Monitor","ASS|Aspirin","Zugang|Troponin","Heparin|Kardiolog|Herzkatheter"],["ST-Hebung|Hebung","Troponin","NSTEMI.{0,60}(ohne Hebung|Troponin (positiv|erhöht))|ohne ST-Hebung","instabil.{0,60}Troponin (negativ|normal)|Troponin negativ"],["Lungenembolie","Aortendissektion","Spannungspneumothorax|Pneumothorax","Ösophagusruptur|Boerhaave","Infarkt|Koronarsyndrom"]],
 terms:["akutes Koronarsyndrom","Myokardinfarkt","Angina pectoris","Koronarangiographie","Troponin"]},

"Frau Sabine Vogt":{id:"fk2",sex:"w",vn:"Sabine",geb:"21.08.1988",cm:170,kg:64,ha:"Frau Doktor Peters in Weinheim",sys:"neuro",scale:10,
 hpi:"Gestern Abend, beim Korrigieren, hat es auf einmal im Kopf geknallt – von einer Sekunde auf die andere. Solche Kopfschmerzen hatte ich noch nie, das ist ganz anders als meine Migräne. Mir ist übel, ich habe zweimal erbrochen, und Licht tut mir weh. Der Nacken fühlt sich steif an. Ich habe eine Migränetablette genommen, aber die hat überhaupt nicht geholfen.",
 fam:"Mutter Migräne; Großmutter an einer Hirnblutung verstorben",
 vit:"RR 168/98 mmHg · HF 64/min · AF 16/min · SpO₂ 98 % · Temp. 37,2 °C · GCS 15 · NRS 10/10",
 patientQs:["Ist das nicht einfach eine besonders schlimme Migräne?","Warum wollen Sie mir in den Rücken stechen, wenn das CT doch unauffällig ist?","Ist das eine Blutung im Kopf? Kann ich daran sterben?"],
 oberarztQs:["Welche Warnzeichen (Red Flags) machen einen Kopfschmerz zum Notfall?","Wie gehen Sie vor, wenn das native cCT unauffällig ist?","Welche Komplikationen drohen nach einer Subarachnoidalblutung in den ersten Tagen?"],
 traps:"A known migraine patient with a 'different' headache is the classic trap: ask how fast the pain reached its maximum (seconds = Donnerschlagkopfschmerz). Say 'Hirnblutung' or 'Blutung unter der Hirnhaut' to the patient, 'Subarachnoidalblutung' to the Oberarzt. Explain the lumbar puncture simply and why a normal CT is not enough after some hours. Note the penicillin allergy and the pill.",
 lay:{open:"Ich habe seit gestern Abend die schlimmsten Kopfschmerzen meines Lebens. Die kamen ganz plötzlich, wie ein Schlag.",
  pmh:"Ich habe seit meiner Jugend Migräne. Sonst bin ich gesund.",ops:"Nein, noch nie.",meds:"Ich nehme die Pille. Und bei Migräne eine Tablette, ein Triptan.",all:"Ja, gegen Penicillin. Davon bekomme ich einen Hautausschlag.",
  fam:"Meine Mutter hat auch Migräne. Und meine Großmutter ist an einer Hirnblutung gestorben.",nox:"Ich rauche nicht. Alkohol trinke ich selten, mal ein Glas Wein.",drugs:"Nein.",
  soc:"Ich bin Lehrerin am Gymnasium. Ich bin ledig und wohne allein.",
  char:"Es ist ein vernichtender Schmerz, im ganzen Kopf, vor allem hinten.",rad:"Er zieht in den Nacken.",
  mod:"Es wird durch nichts besser. Licht und Bewegung machen es noch schlimmer. Meine Migränetablette hat nicht geholfen.",prev:"Migräne kenne ich. Aber die ist einseitig und pochend und kommt langsam. Das hier ist völlig anders.",
  self:"Ich habe gestern Abend mein Triptan genommen und heute früh Ibuprofen. Beides ohne Wirkung.",vacc:"Ich bin vollständig geimpft.",reise:"Nein.",
  veg:{appetit:"Mir ist übel, ich kann nichts essen.",gewicht:"Gleich.",schlaf:"Ich habe die ganze Nacht nicht geschlafen.",stuhl:"Normal.",wasser:"Normal.",fieber:"Nein, Fieber habe ich nicht."},
  gyn:"Meine Periode kommt regelmäßig, die letzte war vor einer Woche. Ich nehme die Pille, schwanger bin ich nicht."},
 brief:"Frau Vogt ist eine 38-jährige Patientin, die sich mit seit dem Vorabend bestehenden stärksten Kopfschmerzen vorstellte. Sie berichtete, die Schmerzen hätten schlagartig begonnen und innerhalb von Sekunden ihr Maximum erreicht (10/10); sie seien holozephal mit Betonung okzipital und strahlten in den Nacken aus. Begleitend bestünden Übelkeit, zweimaliges Erbrechen, Lichtscheu und Nackensteifigkeit. Die Patientin betonte, die Beschwerden unterschieden sich deutlich von ihrer bekannten Migräne; ein Triptan und Ibuprofen hätten nicht geholfen. Ein Trauma, Fieber und Lähmungen wurden verneint.\nAn Vorerkrankungen ist eine Migräne seit der Jugend bekannt. Voroperationen wurden verneint. Medikation: orales Kontrazeptivum (Ethinylestradiol/Levonorgestrel), Triptan bei Bedarf. Es besteht eine Penicillinallergie (Exanthem). Die Patientin sei Nichtraucherin und trinke selten Alkohol. Die Großmutter sei an einer Hirnblutung verstorben. Die Patientin ist Lehrerin und ledig.\nDie Anamnese spricht für eine Subarachnoidalblutung. Differenzialdiagnostisch kommen eine Migräneattacke, eine Meningitis und eine Sinusvenenthrombose in Betracht. Wir empfehlen: sofortiges natives cCT, bei unauffälligem Befund eine Lumbalpunktion, Blutdruckkontrolle, Analgesie, Bettruhe und die umgehende Vorstellung in der Neurologie bzw. Neurochirurgie.",
 kw:[["plötzlich|Donnerschlag|schlagartig","stärkster|schlimmster|nie gekannt","Meningismus|Nackensteifigkeit","neurologische Ausfälle|Bewusstsein|Krampfanfall","Fieber|Trauma|Antikoagulation|Schwangerschaft|über 50"],["Lumbalpunktion","Xanthochromie|Blut im Liquor","6 Stunden|zwölf Stunden|12 Stunden|Sensitivität","CT-Angiographie|CTA|Aneurysma"],["Nachblutung|Rezidivblutung","Vasospasmus","Hydrozephalus","Nimodipin","Hyponatriämie|Krampfanfall"]],
 terms:["Subarachnoidalblutung","Meningismus","Photophobie","Lumbalpunktion","Aneurysma"]},

"Herr Ali Demir":{id:"fk3",sex:"m",vn:"Ali",geb:"03.01.1959",cm:171,kg:83,ha:"Herr Doktor Kurz in Rohrbach",sys:"pulmo",
 hpi:"Seit zwei Tagen bekomme ich immer schlechter Luft, schon wenn ich vom Sofa in die Küche gehe. Ich huste viel, und der Schleim ist gelb. Gestern Abend hatte ich 39 Grad Fieber und Schüttelfrost. Rechts unten in der Brust sticht es, wenn ich huste. Normalerweise komme ich mit meinem Spray gut zurecht, aber jetzt hilft es nicht mehr.",
 fam:"Vater Bronchialkarzinom (Raucher); Mutter Diabetes mellitus Typ 2",
 vit:"RR 128/76 mmHg · HF 108/min · AF 26/min · SpO₂ 88 % unter Raumluft · Temp. 39,0 °C · BZ 214 mg/dl",
 patientQs:["Muss ich im Krankenhaus bleiben? Zu Hause ist niemand, aber da ist mein Bett.","Ist das wieder die Raucherlunge, oder ist es etwas Neues?","Bekomme ich jetzt Antibiotika – und vertragen die sich mit meinen Zuckertabletten?"],
 oberarztQs:["Nach welchen Kriterien entscheiden Sie über die stationäre Aufnahme?","Welche Sauerstoffsättigung streben Sie bei diesem Patienten an und warum?","Welche Antibiose wählen Sie, und was ändert die COPD daran?"],
 traps:"Two lung diseases in one patient: examiners want you to separate 'Lungenentzündung' from the known 'Raucherlunge/COPD' and to justify admission with a score (CRB-65) rather than a feeling. Oxygen target 88–92 % because of the COPD. He lives alone – the social history decides the discharge. Lay terms: 'Lungenentzündung', 'Röntgenbild der Lunge', 'Sauerstoff über eine Nasenbrille'.",
 lay:{open:"Ich bekomme seit zwei Tagen immer schlechter Luft. Ich huste gelben Schleim und habe Fieber.",
  pmh:"Ich habe eine Raucherlunge und Zucker.",ops:"Nein, operiert worden bin ich noch nie.",meds:"Ein Spray für die Lunge jeden Morgen und eins für den Notfall. Und Metformin, morgens und abends.",all:"Nein, keine.",
  fam:"Mein Vater ist an Lungenkrebs gestorben, er hat stark geraucht. Meine Mutter hatte Zucker.",nox:"Ich habe vor fünf Jahren aufgehört zu rauchen. Davor vierzig Jahre lang eine Schachtel am Tag. Alkohol trinke ich nicht.",drugs:"Nein.",
  soc:"Ich war Bäcker, jetzt bin ich Rentner. Meine Frau ist gestorben, ich lebe allein. Meine Tochter wohnt in der Nähe und schaut nach mir.",
  char:"Es ist ein Stechen rechts unten, nur beim Husten und beim tiefen Atmen.",rad:"Nein, es bleibt an der Stelle.",
  mod:"Beim Husten und bei jeder Anstrengung wird es schlimmer. Im Sitzen bekomme ich besser Luft als im Liegen.",prev:"Schlecht Luft bekomme ich öfter, im Winter vor allem. Aber mit so hohem Fieber noch nie.",
  self:"Ich habe mein Notfallspray öfter genommen und Paracetamol gegen das Fieber.",vacc:"Gegen Grippe ja. Gegen Lungenentzündung bin ich, glaube ich, nicht geimpft.",reise:"Nein.",
  veg:{appetit:"Ich habe keinen Appetit.",gewicht:"Gleich geblieben.",schlaf:"Wegen dem Husten schlafe ich kaum.",stuhl:"Normal.",wasser:"Normal.",fieber:"Gestern Abend 39 Grad, mit Schüttelfrost.",durst:"Ich habe mehr Durst als sonst."}},
 brief:"Herr Demir ist ein 67-jähriger Patient, der sich mit seit zwei Tagen zunehmender Dyspnoe, produktivem Husten mit gelblichem Auswurf und Fieber bis 39 °C vorstellte. Er berichtete, die Luftnot trete bereits bei geringer Belastung auf; beim Husten bestünden atemabhängige Schmerzen rechts basal. Am Vorabend habe er Schüttelfrost gehabt. Das Bedarfsspray bringe keine ausreichende Linderung. Hämoptysen und Beinschwellungen wurden verneint.\nAn Vorerkrankungen bestehen eine COPD (GOLD II) und ein Diabetes mellitus Typ 2. Voroperationen wurden verneint. Medikation: Tiotropium 1-0-0, Salbutamol bei Bedarf, Metformin 1000 mg 1-0-1. Allergien sind nicht bekannt. Der Patient habe vor fünf Jahren das Rauchen beendet (40 Packungsjahre); Alkoholkonsum wurde verneint. Der Vater sei an einem Bronchialkarzinom verstorben. Der Patient ist Rentner, verwitwet und lebt allein; die Tochter wohne in der Nähe.\nDie Anamnese spricht für eine ambulant erworbene Pneumonie bei bekannter COPD. Differenzialdiagnostisch kommen eine infektbedingte Exazerbation der COPD, eine kardiale Dekompensation und eine Lungenembolie in Betracht. Wir empfehlen: Röntgen-Thorax, Blutgasanalyse, Labor mit Entzündungswerten, Blutkulturen, Sauerstoffgabe mit Zielsättigung 88–92 %, eine kalkulierte Antibiose und die stationäre Aufnahme.",
 kw:[["CRB-65|CURB","Verwirrtheit|Atemfrequenz|Blutdruck|65","Sättigung|Hypoxie|Sauerstoff","Komorbidität|COPD|Diabetes","lebt allein|soziale|Versorgung"],["88","92","Hyperkapnie|CO2|Atemantrieb","Blutgasanalyse|BGA"],["Aminopenicillin|Amoxicillin|Ampicillin","Betalaktamaseinhibitor|Clavulansäure|Sulbactam","Makrolid|atypisch","Haemophilus|Pseudomonas|COPD.{0,40}Erreger","Blutkulturen|vor der ersten Gabe"]],
 terms:["Pneumonie","Dyspnoe","Sputum","Infiltrat","Blutgasanalyse"]},

"Frau Elena Petrova":{id:"fk4",sex:"w",vn:"Elena",geb:"17.06.1997",cm:164,kg:55,ha:"Herr Doktor Jung in der Weststadt",sys:"gi",scale:7,
 hpi:"Heute Nacht bin ich von Bauchschmerzen aufgewacht, erst mitten im Bauch, um den Nabel herum. Seit dem Morgen tut es rechts unten weh, und es wird immer stärker. Mir ist schlecht, erbrochen habe ich aber nicht. Essen mag ich gar nichts. Beim Gehen muss ich mich nach vorne beugen, und auf der Fahrt hierher hat jede Bodenwelle wehgetan.",
 fam:"Bruder Appendektomie mit 16; Eltern gesund",
 vit:"RR 116/70 mmHg · HF 98/min · AF 16/min · SpO₂ 99 % · Temp. 37,9 °C · NRS 7/10",
 patientQs:["Kann das auch etwas mit den Eierstöcken sein?","Muss ich heute noch operiert werden?","Ich schreibe in zwei Wochen meine Masterarbeit zu Ende – wie lange falle ich aus?"],
 oberarztQs:["Welche klinischen Zeichen prüfen Sie bei Verdacht auf Appendizitis?","Welche Untersuchung muss bei einer jungen Frau vor jeder Bildgebung mit Strahlen erfolgen, und warum?","Wann würden Sie eine CT der Sonographie vorziehen?"],
 traps:"Last period two weeks ago – mid-cycle: think of Mittelschmerz, ovarian cyst and torsion, and say so. The pregnancy test comes before any imaging. Lay terms: 'Blinddarmentzündung', 'Bauchspiegelung', 'Eierstock'. Do not promise a date for the thesis; give the usual range and what it depends on.",
 lay:{open:"Ich habe seit heute Nacht Bauchschmerzen. Erst waren sie in der Mitte, jetzt sind sie rechts unten.",
  pmh:"Nein, ich bin gesund.",ops:"Nein, ich bin noch nie operiert worden.",meds:"Ich nehme keine Medikamente, auch nicht die Pille.",all:"Nein, keine.",
  fam:"Mein Bruder hatte mit sechzehn eine Blinddarmoperation. Meine Eltern sind gesund.",nox:"Ich rauche nicht. Alkohol trinke ich ab und zu, auf einer Feier.",drugs:"Nein.",
  soc:"Ich studiere Biologie und schreibe gerade meine Masterarbeit. Ich wohne in einer WG.",
  char:"Am Anfang war es dumpf, jetzt ist es ein stechender Schmerz.",rad:"Nein, er strahlt nicht aus.",
  mod:"Beim Gehen, Husten und bei Erschütterungen wird es schlimmer. Wenn ich das rechte Bein anziehe, ist es besser.",prev:"Nein, noch nie.",
  self:"Ich habe nichts genommen, ich wollte die Schmerzen nicht überdecken.",vacc:"Ja, alle Impfungen.",reise:"Nein.",
  veg:{appetit:"Ich habe überhaupt keinen Appetit.",gewicht:"Gleich.",stuhl:"Gestern normal, heute noch nicht.",wasser:"Normal, kein Brennen.",schlaf:"Seit drei Uhr nachts bin ich wach.",fieber:"Zu Hause hatte ich 37,8."},
  gyn:"Meine letzte Regel war vor zwei Wochen, sie kommt regelmäßig. Ich verhüte mit Kondom. Schwanger bin ich nicht, denke ich. Ausfluss habe ich keinen."},
 brief:"Frau Petrova ist eine 29-jährige Patientin, die sich mit seit etwa zwölf Stunden bestehenden Bauchschmerzen vorstellte. Sie berichtete, die Schmerzen hätten nachts periumbilikal begonnen und sich am Morgen in den rechten Unterbauch verlagert; sie seien stechend, bei Erschütterung verstärkt und hätten eine Stärke von 7/10. Begleitend bestünden Übelkeit und Appetitlosigkeit ohne Erbrechen; die Temperatur habe 37,8 °C betragen. Miktion und Stuhlgang seien unauffällig. Die letzte Menstruation sei vor zwei Wochen gewesen; vaginaler Ausfluss wurde verneint.\nVorerkrankungen und Voroperationen sind nicht bekannt. Keine Medikation, keine hormonelle Kontrazeption. Allergien sind nicht bekannt. Die Patientin sei Nichtraucherin und trinke gelegentlich Alkohol. Der Bruder sei appendektomiert worden. Die Patientin ist Studentin und lebt in einer Wohngemeinschaft.\nDie Anamnese deutet auf eine akute Appendizitis hin. Differenzialdiagnostisch kommen eine Ovarialzyste bzw. Ovarialtorsion, eine Extrauteringravidität, eine Adnexitis und ein Harnwegsinfekt in Betracht. Wir empfehlen: Labor, Urinstatus mit Schwangerschaftstest, Abdomensonographie, Nahrungskarenz und ein chirurgisches Konsil.",
 kw:[["McBurney","Loslassschmerz|Blumberg","Rovsing","Psoas","Abwehrspannung|Douglas|rektal"],["Schwangerschaftstest|hCG","Extrauterin|Eileiterschwangerschaft","Strahlen|Röntgen|CT","gebärfähig"],["Sonographie unklar|nicht darstellbar|unklarer Befund","Adipositas|ältere","Komplikation|Abszess|Perforation","Strahlenbelastung|MRT"]],
 terms:["Appendizitis","Ovarialtorsion","Extrauteringravidität","Abwehrspannung","Laparoskopie"]},

"Herr Karl Hoffmann":{id:"fk5",sex:"m",vn:"Karl",geb:"30.07.1948",cm:173,kg:80,ha:"Herr Doktor Ernst in Meckesheim",sys:"neuro",
 hpi:"Vor einer Stunde, beim Frühstück, ist mir die Tasse aus der rechten Hand gefallen. Der Arm und das Bein rechts sind ganz schwach, ich kann nicht richtig aufstehen. Meine Frau sagt, ich rede undeutlich und der Mund hängt schief. Kopfschmerzen habe ich keine. Es fing genau um halb acht an, das weiß meine Frau, weil gerade die Nachrichten kamen.",
 fam:"Bruder Schlaganfall mit 70; Vater Myokardinfarkt",
 vit:"RR 178/96 mmHg · HF 88/min, arrhythmisch · AF 16/min · SpO₂ 96 % · Temp. 36,5 °C · BZ 124 mg/dl · GCS 15",
 patientQs:["Ist das ein Schlaganfall?","Bleibt das jetzt so mit dem Arm?","Ich nehme doch einen Blutverdünner – wie kann das dann passieren?"],
 oberarztQs:["Was müssen Sie in den ersten Minuten klären, bevor über eine Lysetherapie entschieden wird?","Welche Rolle spielt die Antikoagulation mit Apixaban für die Therapieentscheidung?","Welche Bildgebung veranlassen Sie, und wonach suchen Sie?"],
 traps:"The time of onset is the first question – get it to the minute and get it from the wife. The second is the anticoagulant: when was the last Apixaban tablet? Speak slowly and in short sentences; the patient has a speech problem, and examiners watch whether you include the relative without talking over the patient. Lay terms: 'Schlaganfall', 'Blutgerinnsel', 'Bild vom Kopf'. Mention the contrast reaction before the CT angiography.",
 lay:{open:"Mein rechter Arm und das rechte Bein sind seit einer Stunde ganz schwach. Und ich kann nicht richtig sprechen.",
  pmh:"Mein Herz schlägt unregelmäßig. Und ich habe hohen Blutdruck und zu viel Cholesterin.",ops:"Nein, operiert worden bin ich nie.",
  meds:"Einen Blutverdünner, morgens und abends, den habe ich heute früh um sieben genommen. Dann eine Tablette für das Herz und eine fürs Cholesterin.",
  all:"Vom Kontrastmittel ist mir einmal schlecht geworden. Sonst nichts.",fam:"Mein Bruder hatte mit siebzig einen Schlaganfall. Mein Vater hatte einen Herzinfarkt.",
  nox:"Ich rauche nicht. Ein Glas Wein zum Essen, mehr nicht.",drugs:"Nein.",
  soc:"Ich war Landwirt. Ich lebe mit meiner Frau zusammen, wir versorgen uns selbst.",
  mod:"Es ist seit einer Stunde gleich, nicht besser und nicht schlechter.",prev:"Nein, so etwas hatte ich noch nie.",
  self:"Nein. Meine Frau hat sofort den Notruf gewählt.",vacc:"Grippe ja.",reise:"Nein.",
  veg:{appetit:"Normal.",gewicht:"Gleich.",schlaf:"Gut.",stuhl:"Normal.",wasser:"Normal.",fieber:"Nein."}},
 brief:"Herr Hoffmann ist ein 78-jähriger Patient, der vom Rettungsdienst mit einer seit einer Stunde bestehenden Schwäche des rechten Armes und Beines sowie einer verwaschenen Sprache eingeliefert wurde. Der Symptombeginn sei laut Ehefrau um 7:30 Uhr gewesen; dem Patienten sei beim Frühstück die Tasse aus der Hand gefallen, zudem hänge der rechte Mundwinkel. Kopfschmerzen, ein Sturz und ein Krampfereignis wurden verneint. Die letzte Einnahme von Apixaban sei am Morgen um 7:00 Uhr erfolgt.\nAn Vorerkrankungen bestehen ein Vorhofflimmern, eine arterielle Hypertonie und eine Hypercholesterinämie. Voroperationen wurden verneint. Medikation: Apixaban 5 mg 1-0-1, Bisoprolol, Atorvastatin. Der Patient gab an, er habe auf Kontrastmittel einmal mit Übelkeit reagiert. Er sei Nichtraucher und trinke gelegentlich Wein. Der Bruder habe mit 70 Jahren einen Schlaganfall erlitten. Der Patient ist Landwirt im Ruhestand, lebt mit seiner Ehefrau und versorgt sich selbstständig.\nDie Anamnese spricht für einen ischämischen Schlaganfall im Stromgebiet der linken Arteria cerebri media. Differenzialdiagnostisch kommen eine intrazerebrale Blutung unter Antikoagulation, eine TIA und eine Hypoglykämie in Betracht. Wir empfehlen: Stroke-Alarm, Blutzucker, sofortiges cCT mit CT-Angiographie, Erhebung des NIHSS, Gerinnungsdiagnostik und die umgehende neurologische Mitbeurteilung zur Frage einer Rekanalisationstherapie.",
 kw:[["Symptombeginn|Zeitfenster|Zeitpunkt","Blutung ausschließen|cCT","Blutzucker","Antikoagulation|letzte Einnahme","NIHSS","Kontraindikation"],["Lyse.{0,60}(kontraindiziert|nicht|48)|48 Stunden|letzte Einnahme","Gerinnung|Anti-Xa|Spiegel","Thrombektomie|mechanisch","Antidot|Andexanet"],["cCT nativ|natives CT","Blutung","CT-Angiographie|Gefäßverschluss","Perfusion|MRT|Infarktfrühzeichen"]],
 terms:["Hirninfarkt","Hemiparese","Dysarthrie","Vorhofflimmern","Thrombolyse"]},

"Frau Monika Schäfer":{id:"fk6",sex:"w",vn:"Monika",geb:"09.09.1981",cm:165,kg:92,ha:"Frau Doktor Busch in Wiesloch",sys:"gi",scale:8,
 hpi:"Vor vier Tagen hatte ich nach einem Schweinebraten krampfartige Schmerzen rechts unter den Rippen, das kenne ich von meinen Gallensteinen. Diesmal ging es aber nicht weg, die Schmerzen kommen immer wieder. Seit heute habe ich Fieber und Schüttelfrost. Mein Mann sagt, meine Augen sind gelb. Der Urin ist dunkel wie Bier, und der Stuhl ist ganz hell.",
 fam:"Mutter Cholezystektomie; Schwester Gallensteine",
 vit:"RR 104/62 mmHg · HF 112/min · AF 20/min · SpO₂ 96 % · Temp. 39,3 °C · NRS 8/10",
 patientQs:["Ich bin selbst Krankenschwester – sagen Sie mir ehrlich: Ist das eine Sepsis?","Muss die Gallenblase jetzt raus?","Was ist eine ERCP, und ist das gefährlich?"],
 oberarztQs:["Welche Trias beschreibt die akute Cholangitis, und welche Laborwerte erwarten Sie?","Was ist die entscheidende Therapie neben dem Antibiotikum, und wie dringend ist sie?","Wie unterscheiden Sie Cholezystitis, Choledocholithiasis und Cholangitis?"],
 traps:"A nurse as patient: stay in lay language anyway unless she asks for the term, and do not let her lead the consultation. Fever + jaundice + right upper abdominal pain (Charcot) must be named, and drainage of the bile duct (ERCP) is the treatment, not 'antibiotics and wait'. Ask for stool and urine colour – that is the point examiners count.",
 lay:{open:"Ich habe seit vier Tagen krampfartige Schmerzen rechts oben im Bauch. Seit heute habe ich Fieber und Schüttelfrost, und meine Haut ist gelb.",
  pmh:"Ich habe Gallensteine, das weiß ich seit zwei Jahren. Und ich habe Übergewicht.",ops:"Ich hatte drei Kaiserschnitte, sonst nichts.",meds:"Ich nehme keine Medikamente regelmäßig.",all:"Nein, keine.",
  fam:"Meiner Mutter wurde die Gallenblase entfernt. Meine Schwester hat auch Gallensteine.",nox:"Ich rauche nicht. Alkohol trinke ich selten.",drugs:"Nein.",
  soc:"Ich bin Krankenschwester auf einer Inneren Station, im Schichtdienst. Ich bin verheiratet und habe drei Kinder.",
  char:"Es sind Krämpfe, die kommen und gehen. Dazwischen bleibt ein dumpfer Druck.",rad:"Ja, in die rechte Schulter und in den Rücken.",
  mod:"Nach fettem Essen wird es schlimmer. Eine Wärmflasche und Buscopan haben am Anfang geholfen, jetzt nicht mehr.",prev:"Ja, solche Koliken hatte ich schon drei-, viermal. Die waren aber nach ein paar Stunden vorbei, und ich hatte nie Fieber.",
  self:"Ich habe Buscopan und Paracetamol genommen.",vacc:"Ja, alles, auch Hepatitis B, das brauche ich für den Beruf.",reise:"Nein.",
  veg:{appetit:"Ich habe keinen Appetit, mir ist übel.",gewicht:"Unverändert.",stuhl:"Der Stuhl ist ganz hell, fast weiß.",wasser:"Der Urin ist dunkelbraun.",schlaf:"Schlecht.",fieber:"Heute Morgen 39,3, mit Schüttelfrost."},
  gyn:"Meine Regel kommt regelmäßig, die letzte war vor zwei Wochen. Ich bin sterilisiert, schwanger kann ich nicht sein."},
 brief:"Frau Schäfer ist eine 45-jährige Patientin, die sich mit seit vier Tagen bestehenden kolikartigen Schmerzen im rechten Oberbauch vorstellte. Sie berichtete, die Beschwerden hätten nach einer fettreichen Mahlzeit begonnen und strahlten in die rechte Schulter und den Rücken aus (8/10). Seit dem Aufnahmetag bestünden Fieber bis 39,3 °C und Schüttelfrost; dem Ehemann sei ein Ikterus aufgefallen. Der Urin sei dunkel, der Stuhl entfärbt. Butylscopolamin und Paracetamol hätten zuletzt nicht mehr geholfen. Ähnliche, kürzere Koliken ohne Fieber seien mehrfach vorgekommen.\nAn Vorerkrankungen bestehen eine Cholezystolithiasis und eine Adipositas. Z. n. dreimaliger Sectio caesarea. Keine Dauermedikation. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint, Alkohol selten. Die Mutter sei cholezystektomiert. Die Patientin ist Krankenschwester im Schichtdienst, verheiratet und hat drei Kinder.\nDie Anamnese mit Fieber, Ikterus und Oberbauchschmerz spricht für eine akute Cholangitis bei Choledocholithiasis. Differenzialdiagnostisch kommen eine akute Cholezystitis, eine Hepatitis und eine biliäre Pankreatitis in Betracht. Wir empfehlen: Labor mit Cholestaseparametern, Lipase und Entzündungswerten, Blutkulturen, Abdomensonographie, Volumengabe, eine kalkulierte Antibiose und die zeitnahe ERCP zur Gallengangsentlastung.",
 kw:[["Charcot","Fieber","Ikterus","Oberbauchschmerz","Bilirubin|AP|Gamma-GT|Cholestase","Leukozytose|CRP"],["ERCP","Entlastung|Drainage|Steinextraktion|Papillotomie","24|dringlich|sofort|zeitnah","Sepsis"],["Cholezystitis.{0,80}(Murphy|kein Ikterus|Wandverdickung)|Murphy","Choledocholithiasis.{0,80}(Ikterus|ohne Fieber|Kolik)|Gallengang","Sonograph|erweiterte Gallenwege","Cholangitis.{0,60}(Fieber|Infektion)"]],
 terms:["Cholangitis","Ikterus","Cholezystolithiasis","Kolik","Cholestase"]},

"Herr Jonas Keller":{id:"fk7",sex:"m",vn:"Jonas",geb:"02.02.2004",cm:182,kg:78,ha:"Herr Doktor Wolf in Eberbach",sys:"muskulo",scale:8,
 hpi:"Ich bin vor einer halben Stunde auf der Baustelle vom Gerüst gefallen, ungefähr drei Meter tief. Ich bin auf der linken Seite gelandet. Das Becken tut höllisch weh, und der linke Unterschenkel auch, den kann ich nicht bewegen. Ich glaube, ich war kurz weg, an den Aufprall kann ich mich nicht richtig erinnern. Einen Helm hatte ich auf.",
 fam:"keine Besonderheiten",
 vit:"RR 98/60 mmHg · HF 118/min · AF 22/min · SpO₂ 96 % · Temp. 36,4 °C · GCS 15 · NRS 8/10",
 patientQs:["Ist etwas gebrochen?","Kann ich etwas gegen die Schmerzen bekommen?","Können Sie meine Mutter anrufen? Sie weiß noch nichts."],
 oberarztQs:["Nach welchem Schema untersuchen Sie einen Schwerverletzten, und was bedeutet jeder Buchstabe?","Warum ist eine Beckenfraktur lebensbedrohlich, und was ist die erste Maßnahme?","Welche Angaben zum Unfallhergang sind für die Schockraumindikation wichtig?"],
 traps:"In trauma the history is short and structured (AMPLE: Allergien, Medikamente, Patientengeschichte, letzte Mahlzeit, Ereignis) – examiners want to hear that you know it. A fall from three metres is a Schockraum criterion. It is a work accident: Berufsgenossenschaft, D-Arzt-Verfahren. Tetanus status must be asked. The mother: he is an adult – ask his permission and it is fine.",
 lay:{open:"Ich bin vor einer halben Stunde vom Gerüst gefallen, drei Meter tief. Mein Becken und das linke Bein tun furchtbar weh.",
  pmh:"Nein, ich bin gesund.",ops:"Nein, noch nie.",meds:"Nein, ich nehme nichts.",all:"Nein, keine.",fam:"Bei uns sind alle gesund.",
  nox:"Ich rauche, so zehn Zigaretten am Tag, seit ich sechzehn bin. Am Wochenende trinke ich Bier. Heute habe ich nichts getrunken.",drugs:"Nein.",
  soc:"Ich mache eine Ausbildung zum Elektriker, im dritten Lehrjahr. Ich wohne noch bei meinen Eltern.",
  char:"Es ist ein stechender, ganz starker Schmerz, im Becken und im Unterschenkel.",rad:"Vom Becken zieht es in die Leiste.",
  mod:"Jede Bewegung ist die Hölle. Wenn ich ganz still liege, geht es.",prev:"Nein, ich hatte noch nie einen Unfall.",
  self:"Der Notarzt hat mir etwas gegen die Schmerzen gespritzt, das hat ein bisschen geholfen.",vacc:"Tetanus? Das weiß ich nicht, vielleicht in der Schule das letzte Mal.",reise:"Nein.",
  lastmeal:"Ich habe um halb zehn ein belegtes Brötchen gegessen und eine Cola getrunken.",
  veg:{appetit:"Normal.",gewicht:"Gleich.",schlaf:"Gut.",stuhl:"Normal.",wasser:"Seit dem Sturz musste ich noch nicht.",fieber:"Nein."}},
 brief:"Herr Keller ist ein 22-jähriger Patient, der vom Notarzt nach einem Arbeitsunfall in unseren Schockraum gebracht wurde. Er berichtete, er sei etwa 30 Minuten zuvor aus circa drei Metern Höhe von einem Gerüst gestürzt und auf der linken Körperseite aufgekommen. Seitdem bestünden stärkste Schmerzen im Becken und im linken Unterschenkel (8/10), den er nicht bewegen könne. Für den Aufprall bestehe eine kurze Erinnerungslücke; er habe einen Helm getragen. Übelkeit, Luftnot und Bauchschmerzen wurden verneint. Die letzte Mahlzeit sei gegen 9:30 Uhr gewesen.\nVorerkrankungen und Voroperationen sind nicht bekannt. Keine Medikation. Allergien sind nicht bekannt. Der Tetanus-Impfstatus ist unklar. Der Patient rauche etwa zehn Zigaretten pro Tag (5 Packungsjahre) und trinke am Wochenende Alkohol. Die Familienanamnese ist unauffällig. Er ist Auszubildender zum Elektriker; es handelt sich um einen Arbeitsunfall (BG-Fall).\nEs besteht der Verdacht auf ein Polytrauma mit Beckenfraktur, Unterschenkelfraktur links und leichtem Schädel-Hirn-Trauma; eine innere Blutung ist auszuschließen. Wir empfehlen: Schockraumversorgung nach ABCDE-Schema, Anlage einer Beckenschlinge, FAST-Sonographie, Ganzkörper-CT, Analgesie, Kreuzblut, Überprüfung des Tetanusschutzes und die Vorstellung in der Unfallchirurgie.",
 kw:[["ABCDE","Atemweg|Airway","Atmung|Breathing|Beatmung","Kreislauf|Circulation|Blutung","neurologisch|Disability|GCS","Entkleiden|Exposure|Wärme"],["Blutung|Blutverlust","retroperitoneal|venöser Plexus|Liter","Beckenschlinge|Beckengurt","Schock"],["Sturzhöhe|drei Meter|3 m","Mechanismus|Hochrasanz","Bewusstlosigkeit|Amnesie","Vitalparameter|Schock"]],
 terms:["Polytrauma","Beckenfraktur","Schädel-Hirn-Trauma","Amnesie","Fraktur"]},

"Frau Gisela Brenner":{id:"fk8",sex:"w",vn:"Gisela",geb:"06.05.1944",cm:159,kg:56,ha:"Herr Doktor Reuter in Ziegelhausen",sys:"neuro",via:"Tochter",
 hpi:"Meine Mutter ist seit zwei Tagen ganz verändert. Sie erkennt mich manchmal nicht, redet durcheinander und ist nachts unruhig, sie läuft durch die Wohnung. Tagsüber ist sie dann schläfrig. Sie trinkt kaum etwas, der Pflegedienst sagt, der Urin riecht streng. Vor einer Woche hat der Hausarzt ihr eine neue Schlaftablette aufgeschrieben. Sonst ist sie für ihr Alter eigentlich klar im Kopf, nur ein bisschen vergesslich.",
 fam:"nicht erhebbar",
 vit:"RR 102/58 mmHg · HF 104/min · AF 20/min · SpO₂ 95 % · Temp. 38,1 °C · BZ 132 mg/dl · GCS 14",
 patientQs:["Ist das jetzt die Demenz, die plötzlich schlimmer geworden ist?","Kann die neue Schlaftablette daran schuld sein?","Muss meine Mutter festgebunden werden, wenn sie nachts aufsteht?"],
 oberarztQs:["Wie unterscheiden Sie ein Delir von einer Demenz?","Welche auslösenden Faktoren suchen Sie bei dieser Patientin?","Welche nichtmedikamentösen Maßnahmen gehören zur Delirbehandlung, und wann geben Sie Medikamente?"],
 traps:"This is a Fremdanamnese: thank the daughter, but also speak to the patient herself. Acute + fluctuating + inattentive = Delir, not 'Demenz'. The new sleeping pill (Zopiclon) is the probe – always ask what changed in the medication in the last two weeks. Fixierung is a last resort and needs a legal basis; say what you do instead. Lay terms: 'akuter Verwirrtheitszustand', 'Blasenentzündung', 'ausgetrocknet'.",
 lay:{open:"Ich bin die Tochter. Meine Mutter ist seit zwei Tagen ganz verwirrt, nachts unruhig, und sie trinkt kaum noch.",
  name:"Meine Mutter heißt Gisela Brenner. Ich bin ihre Tochter, Ute Lehmann.",dob:"Sie ist am sechsten Fünften neunzehnhundertvierundvierzig geboren, sie ist zweiundachtzig.",size:"Sie ist klein, ungefähr eins neunundfünfzig, und wiegt vielleicht sechsundfünfzig Kilo.",
  pmh:"Sie ist ein bisschen vergesslich, der Arzt nennt das leichte Demenz. Das Herz ist schwach. Und sie hat immer wieder Blasenentzündungen.",ops:"Soviel ich weiß, ist sie nie operiert worden.",
  meds:"Eine Wassertablette und eine Blutdrucktablette am Morgen. Und seit einer Woche abends eine Schlaftablette, die ist neu.",all:"Ja, sie verträgt ein bestimmtes Antibiotikum nicht, Sulfonamide steht im Allergiepass.",
  fam:"Das weiß ich nicht genau. Ihre Eltern sind im Krieg gestorben.",nox:"Sie raucht nicht und trinkt keinen Alkohol.",drugs:"Nein, natürlich nicht.",
  soc:"Sie lebt allein in ihrer Wohnung. Zweimal am Tag kommt der Pflegedienst, sie hat Pflegegrad zwei. Ich wohne zwanzig Minuten entfernt und komme jeden zweiten Tag.",
  mod:"Abends und nachts ist es am schlimmsten. Morgens ist sie manchmal fast normal.",prev:"Vor einem Jahr, bei einer Blasenentzündung, war sie auch zwei Tage durcheinander. Aber nicht so stark.",
  self:"Wir haben ihr nichts extra gegeben. Nur die neue Schlaftablette nimmt sie seit einer Woche.",vacc:"Grippe und Corona hat sie bekommen, das macht der Hausarzt.",reise:"Nein.",
  veg:{appetit:"Sie isst sehr wenig.",gewicht:"Sie ist dünner geworden in den letzten Monaten.",stuhl:"Sie hat eher Verstopfung.",wasser:"Der Urin riecht streng, und sie muss ständig zur Toilette. Der Pflegedienst sagt, die Einlage ist dunkel.",schlaf:"Nachts läuft sie herum, tagsüber döst sie.",fieber:"Der Pflegedienst hat heute früh 38 Grad gemessen.",durst:"Sie trinkt fast nichts, höchstens zwei Tassen am Tag."}},
 brief:"Frau Brenner ist eine 82-jährige Patientin, die von ihrer Tochter mit einer seit zwei Tagen bestehenden akuten Verwirrtheit vorgestellt wurde (Fremdanamnese). Die Tochter berichtete, ihre Mutter erkenne sie zeitweise nicht, rede zusammenhanglos und sei nachts unruhig, tagsüber dagegen schläfrig; die Symptomatik schwanke im Tagesverlauf. Die Trinkmenge sei deutlich reduziert, der Urin rieche auffällig, und am Morgen sei eine Temperatur von 38 °C gemessen worden. Eine Woche zuvor sei Zopiclon neu verordnet worden. Ein Sturz wurde verneint.\nAn Vorerkrankungen bestehen eine leichte Demenz, eine Herzinsuffizienz und rezidivierende Harnwegsinfekte. Voroperationen sind nicht bekannt. Medikation: Torasemid 10 mg, Ramipril, seit einer Woche Zopiclon zur Nacht. Es besteht eine Sulfonamidallergie. Nikotin- und Alkoholkonsum wurden verneint. Die Familienanamnese ist nicht erhebbar. Die Patientin lebt allein, wird zweimal täglich vom Pflegedienst versorgt und hat den Pflegegrad 2.\nDie Anamnese spricht für ein Delir bei Harnwegsinfekt und Exsikkose, begünstigt durch die Neuverordnung von Zopiclon. Differenzialdiagnostisch kommen eine Hyponatriämie, eine Pneumonie und ein Schlaganfall in Betracht. Wir empfehlen: Labor mit Elektrolyten und Entzündungswerten, Urinstatus und Urinkultur, Flüssigkeitsgabe, das Absetzen von Zopiclon, eine antibiotische Therapie unter Beachtung der Allergie, Maßnahmen zur Reorientierung und die Aufnahme in die Geriatrie.",
 kw:[["akut|plötzlich","fluktuierend|schwankend","Aufmerksamkeit","Bewusstsein|Vigilanz","Demenz.{0,60}(schleichend|chronisch|Monate)|schleichend"],["Infekt|Harnwegsinfekt","Exsikkose|Dehydratation|Elektrolyte","Medikament|Zopiclon|Schlafmittel","Schmerz|Harnverhalt|Obstipation","Umgebungswechsel|Schlafmangel"],["Reorientierung|Orientierung","Brille|Hörgerät","Angehörige|Bezugsperson","Tag-Nacht|Schlaf","Mobilisation|Flüssigkeit","Haloperidol|Risperidon|niedrig dosiert|nur bei"]],
 terms:["Delir","Demenz","Exsikkose","Harnwegsinfekt","Fremdanamnese"]}
};

// ===== P3 · the classic non-acute FSP pool (clinician report §3.3), cases fy1–fy12 =====
// Chart fields (cc, pmh, meds, all, soc, fam, dx, plan) are for the examiner's view only; the patient speaks from hpi and lay.
// oa = Oberarzt questions with model answers (a) and expected points (kw, regex alternatives). Medical content: see MANIFEST "facts to check".
const P3_FSP_NEW=[
{id:"fy1",age:36,sex:"w",name:"Frau Schubert",vn:"Katrin",geb:"09.02.1990",cm:172,kg:58,ha:"Herr Doktor Lang in Rohrbach",sys:"endo",job:"Bankkauffrau",scale:2,
 cc:"seit drei Monaten Herzklopfen, Schwitzen, Unruhe und acht Kilo Gewichtsverlust trotz gutem Appetit",
 hpi:"Seit ungefähr drei Monaten bin ich wie aufgedreht. Mein Herz klopft bis zum Hals, auch wenn ich nur auf dem Sofa sitze. Ich schwitze schon bei der kleinsten Anstrengung und kann Wärme überhaupt nicht mehr ertragen. Ich esse mehr als früher und habe trotzdem acht Kilo abgenommen. Meine Hände zittern, das fällt sogar den Kunden auf. Mein Mann sagt, meine Augen sehen irgendwie größer aus als früher.",
 pmh:"keine Vorerkrankungen; Z. n. Appendektomie mit 15",meds:"orales Kontrazeptivum; gelegentlich Ibuprofen bei Kopfschmerzen",all:"Nickel (Kontaktekzem), Erdbeeren (Urtikaria)",
 soc:"verheiratet, eine Tochter (6); raucht 10 Zigaretten/Tag seit 15 Jahren; Alkohol selten; viel Stress in der Bank",fam:"Mutter Schilddrüsenoperation mit 40; Vater Hypertonie",
 vit:"RR 145/70 mmHg · HF 116/min, regelmäßig · AF 16/min · SpO₂ 98 % · Temp. 37,4 °C",
 dx:"V. a. Hyperthyreose, am ehesten Morbus Basedow (endokrine Orbitopathie); DD: Schilddrüsenautonomie, Thyreoiditis (de Quervain, Hashimoto-Frühphase), Phäochromozytom, Angststörung, Malignom",
 plan:"Körperliche Untersuchung (Struma, Schwirren, Exophthalmus, Tremor), Labor: TSH, fT3, fT4, TRAK, TPO-AK, Blutbild; EKG; Schilddrüsensonographie mit Duplex, ggf. Szintigraphie; symptomatisch Propranolol, Thyreostatikum (Thiamazol) nach Befund; Nikotinkarenz; Überweisung Endokrinologie und Augenarzt",
 patientQs:["Ist das Krebs? Ich habe so viel abgenommen.","Was ist eine Szintigraphie – ist das gefährlich wegen der Strahlung?","Muss ich jetzt operiert werden wie meine Mutter?"],
 oa:[{q:"Welche Laborkonstellation erwarten Sie, und welcher Antikörper sichert die Diagnose?",a:"Erwartet wird ein supprimiertes TSH bei erhöhtem fT3 und fT4. Für einen Morbus Basedow spricht der Nachweis von TSH-Rezeptor-Antikörpern (TRAK); zusammen mit der endokrinen Orbitopathie ist die Diagnose dann praktisch gesichert.",kw:["TSH.{0,30}(supprimiert|erniedrigt|niedrig)","fT3|fT4|freie Schilddrüsenhormone","TRAK|TSH-Rezeptor","Orbitopathie|Augen"]},
  {q:"Warum ist das Rauchen bei dieser Patientin besonders relevant?",a:"Rauchen ist der wichtigste beeinflussbare Risikofaktor für die Entstehung und Verschlechterung der endokrinen Orbitopathie und verschlechtert das Ansprechen auf die Therapie. Außerdem erhöht es zusammen mit der Pille das Thromboserisiko. Wir raten dringend zum Rauchstopp.",kw:["Orbitopathie|Augen","Risikofaktor|verschlechtert","Rauchstopp|Nikotinkarenz|aufhören","Pille|Thrombose"]},
  {q:"Welche Nebenwirkung von Thiamazol müssen Sie der Patientin erklären, und woran erkennt sie sie?",a:"Die gefährlichste Nebenwirkung ist die Agranulozytose. Die Patientin soll bei Fieber, Halsschmerzen oder Entzündungen im Mund das Medikament sofort pausieren und am selben Tag ein Blutbild machen lassen. Weitere Nebenwirkungen sind Hautausschlag und eine Leberschädigung.",kw:["Agranulozytose|Leukozyten","Fieber","Halsschmerzen|Mund","sofort|Blutbild","Leber|Exanthem|Ausschlag"]}],
 traps:"Ask about stool frequency, cycle, heat intolerance and the eyes – those are the points examiners count. With the patient: 'Schilddrüsenüberfunktion', not 'Hyperthyreose'. Spell the name back (Schubert with b and t). Agranulocytosis under Thiamazol: 'Wenn Sie Fieber oder Halsschmerzen bekommen, sofort zum Arzt.'",
 terms:["Hyperthyreose","Struma","Exophthalmus","Tremor","Tachykardie"],
 lay:{open:"Ich bin seit ein paar Monaten so unruhig, mein Herz klopft ständig, und ich habe acht Kilo abgenommen, obwohl ich mehr esse als früher.",
  pmh:"Eigentlich bin ich gesund.",ops:"Mit fünfzehn hat man mir den Blinddarm rausgenommen.",meds:"Ich nehme die Pille. Und manchmal eine Ibuprofen gegen Kopfschmerzen.",all:"Ich vertrage keinen Modeschmuck mit Nickel, da bekomme ich einen Ausschlag. Und von Erdbeeren bekomme ich Quaddeln.",
  fam:"Meiner Mutter hat man mit vierzig die Schilddrüse operiert. Mein Vater hat hohen Blutdruck.",nox:"Ich rauche zehn Zigaretten am Tag, seit fünfzehn Jahren. Alkohol trinke ich selten.",drugs:"Nein.",
  soc:"Ich bin Bankkauffrau, das ist im Moment sehr stressig. Ich bin verheiratet und habe eine Tochter, sie ist sechs.",
  char:"Es ist kein Schmerz, eher ein Herzrasen und eine innere Unruhe.",mod:"Bei Wärme und Stress wird es schlimmer. Besser macht es eigentlich nichts.",prev:"Nein, so etwas hatte ich noch nie.",self:"Ich habe Baldrian probiert, das hat nichts gebracht.",
  vacc:"Ja, ich bin geimpft.",reise:"Nein, wir waren dieses Jahr nicht im Urlaub.",
  veg:{appetit:"Ich habe ständig Hunger und esse mehr als früher.",gewicht:"Ich habe in drei Monaten acht Kilo abgenommen, ohne es zu wollen.",stuhl:"Ich muss dreimal am Tag auf die Toilette, der Stuhl ist ganz weich.",wasser:"Normal.",schlaf:"Ich schlafe schlecht, ich bin nachts hellwach.",fieber:"Fieber habe ich nicht, aber mir ist ständig warm.",durst:"Ich trinke mehr als sonst, weil ich so schwitze."},
  gyn:"Meine Regel ist schwächer geworden und kommt unregelmäßig. Schwanger bin ich nicht, ich nehme die Pille."},
 brief:"Frau Schubert ist eine 36-jährige Patientin, die sich mit seit etwa drei Monaten bestehendem Herzklopfen, vermehrtem Schwitzen und innerer Unruhe vorstellte. Sie berichtete, sie habe in diesem Zeitraum trotz gesteigerten Appetits ungewollt acht Kilogramm abgenommen. Sie vertrage keine Wärme mehr, ihre Hände zitterten, und sie habe dreimal täglich weichen Stuhl. Dem Ehemann sei aufgefallen, dass ihre Augen größer wirkten. Die Menstruation sei schwächer und unregelmäßig geworden.\nVorerkrankungen sind nicht bekannt. Z. n. Appendektomie im Alter von 15 Jahren. Medikation: orales Kontrazeptivum, Ibuprofen bei Bedarf. Es bestehen eine Nickelallergie und eine Unverträglichkeit von Erdbeeren (Urtikaria). Die Patientin rauche seit 15 Jahren zehn Zigaretten pro Tag; Alkohol selten. Die Mutter sei im Alter von 40 Jahren an der Schilddrüse operiert worden. Die Patientin ist Bankkauffrau, verheiratet und hat eine Tochter.\nDie Anamnese spricht für eine Hyperthyreose, am ehesten bei Morbus Basedow mit beginnender endokriner Orbitopathie. Differenzialdiagnostisch kommen eine Schilddrüsenautonomie, eine Thyreoiditis und eine Angststörung in Betracht. Wir empfehlen: TSH, fT3, fT4, TRAK, EKG, Schilddrüsensonographie, symptomatisch einen Betablocker, nach Befund eine thyreostatische Therapie sowie die Vorstellung in der Endokrinologie und beim Augenarzt."},

{id:"fy2",age:58,sex:"w",name:"Frau Lehmann",vn:"Brigitte",geb:"17.10.1968",cm:163,kg:78,ha:"Frau Doktor Kaiser in Kirchheim",sys:"endo",job:"Sachbearbeiterin",scale:1,
 cc:"seit Monaten Müdigkeit, Frieren, Gewichtszunahme und Verstopfung",
 hpi:"Seit einem halben Jahr bin ich nur noch müde. Ich könnte den ganzen Tag schlafen und komme morgens kaum aus dem Bett. Mir ist ständig kalt, ich trage im Büro eine Strickjacke, während die Kollegen schwitzen. Ich habe sieben Kilo zugenommen, obwohl ich nicht mehr esse. Die Haare fallen aus, die Haut ist trocken, und ich habe Verstopfung. Meine Tochter sagt, ich bin so langsam geworden und vergesse vieles.",
 pmh:"arterielle Hypertonie; Z. n. Hysterektomie wegen Myomen mit 48",meds:"Amlodipin 5 mg 1-0-0",all:"keine bekannt",soc:"verheiratet, zwei erwachsene Kinder; Nichtraucherin; Alkohol selten; Sachbearbeiterin bei einer Versicherung",fam:"Schwester Hashimoto-Thyreoiditis; Mutter Diabetes mellitus Typ 2",
 vit:"RR 148/92 mmHg · HF 56/min · AF 14/min · SpO₂ 97 % · Temp. 36,0 °C",
 dx:"V. a. primäre Hypothyreose, am ehesten bei Hashimoto-Thyreoiditis; DD: Depression, Anämie, Schlafapnoe, Herzinsuffizienz, medikamentöse Ursache",
 plan:"TSH, fT4, TPO-Antikörper, Blutbild, Lipide, Kreatinin, Elektrolyte; Schilddrüsensonographie; Einleitung L-Thyroxin einschleichend (z. B. 25–50 µg morgens nüchtern), TSH-Kontrolle nach 6–8 Wochen; Aufklärung über Einnahme 30 Minuten vor dem Frühstück",
 patientQs:["Muss ich diese Tabletten jetzt mein Leben lang nehmen?","Nehme ich davon wieder ab?","Ist das erblich? Meine Schwester hat das auch."],
 oa:[{q:"Welche Laborwerte bestimmen Sie, und welche Konstellation erwarten Sie?",a:"Wir bestimmen TSH, fT4 und die TPO-Antikörper. Erwartet wird ein erhöhtes TSH bei erniedrigtem fT4, also eine manifeste primäre Hypothyreose; positive TPO-Antikörper sprechen für eine Hashimoto-Thyreoiditis.",kw:["TSH.{0,20}(erhöht|hoch)","fT4.{0,20}(erniedrigt|niedrig)","TPO","Hashimoto"]},
  {q:"Wie leiten Sie die Therapie ein, und was erklären Sie der Patientin zur Einnahme?",a:"L-Thyroxin wird einschleichend begonnen, bei älteren oder herzkranken Patienten niedrig dosiert. Die Tablette wird morgens nüchtern mit Wasser eingenommen, etwa 30 Minuten vor dem Frühstück und mit Abstand zu Eisen oder Calcium. Das TSH kontrollieren wir nach sechs bis acht Wochen.",kw:["L-Thyroxin|Levothyroxin","einschleichend|niedrig","nüchtern|30 Minuten","sechs|6|8 Wochen","Eisen|Calcium|Abstand"]},
  {q:"An welche Differenzialdiagnosen denken Sie bei Müdigkeit und Gewichtszunahme?",a:"Neben der Hypothyreose denke ich an eine Depression, eine Anämie, ein Schlafapnoesyndrom, eine Herzinsuffizienz und an Medikamentennebenwirkungen; seltener an ein Cushing-Syndrom.",kw:["Depression","Anämie","Schlafapnoe","Herzinsuffizienz","Medikament","Cushing"]}],
 traps:"Fatigue is a full vegetative history: ask about cold, constipation, hair, skin, mood, memory and cycle. Patient language: 'Schilddrüsenunterfunktion', 'die Schilddrüse arbeitet zu langsam'. Explain the morning, empty-stomach intake – examiners love asking 'Wie nehmen Sie das ein?'.",
 terms:["Hypothyreose","Obstipation","Bradykardie","Alopezie","Myxödem"],
 lay:{open:"Ich bin seit Monaten nur noch müde, friere ständig und habe zugenommen, obwohl ich nicht mehr esse.",pmh:"Ich habe hohen Blutdruck.",ops:"Mit achtundvierzig wurde mir wegen Myomen die Gebärmutter entfernt.",meds:"Nur eine Blutdrucktablette am Morgen, Amlodipin.",all:"Nein, keine.",
  fam:"Meine Schwester hat auch etwas mit der Schilddrüse, Hashimoto heißt das, glaube ich. Meine Mutter hat Zucker.",nox:"Ich rauche nicht. Alkohol trinke ich selten.",drugs:"Nein.",soc:"Ich arbeite als Sachbearbeiterin bei einer Versicherung. Ich bin verheiratet, die Kinder sind schon aus dem Haus.",
  mod:"Es ist jeden Tag gleich. Auch wenn ich lange schlafe, bin ich nicht ausgeruht.",prev:"Nein, so etwas kannte ich bisher nicht.",self:"Ich habe Vitamintabletten aus der Drogerie genommen, aber das hat nichts gebracht.",vacc:"Grippe und Corona, ja.",reise:"Nein.",
  veg:{appetit:"Eher weniger als früher.",gewicht:"Ich habe in einem halben Jahr sieben Kilo zugenommen.",stuhl:"Ich habe Verstopfung, ich gehe nur alle drei, vier Tage.",wasser:"Normal.",schlaf:"Ich schlafe viel, aber ich bin trotzdem müde.",fieber:"Nein, mir ist eher immer kalt."},
  gyn:"Die Gebärmutter wurde mir mit achtundvierzig entfernt, seitdem habe ich keine Regel mehr."},
 brief:"Frau Lehmann ist eine 58-jährige Patientin, die sich mit seit etwa sechs Monaten bestehender ausgeprägter Müdigkeit vorstellte. Sie berichtete, ihr sei ständig kalt, sie habe trotz unveränderter Nahrungsaufnahme sieben Kilogramm zugenommen und leide unter Obstipation. Zudem seien Haarausfall und trockene Haut aufgefallen; die Tochter beobachte eine Verlangsamung und Vergesslichkeit.\nAn Vorerkrankungen ist eine arterielle Hypertonie bekannt. Z. n. Hysterektomie bei Uterus myomatosus. Medikation: Amlodipin 5 mg 1-0-0. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint, Alkohol selten. Die Schwester leide an einer Hashimoto-Thyreoiditis. Die Patientin ist Sachbearbeiterin und verheiratet.\nDie Anamnese spricht für eine primäre Hypothyreose, am ehesten bei Hashimoto-Thyreoiditis. Differenzialdiagnostisch kommen eine Depression, eine Anämie und ein Schlafapnoesyndrom in Betracht. Wir empfehlen: TSH, fT4, TPO-Antikörper, Blutbild und Lipide, eine Schilddrüsensonographie sowie bei Bestätigung eine einschleichende Substitution mit L-Thyroxin und eine TSH-Kontrolle nach sechs bis acht Wochen."},

{id:"fy3",age:52,sex:"m",name:"Herr Brenner",vn:"Ralf",geb:"03.05.1974",cm:180,kg:86,ha:"Herr Doktor Schuster in Leimen",sys:"gi",job:"Maurer",scale:6,
 cc:"seit drei Wochen brennende Oberbauchschmerzen, heute zweimal schwarzer Stuhl",
 hpi:"Seit ungefähr drei Wochen brennt es hier oben in der Magengrube, vor allem nachts. Wenn ich etwas esse, wird es kurz besser. Wegen meines Rückens nehme ich seit einem Monat jeden Tag Ibuprofen. Heute Morgen war der Stuhlgang ganz schwarz und klebrig, wie Teer, und vorhin noch einmal. Beim Aufstehen ist mir schwindelig geworden.",
 pmh:"Lumbalgie seit Jahren; sonst gesund",meds:"Ibuprofen 600 mg 1-1-1 seit vier Wochen ohne Magenschutz",all:"keine bekannt",soc:"Maurer, verheiratet, zwei Kinder; raucht 20 Zigaretten/Tag; Alkohol 2–3 Bier täglich",fam:"Vater Magengeschwür",
 vit:"RR 104/64 mmHg · HF 108/min · AF 18/min · SpO₂ 97 % · Temp. 36,6 °C · Schellong: Anstieg der HF um 30/min",
 dx:"Obere gastrointestinale Blutung bei V. a. Ulcus duodeni (NSAR, Nikotin, ggf. Helicobacter pylori); DD: Ulcus ventriculi, erosive Gastritis, Ösophagusvarizenblutung, Mallory-Weiss-Läsion, Magenkarzinom",
 plan:"Zwei großlumige Zugänge, Labor (Blutbild, Gerinnung, Kreatinin, Harnstoff, Kreuzblut), Glasgow-Blatchford-Score, PPI hochdosiert i.v., Ibuprofen absetzen, Nahrungskarenz, Gastroskopie innerhalb von 24 Stunden mit Blutstillung und Helicobacter-Test, ggf. Eradikation; Transfusion bei Hb < 7 g/dl",
 patientQs:["Was ist eine Magenspiegelung? Bekomme ich da einen Schlauch in den Hals?","Muss ich jetzt operiert werden?","Was soll ich denn jetzt gegen meine Rückenschmerzen nehmen?"],
 oa:[{q:"Wie schätzen Sie das Blutungsrisiko ein, und wie dringlich ist die Endoskopie?",a:"Teerstuhl, Tachykardie und ein positiver Schellong-Test sprechen für eine relevante obere GI-Blutung. Ich berechne den Glasgow-Blatchford-Score; der Patient braucht eine Gastroskopie innerhalb von 24 Stunden, bei Instabilität sofort nach Stabilisierung.",kw:["Glasgow-Blatchford|Blatchford|Score","Tachykardie|Kreislauf|Schock","24 Stunden|24 h","sofort.{0,30}instabil|instabil","Teerstuhl|Meläna"]},
  {q:"Welche Erstmaßnahmen ergreifen Sie in der Notaufnahme?",a:"Zwei großlumige Zugänge, Labor mit Blutbild, Gerinnung und Kreuzblut, Volumengabe, hochdosierter Protonenpumpenhemmer intravenös, Nahrungskarenz und das Absetzen der NSAR. Transfusion restriktiv bei einem Hämoglobin unter 7 g/dl.",kw:["Zugänge|Zugang","Kreuzblut|Blutgruppe","PPI|Protonenpumpen|Pantoprazol","Volumen","nüchtern|Nahrungskarenz","absetzen|Ibuprofen","Transfusion|7"]},
  {q:"Welche Ursachen eines Ulkus kennen Sie, und wie verhindern Sie ein Rezidiv?",a:"Die wichtigsten Ursachen sind Helicobacter pylori und NSAR, dazu Rauchen und Stress. Zur Rezidivprophylaxe testen wir auf Helicobacter und eradizieren ihn, setzen NSAR ab oder geben sie nur mit PPI-Schutz und raten zum Rauchstopp.",kw:["Helicobacter","NSAR|Ibuprofen","Rauchen|Nikotin","Eradikation","PPI.{0,20}Schutz|Magenschutz|Protonenpumpen"]}],
 traps:"Ask every patient with black stool about NSAIDs, anticoagulants and iron – iron also makes stool black but not tarry. Lay terms: 'Magengeschwür', 'Magenspiegelung', 'Blut im Stuhl'. The back-pain question is a register test: offer Paracetamol or Metamizol and explain why Ibuprofen is out.",
 terms:["Ulkus","Meläna","Gastroskopie","Eradikation","Protonenpumpenhemmer"],
 lay:{open:"Ich habe seit drei Wochen ein Brennen im Oberbauch, und heute war mein Stuhlgang ganz schwarz.",pmh:"Ich habe es seit Jahren mit dem Rücken, sonst bin ich gesund.",ops:"Nein, noch nie.",meds:"Wegen dem Rücken nehme ich seit einem Monat dreimal am Tag Ibuprofen 600. Einen Magenschutz nehme ich nicht.",all:"Nein, keine.",
  fam:"Mein Vater hatte ein Magengeschwür.",nox:"Ich rauche eine Schachtel am Tag. Und nach der Arbeit trinke ich zwei, drei Bier.",drugs:"Nein.",soc:"Ich bin Maurer, verheiratet und habe zwei Kinder.",
  char:"Es ist ein Brennen, wie Säure, genau in der Magengrube.",rad:"Manchmal zieht es in den Rücken.",mod:"Nach dem Essen wird es für eine Weile besser. Nachts und mit leerem Magen ist es am schlimmsten.",prev:"So etwas hatte ich noch nie. Schwarzen Stuhl erst recht nicht.",self:"Ich habe Magentropfen aus der Apotheke genommen.",
  vacc:"Tetanus habe ich, das braucht man auf dem Bau.",reise:"Nein.",veg:{appetit:"Wegen dem Brennen esse ich weniger.",gewicht:"Unverändert.",stuhl:"Heute zweimal ganz schwarz und klebrig, wie Teer.",wasser:"Normal.",schlaf:"Nachts wache ich vom Brennen auf.",fieber:"Nein."}},
 brief:"Herr Brenner ist ein 52-jähriger Patient, der sich mit seit drei Wochen bestehenden brennenden epigastrischen Schmerzen und zweimaligem Teerstuhl am Aufnahmetag vorstellte. Er berichtete, die Schmerzen träten vor allem nachts und bei leerem Magen auf und besserten sich nach dem Essen. Beim Aufstehen sei ihm schwindelig geworden. Er nehme seit vier Wochen wegen Rückenschmerzen täglich dreimal Ibuprofen 600 mg ohne Magenschutz ein.\nAn Vorerkrankungen ist eine chronische Lumbalgie bekannt. Voroperationen wurden verneint. Medikation: Ibuprofen 600 mg 1-1-1. Allergien sind nicht bekannt. Der Patient rauche 20 Zigaretten pro Tag und trinke täglich zwei bis drei Bier. Der Vater habe ein Magengeschwür gehabt. Der Patient ist Maurer und verheiratet.\nDie Anamnese spricht für eine obere gastrointestinale Blutung bei Verdacht auf ein NSAR-assoziiertes Ulcus duodeni. Differenzialdiagnostisch kommen ein Ulcus ventriculi, eine erosive Gastritis und eine Varizenblutung in Betracht. Wir empfehlen: zwei großlumige Zugänge, Labor mit Blutbild und Kreuzblut, hochdosierte Protonenpumpenhemmer intravenös, das Absetzen von Ibuprofen, Nahrungskarenz und eine Gastroskopie innerhalb von 24 Stunden mit Helicobacter-Test."},

{id:"fy4",age:47,sex:"m",name:"Herr Kuhn",vn:"Oliver",geb:"22.11.1978",cm:177,kg:98,ha:"Frau Doktor Neumann in Wieblingen",sys:"gi",job:"Taxifahrer",scale:5,
 cc:"seit Monaten Sodbrennen und brennender Druck hinter dem Brustbein, vor allem im Liegen",
 hpi:"Seit ein paar Monaten habe ich fast jeden Abend Sodbrennen. Es brennt hinter dem Brustbein und steigt bis in den Hals hoch, manchmal kommt saures Wasser in den Mund. Am schlimmsten ist es, wenn ich mich nach dem Essen hinlege oder mich bücke. Morgens bin ich oft heiser und muss husten. Heute Nacht war der Druck so stark, dass ich Angst hatte, es ist das Herz.",
 pmh:"Adipositas (BMI 31), arterielle Hypertonie",meds:"Candesartan 8 mg 1-0-0; Antazida bei Bedarf",all:"keine bekannt",soc:"Taxifahrer im Schichtdienst, verheiratet; raucht 15 Zigaretten/Tag; Alkohol am Wochenende; spätes, fettes Essen",fam:"Vater Herzinfarkt mit 62",
 vit:"RR 142/88 mmHg · HF 84/min · AF 14/min · SpO₂ 98 % · Temp. 36,6 °C",
 dx:"V. a. gastroösophageale Refluxkrankheit mit Refluxösophagitis; DD: koronare Herzkrankheit/akutes Koronarsyndrom, Ulkuskrankheit, eosinophile Ösophagitis, Ösophaguskarzinom",
 plan:"Zuerst kardiale Ursache ausschließen: EKG, Troponin; Allgemeinmaßnahmen (Gewichtsreduktion, Oberkörperhochlagerung, keine späten Mahlzeiten, Rauch- und Alkoholreduktion); PPI-Therapie für 4–8 Wochen; Gastroskopie bei Alarmsymptomen (Dysphagie, Gewichtsverlust, Blutung, Anämie) oder fehlendem Ansprechen",
 patientQs:["Ist es wirklich nicht das Herz? Mein Vater hatte einen Herzinfarkt.","Muss ich die Magentabletten für immer nehmen?","Was kann ich selbst tun, damit es besser wird?"],
 oa:[{q:"Was müssen Sie bei retrosternalem Brennen zuerst ausschließen, und wie?",a:"Zuerst muss eine kardiale Ursache ausgeschlossen werden, insbesondere ein akutes Koronarsyndrom: 12-Kanal-EKG und Troponin, bei Risikofaktoren wie hier – Rauchen, Hypertonie, Adipositas, positive Familienanamnese – gegebenenfalls weitere kardiologische Abklärung.",kw:["Koronarsyndrom|Herzinfarkt|kardial|KHK","EKG","Troponin","Risikofaktoren|Familienanamnese"]},
  {q:"Welche Alarmsymptome erfordern eine Gastroskopie?",a:"Dysphagie, Odynophagie, ungewollter Gewichtsverlust, Zeichen einer Blutung oder Anämie, rezidivierendes Erbrechen, ein tastbarer Tumor, ein Beginn im höheren Lebensalter und fehlendes Ansprechen auf die PPI-Therapie.",kw:["Dysphagie|Schluckstörung","Gewichtsverlust","Blutung|Anämie","Erbrechen","Ansprechen|Therapieversagen"]},
  {q:"Welche Allgemeinmaßnahmen und welche Therapie empfehlen Sie?",a:"Gewichtsreduktion, Oberkörperhochlagerung beim Schlafen, keine späten und fettreichen Mahlzeiten, Verzicht auf Rauchen und Alkohol. Medikamentös ein Protonenpumpenhemmer für vier bis acht Wochen, danach Reduktion auf die niedrigste wirksame Dosis oder Bedarfstherapie.",kw:["Gewicht","Oberkörper|hochlagern|Kopfteil","späte|Mahlzeit","Rauchen|Alkohol","PPI|Protonenpumpen","vier|4|8 Wochen"]}],
 traps:"The examiners want to see the cardiac work-up before anything else – father with an infarction, smoker, hypertension. Lay terms: 'Sodbrennen', 'Rückfluss von Magensäure in die Speiseröhre', 'Magenspiegelung'. Do not promise that it is 'nur der Magen' before the ECG and troponin.",
 terms:["Refluxösophagitis","Sodbrennen","Dysphagie","Gastroskopie","Protonenpumpenhemmer"],
 lay:{open:"Ich habe seit Monaten Sodbrennen, und heute Nacht hat es hinter dem Brustbein so gedrückt, dass ich Angst um mein Herz hatte.",pmh:"Ich habe hohen Blutdruck, und ich wiege zu viel.",ops:"Nein, ich bin noch nie operiert worden.",meds:"Eine Blutdrucktablette am Morgen, Candesartan. Gegen das Sodbrennen lutsche ich Magentabletten aus der Apotheke.",all:"Nein, keine.",
  fam:"Mein Vater hatte mit zweiundsechzig einen Herzinfarkt.",nox:"Ich rauche fünfzehn Zigaretten am Tag. Am Wochenende trinke ich Bier.",drugs:"Nein.",soc:"Ich fahre Taxi, meistens nachts. Ich bin verheiratet. Ich esse oft spät und schnell, Döner oder Pommes.",
  char:"Es ist ein Brennen hinter dem Brustbein, das bis in den Hals hochsteigt.",rad:"Es zieht nach oben in den Hals, nicht in den Arm.",mod:"Im Liegen und beim Bücken wird es schlimmer, nach spätem Essen auch. Die Magentabletten helfen ein bisschen.",prev:"Sodbrennen habe ich schon lange, aber so stark wie heute Nacht war es noch nie.",self:"Die Magentabletten aus der Apotheke, mehrmals am Tag.",
  vacc:"Ja, das Übliche.",reise:"Nein.",veg:{appetit:"Der Appetit ist gut, eher zu gut.",gewicht:"Ich habe eher zugenommen.",stuhl:"Normal, nicht schwarz.",wasser:"Normal.",schlaf:"Ich wache nachts vom Brennen auf und muss mich aufsetzen.",fieber:"Nein."}},
 brief:"Herr Kuhn ist ein 47-jähriger Patient, der sich mit seit Monaten bestehendem Sodbrennen und einem in der Nacht verstärkten retrosternalen Brennen vorstellte. Er berichtete, die Beschwerden träten vor allem im Liegen, beim Bücken und nach späten Mahlzeiten auf und stiegen bis in den Hals; gelegentlich komme saure Flüssigkeit in den Mund. Morgens sei er häufig heiser. Dysphagie, Gewichtsverlust und Teerstuhl wurden verneint.\nAn Vorerkrankungen bestehen eine Adipositas und eine arterielle Hypertonie. Voroperationen wurden verneint. Medikation: Candesartan 8 mg 1-0-0, Antazida bei Bedarf. Allergien sind nicht bekannt. Der Patient rauche 15 Zigaretten pro Tag und trinke am Wochenende Alkohol. Der Vater habe mit 62 Jahren einen Myokardinfarkt erlitten. Der Patient ist Taxifahrer im Schichtdienst und verheiratet.\nDie Anamnese spricht am ehesten für eine gastroösophageale Refluxkrankheit. Differenzialdiagnostisch ist vorrangig ein akutes Koronarsyndrom auszuschließen; außerdem kommen eine Ulkuskrankheit und eine Ösophagitis anderer Ursache in Betracht. Wir empfehlen: EKG und Troponin, Allgemeinmaßnahmen zur Lebensstiländerung, einen Protonenpumpenhemmer für vier bis acht Wochen und eine Gastroskopie bei Alarmsymptomen oder fehlendem Ansprechen."},

{id:"fy5",age:44,sex:"w",name:"Frau Wolf",vn:"Sandra",geb:"28.03.1982",cm:165,kg:84,ha:"Herr Doktor Hertel in Eppelheim",sys:"gi",job:"Erzieherin",scale:8,
 cc:"seit gestern Abend kolikartige Schmerzen im rechten Oberbauch nach fettem Essen, Fieber",
 hpi:"Gestern Abend gab es bei uns Schweinebraten mit Soße. Zwei Stunden später bekam ich krampfartige Schmerzen rechts oben unter den Rippen, die bis in die rechte Schulter ziehen. Ich habe zweimal erbrochen. Seit heute Morgen ist der Schmerz dauernd da, und ich habe 38,6 Fieber. Gelb bin ich nicht, sagt mein Mann. Solche Anfälle hatte ich schon zweimal, aber die waren nach ein paar Stunden vorbei.",
 pmh:"Adipositas; bekannte Cholezystolithiasis seit 2024",meds:"orales Kontrazeptivum",all:"Pflaster (Kontaktdermatitis)",soc:"Erzieherin, verheiratet, drei Kinder; Nichtraucherin; Alkohol selten",fam:"Mutter und Schwester Gallensteine",
 vit:"RR 132/80 mmHg · HF 102/min · AF 18/min · SpO₂ 98 % · Temp. 38,6 °C",
 dx:"Akute Cholezystitis bei Cholezystolithiasis; DD: Choledocholithiasis, Cholangitis, biliäre Pankreatitis, Ulcus duodeni, Pyelonephritis rechts, Hinterwandinfarkt",
 plan:"Labor (Blutbild, CRP, Bilirubin, AP, Gamma-GT, GOT, GPT, Lipase), Schwangerschaftstest, Abdomensonographie (Wandverdickung, Murphy-Zeichen, Steine, Gallengang), Analgesie mit Metamizol, Antibiose, Nahrungskarenz; frühe laparoskopische Cholezystektomie innerhalb von 72 Stunden",
 patientQs:["Muss die Gallenblase jetzt raus? Kann man ohne Gallenblase leben?","Kann ich meine Kinder nach der Operation hochheben?","Kommt das, weil ich zu dick bin?"],
 oa:[{q:"Welche Untersuchungsbefunde und Laborwerte sprechen für eine akute Cholezystitis?",a:"Klinisch ein positives Murphy-Zeichen, Fieber und Druckschmerz im rechten Oberbauch; laborchemisch Leukozytose und CRP-Erhöhung; sonographisch eine verdickte, geschichtete Gallenblasenwand, Steine und ein sonographisches Murphy-Zeichen.",kw:["Murphy","Fieber","Leukozytose|CRP","Wandverdickung|Wand.{0,20}verdickt|dreigeschichtet","Sonograph"]},
  {q:"Wie unterscheiden Sie eine Cholezystitis von einer Cholangitis?",a:"Bei der Cholangitis ist der Gallengang betroffen: Charcot-Trias mit Fieber, Ikterus und Oberbauchschmerz, erhöhtes Bilirubin und Cholestaseparameter sowie ein erweiterter Gallengang. Die Cholangitis braucht eine dringliche ERCP, die Cholezystitis die Cholezystektomie.",kw:["Ikterus|Bilirubin","Charcot","Gallengang","ERCP","Cholezystektomie"]},
  {q:"Wann operieren Sie, und welche Komplikationen erklären Sie der Patientin?",a:"Wir empfehlen die frühe laparoskopische Cholezystektomie innerhalb von 72 Stunden. Risiken sind Blutung, Infektion, Verletzung des Gallengangs, Galleleck und selten die Umstellung auf eine offene Operation.",kw:["72|früh","laparoskopisch|Bauchspiegelung","Gallengang","Blutung|Infektion","Konversion|offen"]}],
 traps:"Fat, female, forty, fertile – but say it respectfully. Ask about jaundice, dark urine and pale stool to separate cholecystitis from bile-duct stones. Pregnancy test before imaging and surgery. Lay terms: 'Gallenblasenentzündung', 'Gallensteine', 'Schlüssellochoperation'.",
 terms:["Cholezystitis","Cholezystolithiasis","Kolik","Cholezystektomie","Ikterus"],
 lay:{open:"Ich habe seit gestern Abend krampfartige Schmerzen rechts oben im Bauch, und seit heute habe ich Fieber.",pmh:"Ich habe Gallensteine, das weiß man seit zwei Jahren. Und ich habe Übergewicht.",ops:"Nein, operiert wurde ich noch nie. Meine drei Kinder sind normal auf die Welt gekommen.",meds:"Nur die Pille.",all:"Von Pflastern bekomme ich einen roten, juckenden Ausschlag.",
  fam:"Meine Mutter und meine Schwester haben auch Gallensteine.",nox:"Ich rauche nicht. Alkohol trinke ich selten.",drugs:"Nein.",soc:"Ich bin Erzieherin im Kindergarten. Ich bin verheiratet und habe drei Kinder.",
  char:"Am Anfang waren es Krämpfe, jetzt ist es ein dauernder, starker Schmerz.",rad:"Es zieht in die rechte Schulter.",mod:"Wenn ich tief einatme, tut es mehr weh. Nach fettem Essen fängt es an.",prev:"Ja, zweimal nach fettem Essen, aber da war es nach ein paar Stunden vorbei und ohne Fieber.",self:"Ich habe Buscopan genommen, das hat diesmal nicht geholfen.",
  vacc:"Ja, im Kindergarten muss man alles haben.",reise:"Nein.",veg:{appetit:"Ich habe keinen Appetit, mir ist übel.",gewicht:"Unverändert.",stuhl:"Normal gefärbt, gestern zuletzt.",wasser:"Der Urin ist normal hell.",schlaf:"Heute Nacht kaum geschlafen.",fieber:"Heute Morgen 38,6."},
  gyn:"Meine letzte Regel war vor drei Wochen. Ich nehme die Pille, schwanger bin ich nicht."},
 brief:"Frau Wolf ist eine 44-jährige Patientin, die sich mit seit dem Vorabend bestehenden Schmerzen im rechten Oberbauch und Fieber vorstellte. Sie berichtete, die Schmerzen hätten etwa zwei Stunden nach einer fettreichen Mahlzeit kolikartig begonnen, strahlten in die rechte Schulter aus und seien seit dem Morgen dauerhaft vorhanden (8/10). Sie habe zweimal erbrochen und am Morgen 38,6 °C gemessen. Ikterus, dunkler Urin und heller Stuhl wurden verneint. Zwei ähnliche, kürzere Episoden ohne Fieber seien vorausgegangen.\nAn Vorerkrankungen bestehen eine Adipositas und eine bekannte Cholezystolithiasis. Voroperationen wurden verneint. Medikation: orales Kontrazeptivum. Es besteht eine Pflasterunverträglichkeit. Nikotinkonsum wurde verneint. Mutter und Schwester litten ebenfalls an Gallensteinen. Die Patientin ist Erzieherin, verheiratet und hat drei Kinder.\nDie Anamnese spricht für eine akute Cholezystitis bei Cholezystolithiasis. Differenzialdiagnostisch kommen eine Choledocholithiasis, eine Cholangitis und eine biliäre Pankreatitis in Betracht. Wir empfehlen: Labor mit Cholestaseparametern und Lipase, Schwangerschaftstest, Abdomensonographie, Analgesie, Antibiose und die frühe laparoskopische Cholezystektomie."},

{id:"fy6",age:29,sex:"m",name:"Herr Schröder",vn:"Tim",geb:"14.06.1997",cm:183,kg:74,ha:"Frau Doktor Haug in der Altstadt",sys:"infekt",job:"Grafikdesigner",scale:3,
 cc:"seit einer Woche Abgeschlagenheit, Übelkeit, seit zwei Tagen gelbe Augen und dunkler Urin; vor vier Wochen Rückkehr aus Marokko",
 hpi:"Seit einer Woche fühle ich mich schlapp, als hätte ich eine Grippe. Mir ist übel, und ich habe keinen Appetit. Vorgestern hat meine Freundin gesagt, meine Augen sind gelb. Der Urin ist dunkel wie Cola, und der Stuhl ist ganz hell. Rechts unter den Rippen drückt es ein bisschen. Vor vier Wochen bin ich aus einem Rucksackurlaub in Marokko zurückgekommen.",
 pmh:"bisher gesund",meds:"keine; Paracetamol 500 mg mehrmals in der letzten Woche",all:"keine bekannt",soc:"Grafikdesigner, lebt mit Partnerin; Nichtraucher; Alkohol am Wochenende; keine Drogen; Impfung gegen Hepatitis A nicht erinnerlich",fam:"keine Besonderheiten",
 vit:"RR 122/74 mmHg · HF 82/min · AF 14/min · SpO₂ 99 % · Temp. 37,9 °C",
 dx:"V. a. akute Hepatitis A nach Reise; DD: Hepatitis B/C/E, medikamentös-toxische Hepatitis (Paracetamol), EBV/CMV, Choledocholithiasis, Autoimmunhepatitis",
 plan:"Labor (GOT, GPT, Bilirubin, AP, Gamma-GT, Quick/INR, Albumin, Blutbild, Kreatinin), Hepatitis-Serologie (Anti-HAV-IgM, HBsAg, Anti-HBc, Anti-HCV, Anti-HEV), Sonographie; Paracetamol und Alkohol meiden; Hygieneberatung, Meldung an das Gesundheitsamt; Riegelungsimpfung der Kontaktpersonen; ambulante Verlaufskontrolle bei stabiler Gerinnung",
 patientQs:["Habe ich meine Freundin angesteckt?","Ist das gefährlich für meine Leber? Bleibt etwas zurück?","Darf ich wieder Alkohol trinken?"],
 oa:[{q:"Welche Laborkonstellation erwarten Sie, und welcher Befund sichert die Diagnose?",a:"Stark erhöhte Transaminasen, typischerweise mit GPT über GOT, dazu ein erhöhtes Bilirubin. Gesichert wird die akute Hepatitis A durch Anti-HAV-IgM. Wichtig für die Schwere ist die Gerinnung, also Quick bzw. INR.",kw:["Transaminasen|GPT|GOT","Bilirubin","Anti-HAV-IgM|IgM","Quick|INR|Gerinnung"]},
  {q:"Wer muss informiert werden, und was raten Sie den Kontaktpersonen?",a:"Die akute Hepatitis A ist nach dem Infektionsschutzgesetz meldepflichtig; das Gesundheitsamt wird namentlich informiert. Enge Kontaktpersonen sollten möglichst bald geimpft werden (Riegelungsimpfung). Der Patient soll auf strenge Händehygiene achten und keine Speisen für andere zubereiten.",kw:["Gesundheitsamt|Meldepflicht|melden|IfSG","Kontaktpersonen","Impfung|Riegelung","Händehygiene|Hygiene"]},
  {q:"Woran erkennen Sie einen schweren Verlauf, der eine stationäre Aufnahme erfordert?",a:"Warnzeichen eines akuten Leberversagens sind ein Abfall des Quick bzw. Anstieg der INR, eine hepatische Enzephalopathie mit Verwirrtheit oder Schläfrigkeit, Hypoglykämien und ein steigendes Bilirubin. Dann ist die stationäre Aufnahme und die Kontaktaufnahme mit einem Transplantationszentrum nötig.",kw:["Quick|INR|Gerinnung","Enzephalopathie|Verwirrtheit|Bewusstsein","Hypoglykämie|Blutzucker","Leberversagen","Transplantation"]}],
 traps:"Travel, food, sexual and vaccination history are the points of this case – ask them all, tactfully. Ask exactly how much Paracetamol he took. Lay terms: 'Leberentzündung', 'Gelbsucht'. Meldepflicht and protecting the partner must come up without being asked.",
 terms:["Hepatitis","Ikterus","Transaminasen","Meldepflicht","Riegelungsimpfung"],
 lay:{open:"Ich fühle mich seit einer Woche schlapp und habe keinen Appetit, und seit zwei Tagen sind meine Augen gelb.",pmh:"Nein, ich bin gesund.",ops:"Nein, noch nie.",meds:"Ich nehme sonst nichts. Letzte Woche habe ich ein paarmal Paracetamol genommen, höchstens drei Tabletten am Tag.",all:"Nein, keine.",
  fam:"Bei uns sind alle gesund.",nox:"Ich rauche nicht. Am Wochenende trinke ich ein paar Bier.",drugs:"Nein, keine Drogen. Gespritzt habe ich mir noch nie etwas.",soc:"Ich bin Grafikdesigner und arbeite meistens im Homeoffice. Ich wohne mit meiner Freundin zusammen.",
  char:"Es ist ein leichter Druck rechts unter den Rippen, kein richtiger Schmerz.",mod:"Nach dem Essen wird die Übelkeit schlimmer.",prev:"Nein, noch nie.",self:"Ein paar Paracetamol, und Kamillentee.",
  vacc:"Ich glaube, ich bin als Kind gegen die normalen Sachen geimpft. Für Marokko habe ich mich nicht extra impfen lassen.",reise:"Ja, ich war im September drei Wochen mit dem Rucksack in Marokko. Wir haben viel an Straßenständen gegessen und manchmal Leitungswasser getrunken. Vor vier Wochen bin ich zurückgekommen.",
  veg:{appetit:"Ich habe gar keinen Appetit, und mir ekelt vor Fett.",gewicht:"Ich habe vielleicht zwei Kilo abgenommen.",stuhl:"Der Stuhl ist seit zwei Tagen ganz hell, fast weiß.",wasser:"Der Urin ist dunkel wie Cola.",schlaf:"Ich bin ständig müde.",fieber:"Am Anfang hatte ich leichtes Fieber, so 38."}},
 brief:"Herr Schröder ist ein 29-jähriger Patient, der sich mit seit einer Woche bestehender Abgeschlagenheit, Übelkeit und Inappetenz sowie seit zwei Tagen bestehendem Sklerenikterus vorstellte. Er berichtete, der Urin sei dunkel und der Stuhl entfärbt; im rechten Oberbauch bestehe ein leichtes Druckgefühl. Vier Wochen zuvor sei er von einer dreiwöchigen Rucksackreise nach Marokko zurückgekehrt, wo er an Straßenständen gegessen und Leitungswasser getrunken habe. Eine Reiseimpfung sei nicht erfolgt. In der letzten Woche habe er bis zu drei Tabletten Paracetamol 500 mg täglich eingenommen.\nVorerkrankungen und Voroperationen sind nicht bekannt. Keine Dauermedikation. Allergien sind nicht bekannt. Nikotin- und Drogenkonsum wurden verneint, Alkohol am Wochenende. Die Familienanamnese ist unauffällig. Der Patient ist Grafikdesigner und lebt mit seiner Partnerin.\nDie Anamnese spricht für eine akute Hepatitis A nach Auslandsreise. Differenzialdiagnostisch kommen eine Hepatitis B, C oder E, eine medikamentös-toxische Hepatitis und eine Choledocholithiasis in Betracht. Wir empfehlen: Leberwerte, Bilirubin, Gerinnung, Hepatitis-Serologie, eine Abdomensonographie, den Verzicht auf Alkohol und Paracetamol, die Meldung an das Gesundheitsamt sowie die Impfung der Kontaktpersonen."},

{id:"fy7",age:67,sex:"m",name:"Herr Graf",vn:"Dieter",geb:"11.01.1959",cm:175,kg:71,ha:"Herr Doktor Albers in Wiesloch",sys:"gi",job:"Rentner, früher Postbeamter",scale:2,
 cc:"seit drei Monaten Blut im Stuhl, Wechsel von Durchfall und Verstopfung, sechs Kilo Gewichtsverlust",
 hpi:"Seit ungefähr drei Monaten ist mein Stuhlgang anders als früher. Mal habe ich Durchfall, dann wieder tagelang Verstopfung. Ein paarmal war Blut am Stuhl, dunkelrot, untergemischt. Ich habe sechs Kilo abgenommen, ohne Diät. Ich bin schneller müde als früher. Nachts schwitze ich manchmal so, dass ich das Schlafanzughemd wechseln muss. Zur Darmspiegelung bin ich nie gegangen, ich hatte Angst davor.",
 pmh:"arterielle Hypertonie; Diabetes mellitus Typ 2; Hämorrhoiden",meds:"Ramipril 5 mg 1-0-0, Metformin 1000 mg 1-0-1",all:"keine bekannt",soc:"Rentner, verheiratet; Ex-Raucher seit 10 Jahren (25 py); Alkohol 1–2 Bier täglich; isst viel Wurst",fam:"Bruder Darmkrebs mit 58",
 vit:"RR 136/82 mmHg · HF 92/min · AF 14/min · SpO₂ 97 % · Temp. 36,7 °C · Hb 10,1 g/dl (Hausarzt)",
 dx:"V. a. kolorektales Karzinom mit B-Symptomatik und Eisenmangelanämie; DD: Divertikelkrankheit, chronisch-entzündliche Darmerkrankung, Polypen, Hämorrhoidalblutung, ischämische Kolitis",
 plan:"Digital-rektale Untersuchung, Labor (Blutbild, Ferritin, CEA als Verlaufsparameter, Leberwerte), Koloskopie mit Biopsie, bei Bestätigung Staging (CT Thorax/Abdomen), Tumorkonferenz; Aufklärung des Patienten in Ruhe, Angehörige einbeziehen auf Wunsch",
 patientQs:["Ist das Krebs, wie bei meinem Bruder?","Was ist eine Darmspiegelung genau? Tut das weh?","Bekomme ich dann einen künstlichen Darmausgang?"],
 oa:[{q:"Welche Befunde sprechen hier für ein Malignom?",a:"Alter, Änderung der Stuhlgewohnheiten, peranaler Blutabgang, ungewollter Gewichtsverlust und Nachtschweiß als B-Symptomatik, die Anämie und die positive Familienanamnese mit einem an Darmkrebs erkrankten Bruder.",kw:["Stuhlgewohnheit|Durchfall.{0,20}Verstopfung|Wechsel","Blut","Gewichtsverlust","Nachtschweiß|B-Symptom","Anämie","Familienanamnese|Bruder"]},
  {q:"Wie erklären Sie dem Patienten die Koloskopie?",a:"Bei der Darmspiegelung schauen wir mit einer kleinen Kamera den Dickdarm von innen an. Am Vortag trinken Sie eine Abführlösung, damit der Darm sauber ist. Sie bekommen ein Schlafmittel und merken nichts. Wir können Gewebeproben entnehmen und Polypen gleich entfernen; das Risiko einer Blutung oder Verletzung ist gering.",kw:["Kamera|Schlauch","Abführ|sauber","Schlafmittel|schlafen|Beruhigung","Probe|Gewebe|Biopsie","Risiko|Blutung|Verletzung"]},
  {q:"Wie geht es nach einer histologischen Sicherung weiter?",a:"Es folgt das Staging mit CT von Thorax und Abdomen, bei Rektumkarzinom zusätzlich MRT des Beckens, sowie die Bestimmung des CEA als Verlaufsparameter. Danach wird der Patient in der interdisziplinären Tumorkonferenz vorgestellt, die über Operation und gegebenenfalls Chemotherapie entscheidet.",kw:["Staging","CT","CEA","Tumorkonferenz|interdisziplinär","Operation|Chemotherapie"]}],
 traps:"This is a breaking-suspicion case: do not say 'Krebs' before you have evidence, but do not hide it either. Use the patient's own words and the SPIKES rhythm. Ask about B symptoms and the brother's age at diagnosis. Lay terms: 'Darmspiegelung', 'Gewebeprobe', 'künstlicher Darmausgang' only if he asks.",
 terms:["Kolorektales Karzinom","Hämatochezie","B-Symptomatik","Koloskopie","Anämie"],
 lay:{open:"Mein Stuhlgang ist seit drei Monaten anders, mal Durchfall, mal Verstopfung, und ein paarmal war Blut dabei.",pmh:"Ich habe hohen Blutdruck und Zucker. Hämorrhoiden habe ich auch, deshalb habe ich bei dem Blut erst gar nicht an etwas Schlimmes gedacht.",ops:"Nein, operiert worden bin ich noch nie.",meds:"Ramipril für den Blutdruck am Morgen und Metformin morgens und abends.",all:"Nein, keine.",
  fam:"Mein Bruder hatte mit achtundfünfzig Darmkrebs. Er wurde operiert und lebt noch.",nox:"Ich habe vor zehn Jahren mit dem Rauchen aufgehört, davor fünfundzwanzig Jahre eine Schachtel am Tag. Ich trinke ein, zwei Bier am Abend.",drugs:"Nein.",soc:"Ich war bei der Post, jetzt bin ich Rentner. Ich bin verheiratet.",
  char:"Richtige Schmerzen habe ich nicht, manchmal krampft es im Unterbauch.",mod:"Nach dem Essen muss ich öfter, sonst gibt es nichts Besonderes.",prev:"Nein, so etwas hatte ich noch nie.",self:"Ich habe Flohsamen gegen die Verstopfung genommen.",
  vacc:"Grippe ja.",reise:"Nein.",veg:{appetit:"Ich habe weniger Appetit als früher.",gewicht:"Ich habe sechs Kilo abgenommen in drei Monaten, ohne Diät.",stuhl:"Mal Durchfall, mal Verstopfung, und ein paarmal Blut am Stuhl, dunkelrot und untergemischt.",wasser:"Normal.",schlaf:"Ich schwitze nachts manchmal so stark, dass ich mich umziehen muss.",fieber:"Fieber habe ich nicht gemessen."}},
 brief:"Herr Graf ist ein 67-jähriger Patient, der sich mit seit etwa drei Monaten veränderten Stuhlgewohnheiten mit Wechsel von Diarrhö und Obstipation vorstellte. Er berichtete über mehrfache peranale Blutabgänge, dunkelrot und dem Stuhl beigemischt, einen ungewollten Gewichtsverlust von sechs Kilogramm in drei Monaten, vermehrte Müdigkeit und gelegentlichen Nachtschweiß. Eine Vorsorgekoloskopie sei nie erfolgt. Beim Hausarzt sei ein Hämoglobin von 10,1 g/dl gemessen worden.\nAn Vorerkrankungen bestehen eine arterielle Hypertonie, ein Diabetes mellitus Typ 2 und ein Hämorrhoidalleiden. Voroperationen wurden verneint. Medikation: Ramipril 5 mg 1-0-0, Metformin 1000 mg 1-0-1. Allergien sind nicht bekannt. Der Patient sei seit zehn Jahren Nichtraucher (25 Packungsjahre) und trinke täglich ein bis zwei Bier. Der Bruder sei mit 58 Jahren an einem Kolonkarzinom erkrankt. Der Patient ist Rentner und verheiratet.\nDie Anamnese mit B-Symptomatik und Anämie spricht für ein kolorektales Karzinom. Differenzialdiagnostisch kommen eine Divertikelkrankheit, eine chronisch-entzündliche Darmerkrankung und eine Hämorrhoidalblutung in Betracht. Wir empfehlen: digital-rektale Untersuchung, Blutbild, Ferritin und CEA, eine Koloskopie mit Biopsie und bei Bestätigung ein Staging mit anschließender Vorstellung in der Tumorkonferenz."},

{id:"fy8",age:24,sex:"w",name:"Frau Albrecht",vn:"Lena",geb:"30.09.2002",cm:168,kg:52,ha:"Frau Doktor Möller in Neuenheim",sys:"gi",job:"Studentin (Pharmazie)",scale:6,
 cc:"seit sechs Wochen blutig-schleimige Durchfälle bis zehnmal täglich, krampfartige Bauchschmerzen, Gewichtsverlust",
 hpi:"Seit ungefähr sechs Wochen habe ich Durchfall, acht- bis zehnmal am Tag, auch nachts. Es ist Blut und Schleim dabei. Vor dem Stuhlgang bekomme ich Krämpfe im linken Unterbauch, und ich habe ständig das Gefühl, zur Toilette zu müssen, auch wenn nichts mehr kommt. Ich habe vier Kilo abgenommen. Abends habe ich manchmal leichtes Fieber.",
 pmh:"bisher gesund",meds:"orales Kontrazeptivum",all:"keine bekannt",soc:"Pharmaziestudentin, lebt in einer WG; Nichtraucherin; Alkohol selten; keine Reise; keine Antibiotika in letzter Zeit",fam:"Onkel Morbus Crohn",
 vit:"RR 108/66 mmHg · HF 104/min · AF 16/min · SpO₂ 99 % · Temp. 37,8 °C",
 dx:"V. a. Erstmanifestation einer Colitis ulcerosa (mittelschwerer Schub); DD: Morbus Crohn, infektiöse Kolitis (Campylobacter, Salmonellen, Clostridioides difficile), mikroskopische Kolitis",
 plan:"Labor (Blutbild, CRP, Elektrolyte, Albumin, Ferritin), Stuhlkulturen und C.-difficile-Toxin, Calprotectin, Abdomensonographie, Ileokoloskopie mit Stufenbiopsien; Therapie je nach Befund mit Mesalazin oral und rektal, bei Bedarf Glukokortikoide; Thromboseprophylaxe bei stationärer Aufnahme",
 patientQs:["Ist das eine Krankheit für immer?","Kann ich mein Studium weitermachen?","Muss ich jetzt Kortison nehmen? Davon nimmt man doch zu."],
 oa:[{q:"Wie unterscheiden Sie Colitis ulcerosa und Morbus Crohn?",a:"Die Colitis ulcerosa beginnt im Rektum und breitet sich kontinuierlich nach proximal aus, sie betrifft nur die Schleimhaut des Kolons; typisch sind blutige Durchfälle. Der Morbus Crohn kann den gesamten Verdauungstrakt diskontinuierlich befallen, alle Wandschichten, oft das terminale Ileum, mit Fisteln, Abszessen und Stenosen.",kw:["Rektum","kontinuierlich","Schleimhaut|Mukosa","diskontinuierlich|Skip","transmural|alle Wandschichten","Fistel|Ileum"]},
  {q:"Was müssen Sie vor der Diagnose einer chronisch-entzündlichen Darmerkrankung ausschließen?",a:"Infektiöse Ursachen: Stuhlkulturen auf bakterielle Erreger, Clostridioides-difficile-Toxin, gegebenenfalls Parasiten, sowie eine Medikamentenanamnese, zum Beispiel Antibiotika oder NSAR.",kw:["Infekt|infektiös","Stuhlkultur|Stuhl","Clostridi|difficile","Parasiten|Amöben","Antibiotika|NSAR|Medikament"]},
  {q:"Wie behandeln Sie einen mittelschweren Schub?",a:"Mesalazin oral und rektal als Basistherapie; bei unzureichendem Ansprechen systemische Glukokortikoide wie Prednisolon mit Ausschleichen. Bei steroidrefraktärem Verlauf Biologika oder Immunsuppressiva. Begleitend Flüssigkeit, Elektrolyte, gegebenenfalls Eisen und Thromboseprophylaxe.",kw:["Mesalazin|5-ASA","rektal|Klysma|Zäpfchen","Prednisolon|Kortison|Glukokortikoid","Biologika|Immunsuppress","Thromboseprophylaxe"]}],
 traps:"A young woman with bloody diarrhoea: ask about travel, antibiotics, other people affected, nocturnal stools, joints, eyes, skin and the family. Do not frighten her with 'chronisch' before a diagnosis, but be honest. Lay terms: 'Darmentzündung', 'Darmspiegelung'.",
 terms:["Colitis ulcerosa","Diarrhö","Tenesmen","Koloskopie","Mesalazin"],
 lay:{open:"Ich habe seit sechs Wochen Durchfall, bis zu zehnmal am Tag, mit Blut und Schleim.",pmh:"Nein, ich war bisher immer gesund.",ops:"Nein, noch nie.",meds:"Nur die Pille.",all:"Nein, keine.",fam:"Mein Onkel hat Morbus Crohn.",nox:"Ich rauche nicht. Alkohol trinke ich nur selten.",drugs:"Nein.",
  soc:"Ich studiere Pharmazie und wohne in einer WG. Im Moment schaffe ich kaum die Vorlesungen, weil ich ständig zur Toilette muss.",char:"Es sind Krämpfe, im linken Unterbauch, vor allem vor dem Stuhlgang.",rad:"Nein, es bleibt im Unterbauch.",mod:"Nach dem Stuhlgang wird es kurz besser. Nach dem Essen muss ich sofort.",prev:"Nein, so etwas hatte ich noch nie.",self:"Ich habe Kohletabletten genommen, das hat nichts geholfen.",
  vacc:"Ja, alle.",reise:"Nein, ich war dieses Jahr nicht im Ausland. Antibiotika habe ich auch nicht genommen.",veg:{appetit:"Ich esse wenig, weil ich danach sofort muss.",gewicht:"Ich habe vier Kilo abgenommen.",stuhl:"Acht- bis zehnmal am Tag, auch nachts, flüssig mit Blut und Schleim. Manchmal muss ich, und es kommt gar nichts.",wasser:"Normal.",schlaf:"Ich muss nachts zwei-, dreimal zur Toilette.",fieber:"Abends manchmal 37,8."},
  gyn:"Meine Regel kommt regelmäßig, ich nehme die Pille. Schwanger bin ich nicht."},
 brief:"Frau Albrecht ist eine 24-jährige Patientin, die sich mit seit sechs Wochen bestehenden blutig-schleimigen Diarrhöen bis zu zehnmal täglich, auch nachts, vorstellte. Sie berichtete über krampfartige Schmerzen im linken Unterbauch vor der Defäkation, imperativen Stuhldrang und Tenesmen. Sie habe vier Kilogramm abgenommen und abends subfebrile Temperaturen gemessen. Auslandsreisen und eine Antibiotikaeinnahme wurden verneint.\nVorerkrankungen und Voroperationen sind nicht bekannt. Medikation: orales Kontrazeptivum. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint, Alkohol selten. Ein Onkel leide an Morbus Crohn. Die Patientin ist Pharmaziestudentin und lebt in einer Wohngemeinschaft.\nDie Anamnese spricht für die Erstmanifestation einer Colitis ulcerosa. Differenzialdiagnostisch kommen ein Morbus Crohn und eine infektiöse Kolitis in Betracht. Wir empfehlen: Blutbild, CRP, Elektrolyte, Stuhlkulturen einschließlich Clostridioides-difficile-Toxin, Calprotectin, eine Ileokoloskopie mit Stufenbiopsien und nach Befund eine Therapie mit Mesalazin."},

{id:"fy9",age:63,sex:"w",name:"Frau Hartmann",vn:"Ursula",geb:"05.04.1963",cm:166,kg:82,ha:"Herr Doktor Böhm in Dossenheim",sys:"gi",job:"Bibliothekarin",scale:6,
 cc:"seit zwei Tagen Schmerzen im linken Unterbauch, Fieber 38,4 °C, Verstopfung",
 hpi:"Seit vorgestern tut es mir links unten im Bauch weh, erst leicht, jetzt immer stärker. Der Schmerz ist die ganze Zeit da. Seit gestern habe ich Fieber, heute Morgen 38,4. Ich habe seit drei Tagen keinen Stuhlgang gehabt. Übel ist mir ein bisschen, erbrochen habe ich nicht. Mein Hausarzt hat vor Jahren bei einer Darmspiegelung Ausstülpungen am Darm gefunden.",
 pmh:"bekannte Divertikulose des Sigmas (Koloskopie 2021), Adipositas, arterielle Hypertonie",meds:"Bisoprolol 5 mg 1-0-0, HCT 12,5 mg 1-0-0",all:"Penicillin (Urtikaria)",soc:"Bibliothekarin, verheiratet; Nichtraucherin; Alkohol selten; ballaststoffarme Ernährung",fam:"Mutter Divertikulitis",
 vit:"RR 138/84 mmHg · HF 98/min · AF 16/min · SpO₂ 98 % · Temp. 38,4 °C",
 dx:"Akute Sigmadivertikulitis („Linksappendizitis“); DD: Kolonkarzinom, ischämische Kolitis, Harnwegsinfekt/Pyelonephritis links, Adnexprozess, Obstipation",
 plan:"Labor (Blutbild, CRP, Kreatinin, Urinstatus), Abdomensonographie, CT Abdomen mit Kontrastmittel zur Stadieneinteilung (Abszess? Perforation?); bei unkomplizierter Divertikulitis ggf. ambulant ohne Antibiotikum, bei Fieber/Risikofaktoren Antibiose (Penicillinallergie beachten, z. B. Ciprofloxacin plus Metronidazol), flüssige Kost; Koloskopie 6–8 Wochen nach Abheilung",
 patientQs:["Muss der Darm operiert werden?","Was darf ich jetzt essen?","Kann das Krebs sein?"],
 oa:[{q:"Welche Bildgebung wählen Sie, und warum?",a:"Zunächst die Sonographie durch einen erfahrenen Untersucher; zur sicheren Stadieneinteilung und zum Ausschluss eines Abszesses oder einer Perforation die CT des Abdomens mit Kontrastmittel. Die Einteilung erfolgt nach der CDD-Klassifikation.",kw:["Sonograph|Ultraschall","CT","Abszess","Perforation","Klassifikation|CDD|Stadium"]},
  {q:"Wie behandeln Sie, und was ändert die Penicillinallergie?",a:"Eine unkomplizierte Divertikulitis ohne Risikofaktoren kann ambulant ohne Antibiotikum behandelt werden. Bei Fieber, Entzündungszeichen oder Risikofaktoren gebe ich ein Antibiotikum; wegen der Penicillinallergie mit Urtikaria verzichte ich auf Ampicillin/Sulbactam und wähle zum Beispiel Ciprofloxacin plus Metronidazol. Dazu Analgesie und flüssige bis ballaststoffarme Kost.",kw:["unkompliziert|ohne Antibiotikum","Antibio","Ciprofloxacin|Metronidazol|Cephalosporin","Penicillin|Allergie","Kost|Ernährung|flüssig"]},
  {q:"Wann ist eine Operation indiziert, und welche Nachsorge empfehlen Sie?",a:"Notfallmäßig bei freier Perforation mit Peritonitis; bei großen Abszessen zunächst Drainage. Elektiv bei rezidivierenden komplizierten Verläufen. Nach Abheilung wird nach sechs bis acht Wochen eine Koloskopie zum Ausschluss eines Karzinoms empfohlen.",kw:["Perforation|Peritonitis","Abszess.{0,20}Drainage|Drainage","rezidiv|elektiv","Koloskopie","Karzinom"]}],
 traps:"Read the allergy line before naming an antibiotic – Ampicillin is a trap. 'Divertikulose' (pouches) and 'Divertikulitis' (inflammation) are not the same; explain both in plain words. Mention the follow-up colonoscopy because a carcinoma can look identical in the CT.",
 terms:["Divertikulitis","Divertikulose","Peritonitis","Perforation","Koloskopie"],
 lay:{open:"Ich habe seit zwei Tagen Schmerzen links unten im Bauch, und seit gestern Fieber.",pmh:"Bei einer Darmspiegelung vor ein paar Jahren hat man Ausstülpungen am Darm gefunden. Außerdem habe ich hohen Blutdruck und wiege zu viel.",ops:"Nein, operiert worden bin ich noch nie.",meds:"Zwei Blutdrucktabletten am Morgen, Bisoprolol und eine Wassertablette.",all:"Ja, gegen Penicillin. Davon habe ich einmal überall Quaddeln bekommen.",
  fam:"Meine Mutter hatte auch eine Entzündung an diesen Ausstülpungen.",nox:"Ich rauche nicht. Alkohol trinke ich selten.",drugs:"Nein.",soc:"Ich bin Bibliothekarin, ich sitze viel. Ich bin verheiratet. Gemüse esse ich ehrlich gesagt wenig.",
  char:"Es ist ein dumpfer, dauernder Schmerz.",rad:"Nein, er bleibt links unten.",mod:"Bei Bewegung und wenn ich drücke, wird es schlimmer.",prev:"Vor zwei Jahren hatte ich so etwas Ähnliches, aber schwächer. Das ist von allein weggegangen.",self:"Ich habe eine Wärmflasche genommen und eine Paracetamol.",
  vacc:"Ja.",reise:"Nein.",veg:{appetit:"Ich habe wenig Appetit, mir ist ein bisschen übel.",gewicht:"Unverändert.",stuhl:"Seit drei Tagen hatte ich keinen Stuhlgang. Blut habe ich keins gesehen.",wasser:"Normal, es brennt nicht.",schlaf:"Schlecht wegen der Schmerzen.",fieber:"Heute Morgen 38,4."},
  gyn:"Die Wechseljahre sind seit zehn Jahren vorbei. Blutungen habe ich keine."},
 brief:"Frau Hartmann ist eine 63-jährige Patientin, die sich mit seit zwei Tagen bestehenden, zunehmenden Schmerzen im linken Unterbauch vorstellte. Sie berichtete, die Schmerzen seien dumpf und dauerhaft (6/10) und verstärkten sich bei Bewegung. Seit dem Vortag habe sie Fieber, am Morgen 38,4 °C. Seit drei Tagen bestehe eine Obstipation; Blutbeimengungen wurden verneint. Eine ähnliche, mildere Episode habe es vor zwei Jahren gegeben.\nAn Vorerkrankungen bestehen eine Sigmadivertikulose, eine Adipositas und eine arterielle Hypertonie. Voroperationen wurden verneint. Medikation: Bisoprolol 5 mg 1-0-0, Hydrochlorothiazid 12,5 mg 1-0-0. Es besteht eine Penicillinallergie (Urtikaria). Nikotinkonsum wurde verneint. Die Mutter habe eine Divertikulitis gehabt. Die Patientin ist Bibliothekarin und verheiratet.\nDie Anamnese spricht für eine akute Sigmadivertikulitis. Differenzialdiagnostisch kommen ein Kolonkarzinom, eine ischämische Kolitis und ein Harnwegsinfekt in Betracht. Wir empfehlen: Blutbild, CRP, Urinstatus, Sonographie und CT des Abdomens, eine Antibiose unter Beachtung der Penicillinallergie, flüssige Kost und eine Koloskopie sechs bis acht Wochen nach Abheilung."},

{id:"fy10",age:56,sex:"m",name:"Herr Seidel",vn:"Bernd",geb:"19.02.1970",cm:178,kg:88,ha:"Herr Doktor Kraus in Sandhausen",sys:"gi",job:"Lagerist",scale:4,
 cc:"seit Monaten Vorwölbung in der rechten Leiste beim Husten und Heben, seit heute schmerzhaft",
 hpi:"Seit ein paar Monaten habe ich rechts in der Leiste so eine Beule, die kommt, wenn ich huste oder etwas Schweres hebe. Im Liegen geht sie normalerweise wieder weg, ich kann sie auch selbst zurückdrücken. Heute bei der Arbeit hat es gezogen, und jetzt tut es mehr weh als sonst. Zurückdrücken kann ich sie aber noch. Übel ist mir nicht, und Stuhlgang hatte ich heute Morgen.",
 pmh:"COPD GOLD 1 (Raucherhusten), arterielle Hypertonie",meds:"Ramipril 5 mg 1-0-0, Salbutamol bei Bedarf",all:"keine bekannt",soc:"Lagerist (schweres Heben), verheiratet; raucht 20 Zigaretten/Tag; Alkohol am Wochenende",fam:"Vater Leistenbruch-OP",
 vit:"RR 144/86 mmHg · HF 80/min · AF 16/min · SpO₂ 96 % · Temp. 36,7 °C",
 dx:"Reponible Leistenhernie rechts, symptomatisch; Ausschluss einer Inkarzeration; DD: Femoralhernie, Lymphadenopathie, Hydrozele, Varikozele, Hodentorsion, Leistenzerrung",
 plan:"Körperliche Untersuchung im Stehen und Liegen (Reponierbarkeit, Hodenbefund), Sonographie der Leiste; bei Reponierbarkeit elektive Operation (z. B. TAPP/TEP oder Lichtenstein) planen; Aufklärung über Inkarzerationszeichen; bei Irreponibilität mit Schmerzen, Rötung oder Ileuszeichen sofortige Operation",
 patientQs:["Muss das operiert werden, oder geht das mit einem Bruchband?","Wie lange kann ich danach nicht arbeiten?","Was mache ich, wenn die Beule nicht mehr zurückgeht?"],
 oa:[{q:"Woran erkennen Sie eine Inkarzeration, und was tun Sie dann?",a:"Die Hernie lässt sich nicht mehr reponieren, ist prall, druckschmerzhaft und eventuell gerötet; hinzu können Übelkeit, Erbrechen und Ileuszeichen kommen. Dann ist eine notfallmäßige Operation indiziert, weil der eingeklemmte Darm absterben kann.",kw:["nicht reponibel|irreponibel|nicht.{0,20}zurück","Schmerz|prall|Rötung","Ileus|Erbrechen","Notfall|sofort|dringlich","Darm.{0,30}(Nekrose|absterben|Durchblutung)|Strangulation"]},
  {q:"Welche Operationsverfahren kennen Sie?",a:"Offene Verfahren wie die Operation nach Lichtenstein mit Netz oder nach Shouldice ohne Netz und die minimalinvasiven Netzverfahren TAPP und TEP. Beim Erwachsenen wird in der Regel ein Netz eingesetzt.",kw:["Lichtenstein","Shouldice","TAPP","TEP","Netz"]},
  {q:"Welche Faktoren begünstigen bei diesem Patienten Hernien und Rezidive?",a:"Chronischer Husten bei COPD und Rauchen, schweres Heben im Beruf, Übergewicht und eine familiäre Bindegewebsschwäche. Nach der Operation sind Rauchstopp und eine Behandlung des Hustens wichtig.",kw:["Husten|COPD","Rauchen","Heben|Beruf","Übergewicht|Adipositas","Bindegewebe|familiär"]}],
 traps:"Always examine the testicle side too and ask about bowel movements and vomiting – incarceration is the red flag. Explain 'eingeklemmt' in lay words and give him a clear rule when to come back immediately. Occupational angle: heavy lifting, sick note duration.",
 terms:["Leistenhernie","Inkarzeration","Reposition","Hernioplastik","Ileus"],
 lay:{open:"Ich habe seit Monaten eine Beule rechts in der Leiste, und seit heute tut sie mehr weh.",pmh:"Ich habe einen Raucherhusten und hohen Blutdruck.",ops:"Nein, operiert worden bin ich noch nie.",meds:"Eine Blutdrucktablette am Morgen und ein Spray, wenn ich schlecht Luft bekomme.",all:"Nein, keine.",
  fam:"Mein Vater wurde auch am Leistenbruch operiert.",nox:"Ich rauche eine Schachtel am Tag. Am Wochenende trinke ich Bier.",drugs:"Nein.",soc:"Ich bin Lagerist, ich muss den ganzen Tag schwere Kisten heben. Ich bin verheiratet.",
  char:"Es ist ein Ziehen und Drücken in der Leiste.",rad:"Es zieht ein bisschen in den Hoden.",mod:"Beim Husten, Pressen und Heben kommt die Beule raus und tut weh. Im Liegen geht sie weg.",prev:"Die Beule habe ich seit Monaten, aber so weh getan hat sie noch nie.",self:"Ich habe sie zurückgedrückt und mich hingelegt.",
  vacc:"Tetanus habe ich vom Betriebsarzt.",reise:"Nein.",veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Heute Morgen hatte ich ganz normal Stuhlgang.",wasser:"Normal.",schlaf:"Gut.",fieber:"Nein."}},
 brief:"Herr Seidel ist ein 56-jähriger Patient, der sich mit einer seit Monaten bestehenden Vorwölbung in der rechten Leiste vorstellte. Er berichtete, die Schwellung trete beim Husten und Heben auf und lasse sich im Liegen selbst reponieren. Seit einer Belastung bei der Arbeit am Aufnahmetag bestünden verstärkte ziehende Schmerzen mit Ausstrahlung in den Hoden. Die Hernie sei weiterhin reponibel. Übelkeit, Erbrechen und Stuhlverhalt wurden verneint.\nAn Vorerkrankungen bestehen eine COPD und eine arterielle Hypertonie. Voroperationen wurden verneint. Medikation: Ramipril 5 mg 1-0-0, Salbutamol bei Bedarf. Allergien sind nicht bekannt. Der Patient rauche 20 Zigaretten pro Tag und trinke am Wochenende Alkohol. Der Vater sei an einer Leistenhernie operiert worden. Der Patient ist Lagerist mit schwerer körperlicher Tätigkeit und verheiratet.\nDie Anamnese spricht für eine symptomatische, reponible Leistenhernie rechts ohne Hinweis auf eine Inkarzeration. Differenzialdiagnostisch kommen eine Femoralhernie, eine Hydrozele und eine Lymphadenopathie in Betracht. Wir empfehlen: Untersuchung im Stehen und Liegen, eine Sonographie der Leiste, die Planung einer elektiven Hernioplastik, den Rauchstopp und die Aufklärung über Inkarzerationszeichen."},

{id:"fy11",age:41,sex:"w",name:"Frau Engel",vn:"Nadine",geb:"12.12.1984",cm:170,kg:76,ha:"Frau Doktor Ritter in Schwetzingen",sys:"kardio",job:"Vertriebsmitarbeiterin",scale:5,
 cc:"seit drei Tagen geschwollene, schmerzhafte linke Wade nach Langstreckenflug",
 hpi:"Vor fünf Tagen bin ich aus Singapur zurückgeflogen, über zwölf Stunden. Seit drei Tagen ist meine linke Wade dick und tut weh, vor allem beim Gehen. Das Bein fühlt sich warm und schwer an. Luftnot oder Brustschmerzen habe ich nicht. Im Flieger habe ich fast die ganze Zeit geschlafen und wenig getrunken.",
 pmh:"Varikosis; sonst gesund",meds:"orales Kontrazeptivum (Ethinylestradiol/Desogestrel)",all:"keine bekannt",soc:"Vertriebsmitarbeiterin mit vielen Flugreisen, ledig; raucht 10 Zigaretten/Tag; Alkohol gelegentlich",fam:"Mutter Lungenembolie mit 50",
 vit:"RR 128/78 mmHg · HF 84/min · AF 14/min · SpO₂ 98 % · Temp. 37,2 °C · Wadenumfang links +3 cm",
 dx:"V. a. tiefe Beinvenenthrombose links (Wells-Score hoch); DD: rupturierte Baker-Zyste, Muskelfaserriss, Erysipel, oberflächliche Thrombophlebitis, Lymphödem",
 plan:"Wells-Score; bei hoher Wahrscheinlichkeit direkt Kompressionssonographie, bei niedriger D-Dimer; therapeutische Antikoagulation (z. B. Apixaban oder Rivaroxaban) bereits bei hohem Verdacht; Pille absetzen und alternative Verhütung beraten; Kompression bei Beschwerden; Thrombophilie-Abklärung erwägen (Familienanamnese)",
 patientQs:["Ist das gefährlich? Kann das Gerinnsel in die Lunge wandern?","Muss ich die Pille absetzen? Wie verhüte ich dann?","Darf ich nächste Woche wieder fliegen?"],
 oa:[{q:"Wie gehen Sie diagnostisch vor?",a:"Ich bestimme die klinische Wahrscheinlichkeit mit dem Wells-Score. Bei hoher Wahrscheinlichkeit folgt direkt die Kompressionssonographie, bei niedriger Wahrscheinlichkeit zunächst der D-Dimer-Test, der eine Thrombose bei negativem Ergebnis ausschließt.",kw:["Wells","Kompressionssonograph|Ultraschall","D-Dimer","niedrig.{0,40}D-Dimer|ausschließen|Ausschluss"]},
  {q:"Wie behandeln Sie, und wie lange?",a:"Therapeutische Antikoagulation, heute meist mit einem direkten oralen Antikoagulans wie Apixaban oder Rivaroxaban, bei hohem Verdacht schon vor der Bestätigung. Bei einem vorübergehenden Risikofaktor wie dem Flug und der Pille in der Regel drei Monate; die Pille wird abgesetzt.",kw:["Antikoagul","Apixaban|Rivaroxaban|DOAK|Heparin","drei Monate|3 Monate","Pille absetzen|Kontrazeptivum absetzen|absetzen","vor.{0,20}Bestätigung|sofort"]},
  {q:"Welche Risikofaktoren hat diese Patientin, und was raten Sie ihr für künftige Flüge?",a:"Langstreckenflug mit Immobilität und wenig Flüssigkeit, östrogenhaltige Pille, Rauchen, Varikosis und eine positive Familienanamnese. Für künftige Flüge: viel trinken, regelmäßig aufstehen und die Waden bewegen, Kompressionsstrümpfe, keine Schlafmittel; eine medikamentöse Prophylaxe nach Rücksprache.",kw:["Flug|Immobil","Pille|Östrogen","Rauchen","Familie|Mutter","Kompressionsstrümpfe|Kompression","trinken|aufstehen|bewegen"]}],
 traps:"Ask for symptoms of a pulmonary embolism before you talk about the leg. The pill plus smoking plus a mother with an embolism is the examiners' checklist. Lay terms: 'Blutgerinnsel in der Beinvene', 'Blutverdünner', 'Ultraschall der Beinvenen'. Contraception advice is part of the answer – do not leave her without one.",
 terms:["Tiefe Beinvenenthrombose","Lungenembolie","Antikoagulation","Kompressionssonographie","Thrombophilie"],
 lay:{open:"Meine linke Wade ist seit drei Tagen dick und tut weh. Ich bin vor fünf Tagen aus Singapur zurückgeflogen.",pmh:"Ich habe Krampfadern, sonst bin ich gesund.",ops:"Nein, noch nie.",meds:"Ich nehme die Pille.",all:"Nein, keine.",fam:"Meine Mutter hatte mit fünfzig ein Blutgerinnsel in der Lunge.",
  nox:"Ich rauche zehn Zigaretten am Tag. Alkohol trinke ich gelegentlich.",drugs:"Nein.",soc:"Ich bin im Vertrieb und fliege oft beruflich. Ich lebe allein.",
  char:"Es ist ein Spannen und Ziehen in der Wade, wie ein Muskelkater.",rad:"Es zieht bis in die Kniekehle.",mod:"Beim Gehen und wenn ich den Fuß anziehe, tut es mehr weh. Hochlegen hilft ein bisschen.",prev:"Nein, so etwas hatte ich noch nie.",self:"Ich habe eine Salbe draufgemacht und eine Ibuprofen genommen.",
  vacc:"Für die Reisen bin ich gut geimpft.",reise:"Ich war zwei Wochen beruflich in Singapur und bin vor fünf Tagen zurückgeflogen, zwölf Stunden ohne Pause.",
  veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Wegen dem Jetlag noch etwas schlecht.",fieber:"Nein, nur das Bein ist warm."},gyn:"Meine Regel ist regelmäßig, ich nehme die Pille. Schwanger bin ich nicht."},
 brief:"Frau Engel ist eine 41-jährige Patientin, die sich mit seit drei Tagen bestehender schmerzhafter Schwellung der linken Wade vorstellte. Sie berichtete, sie sei fünf Tage zuvor von einem über zwölfstündigen Flug aus Singapur zurückgekehrt; während des Fluges habe sie überwiegend geschlafen und wenig getrunken. Das Bein sei warm und schwer, die Schmerzen verstärkten sich beim Gehen. Dyspnoe, Thoraxschmerzen und Hämoptysen wurden verneint.\nAn Vorerkrankungen ist eine Varikosis bekannt. Voroperationen wurden verneint. Medikation: orales Kontrazeptivum. Allergien sind nicht bekannt. Die Patientin rauche zehn Zigaretten pro Tag. Die Mutter habe mit 50 Jahren eine Lungenembolie erlitten. Die Patientin ist im Außendienst tätig und lebt allein.\nDie Anamnese spricht für eine tiefe Beinvenenthrombose links. Differenzialdiagnostisch kommen eine rupturierte Baker-Zyste, ein Muskelfaserriss und ein Erysipel in Betracht. Wir empfehlen: Wells-Score, Kompressionssonographie der Beinvenen, eine therapeutische Antikoagulation, das Absetzen des Kontrazeptivums mit Beratung zu einer östrogenfreien Verhütung und gegebenenfalls eine Thrombophilie-Abklärung."},

{id:"fy12",age:68,sex:"m",name:"Herr Pfeiffer",vn:"Manfred",geb:"08.08.1958",cm:174,kg:80,ha:"Herr Doktor Lindemann in Walldorf",sys:"kardio",job:"Rentner, früher Schreiner",scale:6,
 cc:"seit einem Jahr Wadenschmerzen links nach etwa 100 Metern Gehstrecke, Besserung nach kurzem Stehenbleiben",
 hpi:"Seit ungefähr einem Jahr bekomme ich beim Gehen Krämpfe in der linken Wade. Am Anfang nach einem halben Kilometer, jetzt schon nach hundert Metern. Wenn ich stehen bleibe und mir ein Schaufenster anschaue, ist es nach ein, zwei Minuten weg. Der linke Fuß ist oft kalt. In Ruhe und nachts tut es nicht weh. Am Zeh habe ich keine Wunde.",
 pmh:"Diabetes mellitus Typ 2, arterielle Hypertonie, Hypercholesterinämie",meds:"Metformin 1000 mg 1-0-1, Ramipril 5 mg 1-0-0",all:"keine bekannt",soc:"Rentner, früher Schreiner, verheiratet; raucht seit 50 Jahren 20 Zigaretten/Tag; Alkohol 1 Glas Wein täglich",fam:"Bruder Herzinfarkt mit 60",
 vit:"RR 156/90 mmHg · HF 76/min · AF 14/min · SpO₂ 97 % · Temp. 36,5 °C · Fußpulse links nicht tastbar",
 dx:"Periphere arterielle Verschlusskrankheit (pAVK) links, Stadium II b nach Fontaine; DD: spinale Claudicatio bei Spinalkanalstenose, Polyneuropathie, Baker-Zyste, venöse Claudicatio",
 plan:"Pulsstatus, Knöchel-Arm-Index, Duplexsonographie der Beinarterien; Rauchstopp, strukturiertes Gehtraining, Thrombozytenaggregationshemmer (ASS oder Clopidogrel), hochdosiertes Statin, Blutdruck- und Blutzuckereinstellung; Fußpflege; bei Therapieversagen oder kurzer Gehstrecke Angiographie mit Revaskularisation",
 patientQs:["Muss mir das Bein irgendwann abgenommen werden?","Hilft es wirklich, wenn ich mit dem Rauchen aufhöre? Nach fünfzig Jahren?","Was ist das für ein Gehtraining?"],
 oa:[{q:"Wie teilen Sie die pAVK ein, und in welchem Stadium ist der Patient?",a:"Nach Fontaine: Stadium I beschwerdefrei, II Claudicatio intermittens (II a Gehstrecke über 200 Meter, II b unter 200 Meter), III Ruheschmerz, IV Nekrose oder Gangrän. Der Patient ist mit 100 Metern im Stadium II b.",kw:["Fontaine","Claudicatio","200","II b|IIb|2b","Ruheschmerz|Nekrose"]},
  {q:"Welche Diagnostik veranlassen Sie?",a:"Pulsstatus, den Knöchel-Arm-Index – ein Wert unter 0,9 spricht für eine pAVK, bei Diabetikern kann er durch Mediasklerose falsch hoch sein –, die farbkodierte Duplexsonographie und vor einer Revaskularisation eine Angiographie, CT- oder MR-Angiographie.",kw:["Knöchel-Arm|ABI","0,9","Mediasklerose|falsch hoch","Duplex","Angiograph"]},
  {q:"Welche Therapie empfehlen Sie?",a:"Konsequenter Rauchstopp, strukturiertes Gehtraining, ein Thrombozytenaggregationshemmer und ein hochdosiertes Statin, gute Einstellung von Blutdruck und Blutzucker sowie Fußpflege. Bei starker Einschränkung oder Therapieversagen eine interventionelle oder operative Revaskularisation.",kw:["Rauchstopp|Nikotin","Gehtraining","ASS|Clopidogrel|Thrombozyten","Statin","Revaskularisation|Stent|Bypass|PTA"]}],
 traps:"Ask for the walking distance in metres and what makes it better: standing still (vascular) versus sitting or bending forward (spinal). Look at the feet and ask about wounds – diabetic foot. Lay terms: 'Schaufensterkrankheit', 'Durchblutungsstörung der Beine', 'verengte Schlagadern'.",
 terms:["Periphere arterielle Verschlusskrankheit","Claudicatio intermittens","Knöchel-Arm-Index","Revaskularisation","Arteriosklerose"],
 lay:{open:"Ich bekomme seit einem Jahr beim Gehen Krämpfe in der linken Wade, inzwischen schon nach hundert Metern.",pmh:"Ich habe Zucker, hohen Blutdruck und zu viel Cholesterin.",ops:"Nein, noch nie.",meds:"Metformin morgens und abends und eine Blutdrucktablette. Für das Cholesterin nehme ich nichts, das wollte ich nicht.",all:"Nein, keine.",
  fam:"Mein Bruder hatte mit sechzig einen Herzinfarkt.",nox:"Ich rauche seit fünfzig Jahren, eine Schachtel am Tag. Abends trinke ich ein Glas Wein.",drugs:"Nein.",soc:"Ich war Schreiner, jetzt bin ich Rentner. Ich lebe mit meiner Frau. Am liebsten gehe ich mit dem Hund spazieren, aber das geht kaum noch.",
  char:"Es ist ein Krampf, wie wenn der Muskel sauer wird.",rad:"Nein, es bleibt in der Wade.",mod:"Wenn ich stehen bleibe, ist es nach ein, zwei Minuten weg. Hinsetzen muss ich mich dafür nicht. Bergauf kommt es schneller.",prev:"Es fing vor einem Jahr an und ist langsam schlimmer geworden.",self:"Ich habe Magnesium genommen, weil ich dachte, es sind Krämpfe.",
  vacc:"Grippe ja.",reise:"Nein.",veg:{appetit:"Gut.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Nachts einmal.",schlaf:"Ich schlafe gut, nachts tut das Bein nicht weh.",fieber:"Nein."}},
 brief:"Herr Pfeiffer ist ein 68-jähriger Patient, der sich mit seit etwa einem Jahr bestehenden belastungsabhängigen Schmerzen in der linken Wade vorstellte. Er berichtete, die schmerzfreie Gehstrecke habe von etwa 500 auf 100 Meter abgenommen; nach kurzem Stehenbleiben bildeten sich die Beschwerden innerhalb von ein bis zwei Minuten zurück. Der linke Fuß sei häufig kalt. Ruheschmerzen und Wunden wurden verneint.\nAn Vorerkrankungen bestehen ein Diabetes mellitus Typ 2, eine arterielle Hypertonie und eine Hypercholesterinämie. Voroperationen wurden verneint. Medikation: Metformin 1000 mg 1-0-1, Ramipril 5 mg 1-0-0. Allergien sind nicht bekannt. Der Patient rauche seit 50 Jahren 20 Zigaretten pro Tag (50 Packungsjahre) und trinke täglich ein Glas Wein. Der Bruder habe mit 60 Jahren einen Myokardinfarkt erlitten. Der Patient ist Rentner und verheiratet.\nDie Anamnese spricht für eine periphere arterielle Verschlusskrankheit links im Stadium II b nach Fontaine. Differenzialdiagnostisch kommen eine spinale Claudicatio und eine Polyneuropathie in Betracht. Wir empfehlen: Pulsstatus, Knöchel-Arm-Index, Duplexsonographie der Beinarterien, Rauchstopp, strukturiertes Gehtraining, einen Thrombozytenaggregationshemmer und ein Statin."}
];

// ===== P3 · the classic non-acute FSP pool, cases fy13–fy24 (appended to P3_FSP_NEW) =====
P3_FSP_NEW.push(
{id:"fy13",age:61,sex:"m",name:"Herr Busch",vn:"Klaus",geb:"02.03.1965",cm:176,kg:92,ha:"Frau Doktor Beck in Nußloch",sys:"kardio",job:"Busfahrer",scale:5,
 cc:"seit sechs Wochen Druckgefühl hinter dem Brustbein beim Treppensteigen, verschwindet in Ruhe",
 hpi:"Seit ungefähr sechs Wochen bekomme ich beim Treppensteigen einen Druck auf der Brust, wie ein Band. Nach dem zweiten Stockwerk muss ich stehen bleiben, dann ist es nach zwei, drei Minuten weg. Bei Kälte und nach dem Essen kommt es schneller. In Ruhe hatte ich es noch nie. Heute kam es schon beim Weg vom Parkplatz, deshalb hat meine Frau mich hergeschickt.",
 pmh:"arterielle Hypertonie, Hypercholesterinämie, Adipositas",meds:"Amlodipin 5 mg 1-0-0",all:"keine bekannt",soc:"Busfahrer, verheiratet, zwei erwachsene Kinder; raucht 25 Zigaretten/Tag seit 40 Jahren; Alkohol 2 Bier abends; Bewegungsmangel",fam:"Vater Herzinfarkt mit 55, Mutter Schlaganfall",
 vit:"RR 158/94 mmHg · HF 78/min · AF 14/min · SpO₂ 97 % · Temp. 36,6 °C · EKG in Ruhe ohne Ischämiezeichen · hs-Troponin negativ",
 dx:"V. a. koronare Herzkrankheit mit stabiler Angina pectoris (CCS II), heute Belastungsgrenze gesunken – instabile Angina ausschließen; DD: Refluxkrankheit, muskuloskelettale Schmerzen, Aortenstenose, Lungenembolie",
 plan:"Ruhe-EKG, hs-Troponin 0/1 h zum Ausschluss eines akuten Koronarsyndroms; Echokardiographie; nichtinvasive Ischämiediagnostik (Stress-Echo, Stress-MRT oder Koronar-CT) bzw. bei hoher Wahrscheinlichkeit Herzkatheter; ASS 100 mg, hochdosiertes Statin, Betablocker, Nitrospray bei Bedarf; Rauchstopp, Blutdruckeinstellung; Fahreignung als Berufskraftfahrer besprechen",
 patientQs:["Ist das ein Herzinfarkt, der gleich kommt?","Was ist ein Herzkatheter? Muss ich da operiert werden?","Darf ich weiter Bus fahren?"],
 oa:[{q:"Wie unterscheiden Sie stabile und instabile Angina pectoris?",a:"Die stabile Angina tritt reproduzierbar bei Belastung auf und verschwindet in Ruhe oder nach Nitro. Instabil ist sie bei Erstauftreten, zunehmender Häufigkeit oder Dauer, abnehmender Belastungsschwelle oder Beschwerden in Ruhe; sie gehört zum akuten Koronarsyndrom und erfordert Troponin und Monitoring.",kw:["Belastung","Ruhe","Nitro","Crescendo|zunehmend|abnehmende Belastung","Koronarsyndrom","Troponin"]},
  {q:"Wie erklären Sie dem Patienten eine Herzkatheteruntersuchung?",a:"Wir schieben über die Schlagader am Handgelenk einen dünnen Schlauch bis zum Herzen und machen die Herzkranzgefäße mit Kontrastmittel sichtbar. Ist ein Gefäß verengt, können wir es sofort aufdehnen und mit einem Röhrchen, einem Stent, offen halten. Sie sind wach, die Stelle wird örtlich betäubt.",kw:["Handgelenk|Leiste|Schlagader","Schlauch|Katheter","Kontrastmittel","Stent|Röhrchen|aufdehnen","betäubt|wach"]},
  {q:"Welche Sekundärprävention leiten Sie ein?",a:"ASS 100 mg, ein hochdosiertes Statin mit LDL-Ziel unter 55 mg/dl, Betablocker oder Calciumantagonist gegen die Angina, Nitrospray bei Bedarf, Blutdruckeinstellung, konsequenter Rauchstopp, Gewichtsreduktion und Bewegung.",kw:["ASS","Statin","LDL|55","Betablocker","Nitro","Rauchstopp|Nikotin"]}],
 traps:"Today's pain came at a lower effort: say 'instabil, bis das Troponin negativ ist'. A bus driver: driving rules matter, do not improvise. Lay terms: 'Engegefühl', 'verengte Herzkranzgefäße', 'Herzkatheter'.",
 terms:["Angina pectoris","Koronare Herzkrankheit","Herzkatheteruntersuchung","Stent","Sekundärprävention"],
 lay:{open:"Ich bekomme seit sechs Wochen beim Treppensteigen einen Druck auf der Brust. Heute kam er schon auf dem Weg vom Parkplatz.",pmh:"Ich habe hohen Blutdruck und zu viel Cholesterin. Und ich wiege zu viel.",ops:"Nein, operiert worden bin ich nie.",meds:"Eine Blutdrucktablette am Morgen. Für das Cholesterin nehme ich nichts.",all:"Nein, keine.",
  fam:"Mein Vater hatte mit fünfundfünfzig einen Herzinfarkt. Meine Mutter hatte einen Schlaganfall.",nox:"Ich rauche seit vierzig Jahren, ungefähr fünfundzwanzig Zigaretten am Tag. Abends trinke ich zwei Bier.",drugs:"Nein.",soc:"Ich bin Busfahrer. Ich bin verheiratet, die Kinder sind erwachsen. Sport mache ich ehrlich gesagt keinen.",
  char:"Es ist ein Druck, wie ein Band um die Brust.",rad:"Manchmal zieht es in den linken Arm, nicht in den Kiefer.",mod:"Wenn ich stehen bleibe, ist es nach zwei, drei Minuten weg. Bei Kälte und nach dem Essen kommt es schneller.",prev:"Seit sechs Wochen immer wieder. Aber heute kam es zum ersten Mal schon nach wenigen Schritten.",self:"Nein, ich habe nichts genommen.",
  vacc:"Ja, das Übliche.",reise:"Nein.",veg:{appetit:"Gut.",gewicht:"Eher mehr geworden.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Ich schlafe flach mit einem Kissen, nachts habe ich keine Beschwerden.",fieber:"Nein."}},
 brief:"Herr Busch ist ein 61-jähriger Patient, der sich mit seit sechs Wochen bestehendem retrosternalem Druckgefühl bei Belastung vorstellte. Er berichtete, die Beschwerden träten beim Treppensteigen nach dem zweiten Stockwerk auf, strahlten gelegentlich in den linken Arm aus und bildeten sich in Ruhe innerhalb weniger Minuten zurück. Bei Kälte und postprandial komme es früher dazu. Am Aufnahmetag sei der Druck erstmals bereits bei geringer Belastung aufgetreten. Ruhebeschwerden wurden verneint.\nAn Vorerkrankungen bestehen eine arterielle Hypertonie, eine Hypercholesterinämie und eine Adipositas. Voroperationen wurden verneint. Medikation: Amlodipin 5 mg 1-0-0. Allergien sind nicht bekannt. Der Patient rauche seit 40 Jahren etwa 25 Zigaretten pro Tag (50 Packungsjahre) und trinke abends zwei Bier. Der Vater habe mit 55 Jahren einen Myokardinfarkt erlitten. Der Patient ist Busfahrer und verheiratet.\nDie Anamnese spricht für eine koronare Herzkrankheit mit Angina pectoris; wegen der abnehmenden Belastungsschwelle ist eine instabile Angina auszuschließen. Differenzialdiagnostisch kommen eine Refluxkrankheit und eine Aortenstenose in Betracht. Wir empfehlen: EKG und hs-Troponin im Verlauf, eine Echokardiographie, eine Ischämiediagnostik bzw. Koronarangiographie, ASS, ein Statin, einen Betablocker, Nitrospray bei Bedarf und den Rauchstopp."},

{id:"fy14",age:72,sex:"w",name:"Frau Vogel",vn:"Renate",geb:"24.07.1954",cm:162,kg:70,ha:"Herr Doktor Busch in Bammental",sys:"kardio",job:"Rentnerin, früher Apothekenhelferin",scale:1,
 cc:"seit zwei Wochen Herzstolpern und Leistungsknick, heute Herzrasen",
 hpi:"Seit ungefähr zwei Wochen stolpert mein Herz, mal schnell, mal langsam, ganz unregelmäßig. Ich bin nicht mehr so belastbar, nach dem Einkaufen muss ich mich hinsetzen. Heute früh hat das Herz richtig gerast, deshalb bin ich hier. Schmerzen in der Brust habe ich nicht. Lähmungen oder Sprachstörungen hatte ich nie.",
 pmh:"arterielle Hypertonie, Diabetes mellitus Typ 2 (diätetisch), Hypothyreose; Z. n. Cholezystektomie",meds:"Candesartan 8 mg 1-0-0, L-Thyroxin 75 µg 1-0-0",all:"keine bekannt",soc:"verwitwet, lebt allein, selbstständig; Nichtraucherin; Alkohol selten",fam:"Bruder Schlaganfall",
 vit:"RR 146/88 mmHg · HF 128/min, absolut arrhythmisch · AF 16/min · SpO₂ 96 % · Temp. 36,6 °C · EKG: tachykardes Vorhofflimmern",
 dx:"Erstdiagnose tachykardes Vorhofflimmern, Beginn unklar (> 48 h); CHA₂DS₂-VASc 5; DD: Vorhofflattern, Hyperthyreose (Überdosierung L-Thyroxin), Herzinsuffizienz, Elektrolytstörung",
 plan:"12-Kanal-EKG, Labor (TSH, Elektrolyte, Kreatinin, Blutbild, Troponin, NT-proBNP), Echokardiographie; Frequenzkontrolle mit Betablocker (Ziel < 110/min in Ruhe); Antikoagulation mit DOAK (z. B. Apixaban) nach CHA₂DS₂-VASc und HAS-BLED; keine Kardioversion ohne TEE oder dreiwöchige Antikoagulation bei Beginn > 48 h; kardiologische Anbindung",
 patientQs:["Bekomme ich jetzt einen Schlaganfall wie mein Bruder?","Ich habe Angst vor Blutverdünnern – blute ich dann nicht bei jedem Schnitt?","Kann man das Stolpern nicht einfach wegmachen?"],
 oa:[{q:"Wie entscheiden Sie über die Antikoagulation?",a:"Mit dem CHA₂DS₂-VASc-Score: Alter über 65 und weibliches Geschlecht, Hypertonie und Diabetes ergeben hier 5 Punkte, damit ist eine orale Antikoagulation klar indiziert, bevorzugt mit einem DOAK wie Apixaban. Das Blutungsrisiko schätze ich mit HAS-BLED ab und behandle beeinflussbare Faktoren.",kw:["CHA2DS2|CHA₂DS₂","Alter|weiblich|Hypertonie|Diabetes","DOAK|Apixaban|Rivaroxaban|Edoxaban","HAS-BLED|Blutungsrisiko","indiziert"]},
  {q:"Frequenz- oder Rhythmuskontrolle – und was müssen Sie vor einer Kardioversion beachten?",a:"Akut zuerst Frequenzkontrolle, zum Beispiel mit einem Betablocker. Eine Rhythmuskontrolle ist bei symptomatischen Patienten sinnvoll. Besteht das Vorhofflimmern länger als 48 Stunden oder ist der Beginn unklar, darf nur nach Ausschluss von Vorhofthromben durch eine TEE oder nach drei Wochen Antikoagulation kardiovertiert werden.",kw:["Frequenzkontrolle|Betablocker","Rhythmuskontrolle|Kardioversion","48","TEE|transösophageal","drei Wochen|3 Wochen"]},
  {q:"Welche Ursachen suchen Sie bei neu aufgetretenem Vorhofflimmern?",a:"Strukturelle Herzerkrankungen wie Hypertonie, Klappenfehler, KHK und Herzinsuffizienz, eine Hyperthyreose – hier auch eine Überdosierung von L-Thyroxin –, Elektrolytstörungen, Alkohol, Infekte, Schlafapnoe und eine Lungenembolie.",kw:["Hyperthyreose|TSH|Schilddrüse","Klappe|Echokardiographie","Elektrolyt|Kalium","Alkohol","Schlafapnoe|Infekt|Lungenembolie","Hypertonie|KHK"]}],
 traps:"Ask how long the palpitations have lasted (48 hours!) and about stroke symptoms. Thyroxine in the medication list is a probe – check TSH. Explain anticoagulation honestly: the benefit outweighs the bleeding risk. Lay terms: 'Herzstolpern', 'Blutverdünner', 'Blutgerinnsel im Herzen'.",
 terms:["Vorhofflimmern","Tachyarrhythmie","Antikoagulation","Kardioversion","Thromboembolie"],
 lay:{open:"Mein Herz stolpert seit zwei Wochen, und heute früh hat es richtig gerast.",pmh:"Ich habe hohen Blutdruck, einen leichten Zucker, der mit Diät geht, und eine Schilddrüsenunterfunktion.",ops:"Man hat mir vor dreißig Jahren die Gallenblase rausgenommen.",meds:"Eine Blutdrucktablette und eine Schilddrüsentablette, beide morgens.",all:"Nein, keine.",
  fam:"Mein Bruder hatte einen Schlaganfall, er sitzt seitdem im Rollstuhl.",nox:"Ich habe nie geraucht. Alkohol trinke ich selten.",drugs:"Aber nein.",soc:"Ich war Apothekenhelferin. Mein Mann ist gestorben, ich lebe allein und mache alles selbst.",
  char:"Es ist kein Schmerz, das Herz flattert und stolpert.",mod:"Bei Anstrengung rast es mehr. In Ruhe ist es etwas besser, aber nie ganz regelmäßig.",prev:"Ab und zu hat es mal gestolpert, aber nie so lange.",self:"Nein. Ich habe mich hingelegt.",
  vacc:"Grippe, Corona und Lungenentzündung, das macht mein Hausarzt.",reise:"Nein.",veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Ich spüre das Stolpern nachts, deshalb schlafe ich schlechter. Flach liegen geht.",fieber:"Nein."},
  gyn:"Das ist lange vorbei. Ich habe zwei Kinder."},
 brief:"Frau Vogel ist eine 72-jährige Patientin, die sich mit seit etwa zwei Wochen bestehendem unregelmäßigem Herzschlag und Leistungsminderung sowie seit dem Morgen bestehendem Herzrasen vorstellte. Thoraxschmerzen, Synkopen sowie neurologische Ausfälle wurden verneint. Im EKG zeigt sich ein tachykardes Vorhofflimmern; der Beginn liegt vermutlich länger als 48 Stunden zurück.\nAn Vorerkrankungen bestehen eine arterielle Hypertonie, ein diätetisch eingestellter Diabetes mellitus Typ 2 und eine Hypothyreose. Z. n. Cholezystektomie. Medikation: Candesartan 8 mg 1-0-0, L-Thyroxin 75 µg 1-0-0. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint. Der Bruder habe einen Schlaganfall erlitten. Die Patientin ist verwitwet und lebt selbstständig allein.\nEs handelt sich um ein erstdiagnostiziertes tachykardes Vorhofflimmern mit einem CHA₂DS₂-VASc-Score von 5. Differenzialdiagnostisch sind eine Hyperthyreose und eine Herzinsuffizienz zu bedenken. Wir empfehlen: Labor mit TSH und Elektrolyten, eine Echokardiographie, eine Frequenzkontrolle mit einem Betablocker, eine orale Antikoagulation mit Apixaban und eine Kardioversion erst nach TEE oder dreiwöchiger Antikoagulation."},

{id:"fy15",age:76,sex:"m",name:"Herr Lange",vn:"Heinz",geb:"13.12.1949",cm:171,kg:84,ha:"Frau Doktor Kühn in Neckargemünd",sys:"kardio",job:"Rentner, früher Elektromeister",scale:1,
 cc:"seit Wochen zunehmende Belastungsluftnot, geschwollene Beine, nachts mehrfach Wasserlassen",
 hpi:"In den letzten Wochen bekomme ich immer schlechter Luft. Früher bin ich jeden Tag eine Stunde spazieren gegangen, jetzt schaffe ich keine zweihundert Meter. Abends sind die Knöchel dick, morgens ist es besser. Nachts brauche ich zwei Kissen und muss dreimal zum Wasserlassen raus. Seit einer Woche habe ich zwei Kilo zugenommen. Vor drei Jahren hatte ich einen Herzinfarkt.",
 pmh:"KHK, Z. n. Hinterwandinfarkt mit Stent 2023; Herzinsuffizienz mit reduzierter EF (35 %, 2025); arterielle Hypertonie; Niereninsuffizienz Stadium 3a",meds:"ASS 100 mg 1-0-0, Atorvastatin 40 mg 0-0-1, Ramipril 5 mg 1-0-0, Bisoprolol 2,5 mg 1-0-0, Torasemid 10 mg 1-0-0",all:"keine bekannt",soc:"verheiratet; Ex-Raucher seit 2023 (40 py); Alkohol selten; salzreiche Kost",fam:"Vater Herzinsuffizienz",
 vit:"RR 128/78 mmHg · HF 88/min · AF 20/min · SpO₂ 94 % · Temp. 36,5 °C · Gewicht 84 kg (vor einer Woche 82 kg)",
 dx:"Chronische Herzinsuffizienz mit reduzierter Ejektionsfraktion (HFrEF), NYHA III, mit Zeichen der Volumenüberladung; DD: Progression der KHK/Ischämie, Vorhofflimmern, Anämie, Medikamentenadhärenz, Niereninsuffizienz-Progression",
 plan:"EKG, Labor (NT-proBNP, Kreatinin, Kalium, Natrium, Blutbild, TSH), Röntgen-Thorax, Echokardiographie; Diuretikum anpassen; leitliniengerechte Therapie ausbauen (ARNI statt ACE-Hemmer, Betablocker auftitrieren, MRA, SGLT2-Hemmer); tägliche Gewichtskontrolle, Trinkmenge 1,5–2 l, Salzreduktion; Herzinsuffizienzschulung; ICD-Indikation prüfen",
 patientQs:["Ist mein Herz jetzt kaputt?","Warum soll ich mich jeden Tag wiegen?","Wie viel darf ich noch trinken?"],
 oa:[{q:"Wie teilen Sie die Herzinsuffizienz klinisch ein, und wo steht der Patient?",a:"Nach der NYHA-Klassifikation: I keine Beschwerden, II Beschwerden bei stärkerer Belastung, III bei leichter Belastung, IV in Ruhe. Mit Luftnot nach weniger als 200 Metern ist der Patient im Stadium NYHA III. Nach der Ejektionsfraktion handelt es sich um eine HFrEF.",kw:["NYHA","III|3","leichte Belastung|geringer Belastung","HFrEF|reduziert|Ejektionsfraktion"]},
  {q:"Welche medikamentöse Therapie ist bei HFrEF prognostisch wirksam?",a:"Die vier Säulen: ARNI (Sacubitril/Valsartan) oder ACE-Hemmer, ein Betablocker, ein Mineralokortikoidrezeptorantagonist wie Spironolacton und ein SGLT2-Hemmer wie Dapagliflozin oder Empagliflozin. Diuretika lindern Symptome, verbessern aber nicht die Prognose.",kw:["ARNI|Sacubitril|ACE","Betablocker","Spironolacton|Eplerenon|MRA","SGLT2|Dapagliflozin|Empagliflozin","Diuretik.{0,40}(Symptom|Prognose)"]},
  {q:"Was bringen Sie dem Patienten für zu Hause bei?",a:"Tägliches Wiegen morgens; bei einer Zunahme von mehr als einem Kilo über Nacht oder zwei Kilo in drei Tagen soll er sich melden. Trinkmenge etwa 1,5 bis 2 Liter, wenig Salz, regelmäßige Bewegung im Rahmen der Belastbarkeit, Medikamente regelmäßig einnehmen und keine NSAR.",kw:["wiegen|Gewicht","zwei Kilo|2 kg|1 kg","Trinkmenge|1,5|2 l","Salz","NSAR|Ibuprofen","Bewegung|Training"]}],
 traps:"Ask about weight, number of pillows, nocturia, salt and adherence. Examiners love 'Warum sollen Sie sich wiegen?' – answer in lay words: 'Wasser im Körper zeigt sich zuerst auf der Waage.' Lay terms: 'Herzschwäche', 'Wassertablette'.",
 terms:["Herzinsuffizienz","Orthopnoe","Nykturie","Ödem","Ejektionsfraktion"],
 lay:{open:"Ich bekomme seit Wochen immer schlechter Luft, schon nach ein paar hundert Metern, und abends sind die Knöchel dick.",pmh:"Vor drei Jahren hatte ich einen Herzinfarkt, da hat man mir einen Stent eingesetzt. Seitdem ist das Herz schwach. Außerdem habe ich hohen Blutdruck, und die Nieren arbeiten nicht mehr ganz so gut.",ops:"Nur den Stent, das ging über das Handgelenk.",
  meds:"ASS, eine Tablette fürs Cholesterin abends, eine für den Blutdruck, eine, die das Herz langsamer macht, und eine Wassertablette, alle morgens.",all:"Nein, keine.",fam:"Mein Vater hatte auch ein schwaches Herz.",nox:"Seit dem Herzinfarkt rauche ich nicht mehr. Davor vierzig Jahre lang eine Schachtel. Alkohol trinke ich selten.",drugs:"Nein.",
  soc:"Ich war Elektromeister. Ich lebe mit meiner Frau, sie kocht gern deftig und salzig, das muss ich zugeben.",mod:"Bei jeder Anstrengung wird es schlimmer, im Sitzen geht es. Im Liegen brauche ich zwei Kissen.",prev:"Ein bisschen schlapp war ich seit dem Infarkt immer, aber so schlecht war es noch nie.",self:"Ich habe an zwei Tagen eine Wassertablette mehr genommen.",
  vacc:"Grippe, Corona und Lungenentzündung, ja.",reise:"Nein.",veg:{appetit:"Normal, aber ich bin schnell satt.",gewicht:"Ich habe in einer Woche zwei Kilo zugenommen.",stuhl:"Normal.",wasser:"Nachts muss ich dreimal raus.",schlaf:"Ich brauche zwei Kissen, sonst bekomme ich keine Luft.",fieber:"Nein."}},
 brief:"Herr Lange ist ein 76-jähriger Patient, der sich mit seit Wochen zunehmender Belastungsdyspnoe vorstellte. Er berichtete, die Gehstrecke sei auf unter 200 Meter gesunken; abends bestünden Knöchelödeme, nachts benötige er zwei Kissen und müsse dreimal Wasser lassen. Innerhalb einer Woche habe er zwei Kilogramm zugenommen. Thoraxschmerzen und Synkopen wurden verneint.\nAn Vorerkrankungen bestehen eine koronare Herzkrankheit mit Z. n. Hinterwandinfarkt und Stentimplantation 2023, eine Herzinsuffizienz mit reduzierter Ejektionsfraktion (35 %), eine arterielle Hypertonie und eine Niereninsuffizienz Stadium 3a. Medikation: ASS 100 mg, Atorvastatin 40 mg, Ramipril 5 mg, Bisoprolol 2,5 mg, Torasemid 10 mg. Allergien sind nicht bekannt. Der Patient sei seit 2023 Nichtraucher (40 Packungsjahre). Der Vater habe an einer Herzinsuffizienz gelitten. Der Patient ist Rentner und verheiratet.\nEs handelt sich um eine chronische Herzinsuffizienz mit reduzierter Ejektionsfraktion im Stadium NYHA III mit Zeichen der Volumenüberladung. Differenzialdiagnostisch sind eine Ischämie, ein Vorhofflimmern und eine Anämie als Auslöser zu bedenken. Wir empfehlen: EKG, NT-proBNP, Nierenwerte und Elektrolyte, Röntgen-Thorax, Echokardiographie, eine Anpassung der Diuretikadosis, den Ausbau der leitliniengerechten Therapie sowie tägliche Gewichtskontrollen und eine Salzreduktion."},

{id:"fy16",age:27,sex:"w",name:"Frau Schuster",vn:"Julia",geb:"21.05.1999",cm:169,kg:61,ha:"Herr Doktor Graf in Weinheim",sys:"pulmo",job:"Tierarzthelferin",scale:1,
 cc:"seit Monaten anfallsartige Luftnot mit pfeifendem Atem, vor allem nachts und bei der Arbeit",
 hpi:"Seit ein paar Monaten bekomme ich anfallsweise schlecht Luft. Beim Ausatmen pfeift es, und ich muss husten. Oft kommt es nachts gegen drei Uhr, dann sitze ich im Bett. Bei der Arbeit in der Tierarztpraxis, vor allem bei Katzen, wird es schlimmer. Am Wochenende und im Urlaub geht es mir besser. Als Kind hatte ich Neurodermitis.",
 pmh:"Neurodermitis im Kindesalter, Heuschnupfen (Gräser)",meds:"Cetirizin 10 mg bei Bedarf",all:"Gräserpollen, Katzenhaare (vermutet)",soc:"Tierarzthelferin, lebt mit Partner, keine Haustiere; Nichtraucherin; Alkohol selten",fam:"Mutter Asthma, Vater Heuschnupfen",
 vit:"RR 118/72 mmHg · HF 92/min · AF 18/min · SpO₂ 97 % · Temp. 36,7 °C · exspiratorisches Giemen beidseits",
 dx:"V. a. allergisches Asthma bronchiale (Berufsallergen Tierhaare), teilweise kontrolliert; DD: Vocal-Cord-Dysfunktion, Hyperventilation, chronische Bronchitis, Herzinsuffizienz (unwahrscheinlich)",
 plan:"Lungenfunktion mit Bronchospasmolysetest (Reversibilität), ggf. Provokationstest, FeNO; Allergiediagnostik (Prick, spezifisches IgE); Stufentherapie: ICS-Formoterol bei Bedarf bzw. als Dauertherapie; Inhalationsschulung, Notfallplan; Allergenkarenz; Berufsgenossenschaft informieren (Verdacht auf Berufskrankheit) und Betriebsarzt einbeziehen",
 patientQs:["Muss ich jetzt meinen Beruf aufgeben?","Sind Kortisonsprays gefährlich?","Wie benutze ich so ein Spray richtig?"],
 oa:[{q:"Wie sichern Sie die Diagnose?",a:"Mit der Lungenfunktion: eine obstruktive Ventilationsstörung mit erniedrigtem FEV1/FVC, die nach Bronchospasmolyse reversibel ist (Anstieg des FEV1 um mindestens 12 % und 200 ml). Bei normaler Lungenfunktion ein Provokationstest. Dazu Allergiediagnostik mit Prick-Test und spezifischem IgE.",kw:["Lungenfunktion|Spirometrie","FEV1","Reversib|Bronchospasmolyse","12","Provokation","Prick|IgE|Allergietest"]},
  {q:"Wie behandeln Sie nach dem Stufenschema?",a:"Bevorzugt ein inhalatives Kortikosteroid in Kombination mit Formoterol, in niedrigen Stufen bei Bedarf, sonst als Dauer- und Bedarfstherapie; bei unzureichender Kontrolle Dosissteigerung, zusätzlich LAMA, bei schwerem Asthma Biologika. Dazu Inhalationsschulung, Allergenkarenz und ein schriftlicher Notfallplan.",kw:["ICS|inhalatives Kortikosteroid|Kortison","Formoterol|LABA","Stufe","Schulung|Inhalationstechnik","Notfallplan","Allergenkarenz|meiden"]},
  {q:"Welche berufliche Konsequenz hat der Verdacht?",a:"Der Verdacht auf ein berufsbedingtes allergisches Asthma muss als Berufskrankheit der Berufsgenossenschaft gemeldet werden. Ziel ist zuerst die Allergenreduktion am Arbeitsplatz mit dem Betriebsarzt; ein Berufswechsel ist nicht automatisch nötig.",kw:["Berufskrankheit","Berufsgenossenschaft|BG|Unfallversicherung","melden|Meldung|Anzeige","Betriebsarzt","Arbeitsplatz"]}],
 traps:"Ask when it gets better: weekends and holidays point to an occupational cause. Explain the inhaler step by step, and say clearly that inhaled steroids are safe at these doses. Lay terms: 'Asthma', 'pfeifende Atmung', 'Kortisonspray'.",
 terms:["Asthma bronchiale","Giemen","Obstruktion","Bronchospasmolyse","Berufskrankheit"],
 lay:{open:"Ich bekomme seit Monaten anfallsweise schlecht Luft, und beim Ausatmen pfeift es. Oft nachts und bei der Arbeit.",pmh:"Als Kind hatte ich Neurodermitis, und ich habe Heuschnupfen.",ops:"Nein, noch nie.",meds:"Bei Heuschnupfen nehme ich Cetirizin, sonst nichts.",all:"Gegen Gräserpollen, das ist getestet. Und ich glaube, gegen Katzen.",
  fam:"Meine Mutter hat Asthma, mein Vater Heuschnupfen.",nox:"Ich rauche nicht. Alkohol trinke ich selten.",drugs:"Nein.",soc:"Ich bin Tierarzthelferin. Ich wohne mit meinem Freund zusammen, wir haben keine Haustiere.",
  char:"Es ist eine Enge in der Brust, und beim Ausatmen pfeift es.",mod:"Bei der Arbeit, besonders mit Katzen, und bei kalter Luft wird es schlimmer. Am Wochenende und im Urlaub ist es viel besser.",prev:"Seit ein paar Monaten immer wieder, aber in letzter Zeit öfter.",self:"Eine Kollegin hat mir ihr blaues Spray gegeben, das hat sofort geholfen.",
  vacc:"Ja, alles, auch Tollwut, wegen der Arbeit.",reise:"Nein.",veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Nachts wache ich oft gegen drei Uhr mit Luftnot auf.",fieber:"Nein."},
  gyn:"Meine Regel ist regelmäßig. Schwanger bin ich nicht."},
 brief:"Frau Schuster ist eine 27-jährige Patientin, die sich mit seit Monaten bestehender anfallsartiger Dyspnoe mit exspiratorischem Pfeifen und Husten vorstellte. Sie berichtete, die Beschwerden träten häufig nachts gegen drei Uhr sowie bei der Arbeit in einer Tierarztpraxis, besonders im Kontakt mit Katzen, auf; am Wochenende und im Urlaub bessere sich die Symptomatik deutlich. Ein geliehenes Salbutamol-Spray habe rasch geholfen.\nAn Vorerkrankungen bestehen eine atopische Dermatitis im Kindesalter und eine Rhinitis allergica (Gräser). Voroperationen wurden verneint. Medikation: Cetirizin bei Bedarf. Es bestehen Allergien gegen Gräserpollen und vermutlich gegen Katzenhaare. Nikotinkonsum wurde verneint. Die Mutter leide an Asthma bronchiale. Die Patientin ist Tierarzthelferin und lebt mit ihrem Partner.\nDie Anamnese spricht für ein allergisches Asthma bronchiale mit Verdacht auf eine berufliche Auslösung. Differenzialdiagnostisch kommen eine Vocal-Cord-Dysfunktion und ein Hyperventilationssyndrom in Betracht. Wir empfehlen: Lungenfunktion mit Bronchospasmolysetest, Allergiediagnostik, eine Therapie mit ICS-Formoterol, eine Inhalationsschulung, einen Notfallplan und die Meldung des Verdachts auf eine Berufskrankheit."},

{id:"fy17",age:66,sex:"m",name:"Herr Roth",vn:"Werner",geb:"30.10.1959",cm:179,kg:68,ha:"Herr Doktor Jäger in Mosbach",sys:"pulmo",job:"Dachdecker im Ruhestand",scale:3,
 cc:"seit zwei Monaten Husten, seit einer Woche blutiger Auswurf, acht Kilo Gewichtsverlust",
 hpi:"Ich huste seit zwei Monaten, mehr als sonst. Seit einer Woche ist Blut im Schleim, ein paar Fäden, heute Morgen ein Teelöffel voll. Ich habe acht Kilo abgenommen, ohne es zu wollen. Nachts schwitze ich, und ich bin müde. Rechts in der Brust zieht es manchmal. Die Stimme ist seit ein paar Wochen heiser.",
 pmh:"COPD GOLD 2; arterielle Hypertonie",meds:"Tiotropium 1-0-0, Salbutamol bei Bedarf, Ramipril 5 mg 1-0-0",all:"keine bekannt",soc:"Dachdecker im Ruhestand (Asbestkontakt in den 70er/80er Jahren), verheiratet; raucht seit 50 Jahren 25 Zigaretten/Tag; Alkohol 2–3 Bier täglich",fam:"Vater Lungenkrebs",
 vit:"RR 132/80 mmHg · HF 92/min · AF 18/min · SpO₂ 93 % · Temp. 37,4 °C",
 dx:"V. a. Bronchialkarzinom rechts mit Hämoptysen, B-Symptomatik und Heiserkeit (Rekurrensparese?); DD: Tuberkulose, Pneumonie, Bronchiektasen, Lungenembolie, Mesotheliom (Asbest)",
 plan:"Röntgen-Thorax, CT Thorax mit Kontrastmittel, Labor (Blutbild, Gerinnung, Calcium, Natrium), Sputum auf Tuberkulose, Bronchoskopie mit Biopsie, PET-CT zum Staging, Lungenfunktion; Tumorkonferenz; Aufklärung schrittweise und ehrlich; Asbestexposition als mögliche Berufskrankheit melden",
 patientQs:["Ist das Krebs? Sagen Sie es mir ehrlich.","Was ist eine Bronchoskopie?","Hätte ich früher aufhören sollen?"],
 oa:[{q:"Welche Diagnostik veranlassen Sie, und in welcher Reihenfolge?",a:"Zuerst Röntgen-Thorax und ein CT des Thorax mit Kontrastmittel, dann die histologische Sicherung meist durch Bronchoskopie mit Biopsie, bei peripheren Herden CT-gesteuert. Zum Staging folgen PET-CT und MRT des Schädels; vor einer Operation eine Lungenfunktion. Wegen Nachtschweiß und Gewichtsverlust schließe ich eine Tuberkulose aus.",kw:["Röntgen","CT","Bronchoskopie","Biopsie|Histolog","PET|Staging","Tuberkulose"]},
  {q:"Wie überbringen Sie dem Patienten den Verdacht?",a:"In einem ruhigen Raum mit genügend Zeit, auf Wunsch mit Angehörigen. Ich frage zuerst, was er selbst vermutet und wie viel er wissen möchte, kündige an, dass ich keine guten Nachrichten habe, spreche klar von einem Verdacht auf einen Tumor, lasse Pausen, gehe auf seine Gefühle ein und erkläre die nächsten Schritte. Das entspricht dem SPIKES-Modell.",kw:["ruhig|Raum|Zeit","was er weiß|Vorwissen|vermutet","Warnschuss|keine guten Nachrichten","Pause|Gefühl|Emotion|Empathie","nächste Schritte|Plan","SPIKES"]},
  {q:"Welche Bedeutung hat die Berufsanamnese?",a:"Als Dachdecker hatte er Kontakt mit Asbest. Asbest erhöht das Risiko für Lungenkrebs, besonders in Kombination mit Rauchen, und für ein Mesotheliom. Der begründete Verdacht einer Berufskrankheit muss der Unfallversicherung gemeldet werden.",kw:["Asbest","Mesotheliom","Rauchen|synergistisch|multipliziert","Berufskrankheit","melden|Unfallversicherung|BG"]}],
 traps:"Breaking-bad-news case: no jargon, no false comfort, no 'Krebs' as the first word – but no lie when he asks directly. Do not forget tuberculosis (night sweats) and asbestos. Lay terms: 'Lungenspiegelung', 'Gewebeprobe', 'Schatten auf der Lunge'.",
 terms:["Bronchialkarzinom","Hämoptysen","B-Symptomatik","Bronchoskopie","Asbestose"],
 lay:{open:"Ich huste seit zwei Monaten, und seit einer Woche ist Blut im Schleim.",pmh:"Ich habe eine Raucherlunge und hohen Blutdruck.",ops:"Nein, operiert worden bin ich nie.",meds:"Ein Spray für die Lunge morgens, eins für den Notfall und eine Blutdrucktablette.",all:"Nein, keine.",
  fam:"Mein Vater ist an Lungenkrebs gestorben.",nox:"Ich rauche seit fünfzig Jahren, ungefähr fünfundzwanzig Zigaretten am Tag. Abends trinke ich zwei, drei Bier.",drugs:"Nein.",soc:"Ich war Dachdecker. Früher haben wir viel mit Eternitplatten gearbeitet, da war Asbest drin. Ich bin verheiratet.",
  char:"In der Brust rechts zieht es manchmal, kein starker Schmerz.",mod:"Beim Husten zieht es mehr.",prev:"Husten habe ich als Raucher immer. Aber Blut hatte ich noch nie.",self:"Hustensaft aus der Apotheke, ohne Erfolg.",
  vacc:"Grippe ja, Lungenentzündung weiß ich nicht.",reise:"Nein.",veg:{appetit:"Ich habe kaum Appetit.",gewicht:"Ich habe acht Kilo abgenommen in zwei Monaten.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Ich schwitze nachts stark.",fieber:"Abends manchmal leicht erhöht, 37,5."}},
 brief:"Herr Roth ist ein 66-jähriger Patient, der sich mit seit zwei Monaten verstärktem Husten und seit einer Woche bestehenden Hämoptysen vorstellte. Er berichtete über einen ungewollten Gewichtsverlust von acht Kilogramm, Nachtschweiß, Müdigkeit und eine seit einigen Wochen bestehende Heiserkeit. Gelegentlich bestehe ein Ziehen im rechten Thorax.\nAn Vorerkrankungen bestehen eine COPD (GOLD 2) und eine arterielle Hypertonie. Voroperationen wurden verneint. Medikation: Tiotropium 1-0-0, Salbutamol bei Bedarf, Ramipril 5 mg 1-0-0. Allergien sind nicht bekannt. Der Patient rauche seit 50 Jahren etwa 25 Zigaretten pro Tag (über 60 Packungsjahre) und trinke täglich zwei bis drei Bier. Als Dachdecker habe er beruflich Kontakt zu Asbest gehabt. Der Vater sei an einem Bronchialkarzinom verstorben. Der Patient ist Rentner und verheiratet.\nDie Anamnese spricht für ein Bronchialkarzinom mit B-Symptomatik. Differenzialdiagnostisch kommen eine Tuberkulose, eine Pneumonie und ein Mesotheliom in Betracht. Wir empfehlen: Röntgen- und CT-Thorax, Sputum auf Tuberkulose, eine Bronchoskopie mit Biopsie, ein Staging, die Vorstellung in der Tumorkonferenz und die Meldung des Verdachts auf eine Berufskrankheit."},

{id:"fy18",age:34,sex:"m",name:"Herr Haddad",vn:"Karim",geb:"16.03.1992",cm:181,kg:63,ha:"Frau Doktor Wagner in Mannheim-Jungbusch",sys:"infekt",job:"Küchenhilfe",scale:2,
 cc:"seit fünf Wochen Husten, Nachtschweiß, Gewichtsverlust; vor einem Jahr aus einem Land mit hoher Tuberkulose-Inzidenz zugewandert",
 hpi:"Ich huste seit über einem Monat, und es wird nicht besser. Manchmal ist der Schleim gelblich, einmal war ein bisschen Blut dabei. Nachts schwitze ich so stark, dass das Bettlaken nass ist. Ich habe sechs Kilo abgenommen und bin immer müde. Abends habe ich oft leichtes Fieber. Mein Mitbewohner hustet auch seit ein paar Wochen.",
 pmh:"bisher gesund; HIV-Status unbekannt",meds:"keine",all:"keine bekannt",soc:"Küchenhilfe, lebt in einer Gemeinschaftsunterkunft mit drei Mitbewohnern; Nichtraucher; kein Alkohol",fam:"Onkel Tuberkulose",
 vit:"RR 116/70 mmHg · HF 96/min · AF 18/min · SpO₂ 96 % · Temp. 38,0 °C",
 dx:"V. a. offene Lungentuberkulose; DD: Pneumonie, Bronchialkarzinom (unwahrscheinlich), Lymphom, HIV-assoziierte Infektion, Sarkoidose",
 plan:"Sofortige Isolierung (Einzelzimmer, FFP2-Maske für Personal, Mund-Nasen-Schutz für den Patienten), Röntgen-Thorax, Sputum an drei Tagen (Mikroskopie, PCR, Kultur mit Resistenztestung), Interferon-Gamma-Test, HIV-Test nach Einwilligung, Leberwerte; Meldung an das Gesundheitsamt; Standardtherapie mit Isoniazid, Rifampicin, Pyrazinamid, Ethambutol nach Sicherung; Umgebungsuntersuchung durch das Gesundheitsamt",
 patientQs:["Muss ich ins Gefängnis oder werde ich abgeschoben, wenn ich Tuberkulose habe?","Wie lange muss ich die Tabletten nehmen?","Darf ich wieder in der Küche arbeiten?"],
 oa:[{q:"Welche Maßnahmen ergreifen Sie sofort, und wie sichern Sie die Diagnose?",a:"Sofortige Isolierung im Einzelzimmer, Personal mit FFP2-Maske, der Patient mit Mund-Nasen-Schutz. Röntgen-Thorax, Sputum an drei Tagen für Mikroskopie, PCR und Kultur mit Resistenztestung. Ergänzend ein Interferon-Gamma-Test und nach Einwilligung ein HIV-Test.",kw:["Isolier","FFP2|Maske","Röntgen","Sputum","PCR|Kultur|Mikroskop","HIV"]},
  {q:"Wie wird eine unkomplizierte Lungentuberkulose behandelt?",a:"Zwei Monate Initialphase mit Isoniazid, Rifampicin, Pyrazinamid und Ethambutol, danach vier Monate Kontinuitätsphase mit Isoniazid und Rifampicin, insgesamt also sechs Monate. Wichtig sind die regelmäßige Einnahme, Kontrollen der Leberwerte und der Sehfähigkeit wegen Ethambutol.",kw:["Isoniazid","Rifampicin","Pyrazinamid","Ethambutol","sechs Monate|6 Monate","Leber"]},
  {q:"Welche Pflichten haben Sie gegenüber dem Gesundheitsamt?",a:"Erkrankung und Tod an einer behandlungsbedürftigen Tuberkulose sind nach dem Infektionsschutzgesetz namentlich meldepflichtig. Das Gesundheitsamt organisiert die Umgebungsuntersuchung der Kontaktpersonen, hier besonders der Mitbewohner, und überwacht den Therapieabschluss.",kw:["Meldepflicht|melden|IfSG|Infektionsschutzgesetz","namentlich","Umgebungsuntersuchung|Kontaktpersonen","Mitbewohner"]}],
 traps:"Ask about origin and living conditions neutrally – it is medicine, not suspicion. The patient's fear about consequences must be answered calmly: the medical confidentiality and the purpose of the health office. Lay terms: 'Tuberkulose', 'ansteckende Lungenkrankheit', 'Schleimprobe'.",
 terms:["Tuberkulose","Hämoptysen","Nachtschweiß","Meldepflicht","Isolierung"],
 lay:{open:"Ich huste seit über einem Monat, ich schwitze nachts sehr stark und habe abgenommen.",pmh:"Ich war immer gesund. Einen HIV-Test habe ich noch nie gemacht.",ops:"Nein, noch nie.",meds:"Ich nehme keine Medikamente.",all:"Nein, keine.",fam:"Mein Onkel hatte Tuberkulose, als ich ein Kind war. Wir haben im selben Haus gewohnt.",
  nox:"Ich rauche nicht. Alkohol trinke ich gar nicht.",drugs:"Nein.",soc:"Ich arbeite als Küchenhilfe in einem Restaurant. Ich wohne in einer Unterkunft, mit drei anderen Männern in einem Zimmer. Vor einem Jahr bin ich nach Deutschland gekommen.",
  char:"In der Brust tut es nur beim Husten ein bisschen weh.",mod:"Nachts und morgens ist der Husten am schlimmsten.",prev:"Nein, so lange habe ich noch nie gehustet.",self:"Ich habe Hustensaft und Tee genommen, das hat nicht geholfen.",
  vacc:"Als Kind bin ich geimpft worden, ich habe eine Narbe am Arm. Mehr weiß ich nicht.",reise:"Ich bin vor einem Jahr nach Deutschland gekommen. Seitdem war ich nicht mehr weg.",
  veg:{appetit:"Ich habe kaum Appetit.",gewicht:"Ich habe sechs Kilo abgenommen, die Hose ist zu weit.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Nachts schwitze ich so stark, dass das Laken nass ist.",fieber:"Abends habe ich oft Fieber, so 38."}},
 brief:"Herr Haddad ist ein 34-jähriger Patient, der sich mit seit über fünf Wochen bestehendem produktivem Husten vorstellte. Er berichtete über einmalige Blutbeimengungen im Sputum, ausgeprägten Nachtschweiß, abendliche subfebrile bis febrile Temperaturen, Müdigkeit und einen ungewollten Gewichtsverlust von sechs Kilogramm. Ein Mitbewohner huste ebenfalls seit einigen Wochen.\nVorerkrankungen und Voroperationen sind nicht bekannt; der HIV-Status ist unbekannt. Keine Medikation. Allergien sind nicht bekannt. Nikotin- und Alkoholkonsum wurden verneint. Ein Onkel habe an einer Tuberkulose gelitten. Der Patient ist Küchenhilfe, lebt seit einem Jahr in Deutschland in einer Gemeinschaftsunterkunft und ist in der Kindheit BCG-geimpft.\nDie Anamnese spricht für eine offene Lungentuberkulose. Differenzialdiagnostisch kommen eine Pneumonie, ein Lymphom und eine HIV-assoziierte Infektion in Betracht. Wir empfehlen: sofortige Isolierung, Röntgen-Thorax, Sputumuntersuchungen an drei Tagen mit PCR und Kultur, einen HIV-Test nach Einwilligung, die Meldung an das Gesundheitsamt und nach Sicherung eine Vierfachtherapie."},

{id:"fy19",age:29,sex:"w",name:"Frau Kessler",vn:"Anna",geb:"07.01.1997",cm:166,kg:58,ha:"Herr Doktor Pohl in Edingen",sys:"neuro",job:"Lehrerin",scale:8,
 cc:"seit dem Morgen halbseitiger pulsierender Kopfschmerz links mit vorausgehendem Flimmern im Gesichtsfeld, Übelkeit",
 hpi:"Heute Morgen habe ich zuerst ein Flimmern und Zickzacklinien vor den Augen gesehen, ungefähr zwanzig Minuten lang. Danach kamen starke, pochende Kopfschmerzen links an der Schläfe. Mir ist übel, Licht und Lärm sind unerträglich. Solche Anfälle habe ich seit der Jugend etwa einmal im Monat, meistens kurz vor der Periode. Heute ist es stärker als sonst, und meine Tabletten helfen nicht.",
 pmh:"Migräne mit Aura seit dem 15. Lebensjahr",meds:"kombiniertes orales Kontrazeptivum; Ibuprofen 400 mg bei Attacken",all:"keine bekannt",soc:"Lehrerin, ledig; raucht 8 Zigaretten/Tag; Alkohol gelegentlich; viel Stress, wenig Schlaf",fam:"Mutter Migräne",
 vit:"RR 128/80 mmHg · HF 76/min · AF 14/min · SpO₂ 99 % · Temp. 36,8 °C · neurologisch unauffällig",
 dx:"Migräneattacke mit Aura; Problem: kombiniertes orales Kontrazeptivum bei Migräne mit Aura und Nikotinkonsum (erhöhtes Schlaganfallrisiko); DD: Subarachnoidalblutung, TIA, Sinusvenenthrombose, Spannungskopfschmerz",
 plan:"Neurologische Untersuchung; bei typischem Verlauf keine Bildgebung, bei Warnzeichen cCT; Akuttherapie: Antiemetikum (Metoclopramid), ASS i.v. oder Triptan; Triptane nicht während der Aura; östrogenhaltige Pille absetzen und gestagenmonopräparat besprechen; Rauchstopp; Kopfschmerztagebuch; Prophylaxe erwägen (z. B. Betablocker, Topiramat) bei ≥ 3 Attacken/Monat",
 patientQs:["Ist das wirklich nur Migräne und nichts im Kopf?","Warum soll ich die Pille nicht mehr nehmen?","Was kann ich tun, damit die Anfälle seltener werden?"],
 oa:[{q:"Welche Warnzeichen würden Sie an eine sekundäre Kopfschmerzursache denken lassen?",a:"Ein erstmaliger oder plötzlicher Donnerschlagkopfschmerz, eine Änderung des bekannten Kopfschmerzmusters, neurologische Ausfälle, die länger als eine Stunde dauern, Fieber, Meningismus, Bewusstseinsstörung, Beginn nach dem 50. Lebensjahr, Schwangerschaft oder Immunsuppression.",kw:["plötzlich|Donnerschlag","neu|erstmalig|Änderung","neurologisch|Ausfälle","Fieber|Meningismus","50|Alter","Aura.{0,30}(lang|Stunde)"]},
  {q:"Wie behandeln Sie die Attacke akut?",a:"Ein Antiemetikum wie Metoclopramid, dazu ein Analgetikum wie ASS 1000 mg intravenös oder ein Triptan. Das Triptan sollte erst mit Beginn des Kopfschmerzes, nicht während der Aura gegeben werden. Ruhe in einem abgedunkelten Raum.",kw:["Metoclopramid|Antiemetikum","ASS|Aspirin|Ibuprofen|Analgetikum","Triptan","Aura|nicht während","abgedunkelt|Ruhe"]},
  {q:"Was ist bei dieser Patientin bezüglich der Verhütung wichtig?",a:"Bei Migräne mit Aura sind östrogenhaltige Kontrazeptiva wegen des erhöhten Risikos für ischämische Schlaganfälle kontraindiziert, besonders in Kombination mit Rauchen. Ich rate zum Absetzen der kombinierten Pille und zu einer östrogenfreien Methode, etwa einem Gestagenmonopräparat oder einer Spirale, und zum Rauchstopp.",kw:["Östrogen|kombinierte Pille","Schlaganfall","Rauchen","kontraindiziert|absetzen","Gestagen|Spirale|östrogenfrei"]}],
 traps:"A patient who says 'stronger than usual' needs the red-flag questions before the migraine label. The pill plus aura plus smoking is the point examiners wait for. Lay terms: 'Sehstörung vor dem Kopfschmerz', 'Schlaganfallrisiko'.",
 terms:["Migräne","Aura","Photophobie","Triptan","Prophylaxe"],
 lay:{open:"Ich habe heute Morgen zuerst ein Flimmern vor den Augen gehabt und danach starke, pochende Kopfschmerzen links.",pmh:"Ich habe Migräne mit Aura, seit ich fünfzehn bin.",ops:"Nein, noch nie.",meds:"Ich nehme die Pille, und bei Migräne Ibuprofen 400.",all:"Nein, keine.",fam:"Meine Mutter hat auch Migräne.",
  nox:"Ich rauche ungefähr acht Zigaretten am Tag. Alkohol trinke ich gelegentlich.",drugs:"Nein.",soc:"Ich bin Lehrerin an einer Realschule. Im Moment habe ich viel Stress und schlafe zu wenig. Ich lebe allein.",
  char:"Es ist ein pochender, pulsierender Schmerz.",rad:"Es zieht von der linken Schläfe hinter das linke Auge.",mod:"Licht, Lärm und Bewegung machen es schlimmer. Im dunklen Zimmer liegen hilft etwas.",prev:"Ja, ungefähr einmal im Monat, meistens vor der Periode. Aber heute ist es stärker als sonst, und das Flimmern war länger.",self:"Ich habe zwei Ibuprofen genommen, das hat diesmal nicht geholfen.",
  vacc:"Ja, alles.",reise:"Nein.",veg:{appetit:"Mir ist übel, ich mag nichts essen.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Normal.",schlaf:"In letzter Zeit schlafe ich zu wenig.",fieber:"Nein, Fieber habe ich nicht."},
  gyn:"Meine Periode kommt in zwei Tagen. Ich nehme die Pille, schwanger bin ich nicht."},
 brief:"Frau Kessler ist eine 29-jährige Patientin, die sich mit seit dem Morgen bestehenden linksseitigen, pulsierenden Kopfschmerzen vorstellte. Sie berichtete, zuvor seien für etwa 20 Minuten ein Flimmern und Zickzacklinien im Gesichtsfeld aufgetreten. Begleitend bestünden Übelkeit, Photo- und Phonophobie. Seit der Jugend habe sie etwa monatlich ähnliche, meist menstruationsassoziierte Attacken; die aktuelle sei stärker als gewohnt, Ibuprofen sei ohne Wirkung geblieben. Neurologische Ausfälle, Fieber und ein plötzlicher Beginn wurden verneint.\nAn Vorerkrankungen ist eine Migräne mit Aura bekannt. Voroperationen wurden verneint. Medikation: kombiniertes orales Kontrazeptivum, Ibuprofen 400 mg bei Bedarf. Allergien sind nicht bekannt. Die Patientin rauche acht Zigaretten pro Tag. Die Mutter leide ebenfalls an Migräne. Die Patientin ist Lehrerin.\nEs handelt sich am ehesten um eine Migräneattacke mit Aura. Differenzialdiagnostisch sind eine Subarachnoidalblutung, eine TIA und eine Sinusvenenthrombose zu bedenken. Wir empfehlen: neurologische Untersuchung, Metoclopramid und ASS intravenös bzw. ein Triptan, das Absetzen des östrogenhaltigen Kontrazeptivums mit Beratung zu einer östrogenfreien Verhütung, den Rauchstopp und ein Kopfschmerztagebuch."},

{id:"fy20",age:45,sex:"m",name:"Herr Becker",vn:"Frank",geb:"04.04.1981",cm:185,kg:94,ha:"Frau Doktor Huber in Hockenheim",sys:"muskulo",job:"Paketzusteller",scale:8,
 cc:"seit drei Tagen Rückenschmerzen nach dem Heben mit Ausstrahlung ins linke Bein bis in den Fuß, Kribbeln an der Fußaußenseite",
 hpi:"Vor drei Tagen habe ich bei der Arbeit ein schweres Paket gehoben, da hat es im Kreuz geschossen, wie ein Hexenschuss. Seitdem zieht der Schmerz vom Rücken hinten über das linke Bein bis in den Fuß. Am Fußrand links kribbelt es und fühlt sich taub an. Husten und Niesen tun höllisch weh. Wasserlassen und Stuhlgang sind normal, und im Schritt habe ich kein Taubheitsgefühl.",
 pmh:"rezidivierende Lumbalgien",meds:"Ibuprofen 600 mg 1-1-1 seit drei Tagen",all:"keine bekannt",soc:"Paketzusteller, verheiratet, zwei Kinder; raucht 15 Zigaretten/Tag; Alkohol am Wochenende",fam:"Vater Bandscheibenvorfall",
 vit:"RR 142/86 mmHg · HF 84/min · AF 14/min · SpO₂ 98 % · Temp. 36,7 °C · Lasègue links bei 40° positiv, ASR links abgeschwächt",
 dx:"Lumbaler Bandscheibenvorfall L5/S1 links mit S1-Radikulopathie ohne motorisches Defizit; DD: Spinalkanalstenose, Facettensyndrom, Tumor/Metastase, Spondylodiszitis, Kaudasyndrom (ausgeschlossen), Arbeitsunfall?",
 plan:"Neurologische Untersuchung (Kraftgrade, Reflexe, Sensibilität, Reithosenanästhesie, Restharn), bei Red Flags sofort MRT; sonst konservativ: Analgesie (NSAR mit Magenschutz, ggf. kurz Opioid), Bewegung statt Bettruhe, Physiotherapie; MRT bei Paresen oder Persistenz > 6 Wochen; Operation bei Kaudasyndrom, progredienter Parese oder therapieresistenten Schmerzen; als Hebetrauma bei der Arbeit: D-Arzt-Verfahren prüfen",
 patientQs:["Muss ich operiert werden?","Soll ich mich hinlegen und schonen?","Wann kann ich wieder Pakete tragen?"],
 oa:[{q:"Welche Warnzeichen erfordern eine sofortige Bildgebung und Operation?",a:"Ein Kaudasyndrom mit Reithosenanästhesie, Blasen- oder Mastdarmstörung, eine akute oder zunehmende Parese, außerdem Fieber, Tumoranamnese, Trauma oder ungewollter Gewichtsverlust als Hinweise auf eine andere Ursache. Dann sofort MRT und neurochirurgische Vorstellung.",kw:["Kauda|Reithose","Blase|Mastdarm|Inkontinenz|Harnverhalt","Parese|Lähmung|Kraft","Fieber|Tumor|Gewichtsverlust","MRT","sofort|Notfall"]},
  {q:"Welcher Nerv ist betroffen, und woran erkennen Sie das?",a:"Die Ausstrahlung an der Rückseite des Beins bis zur Fußaußenseite, die Sensibilitätsstörung am lateralen Fußrand und der abgeschwächte Achillessehnenreflex sprechen für eine Wurzelreizung S1, meist durch einen Bandscheibenvorfall L5/S1.",kw:["S1","Achillessehnenreflex|ASR","Fußaußen|lateral|Fußrand","L5/S1|L5-S1","Lasègue"]},
  {q:"Wie behandeln Sie konservativ, und was raten Sie dem Patienten?",a:"Ausreichende Analgesie, zum Beispiel NSAR mit Magenschutz, kurzfristig auch ein Opioid; keine Bettruhe, sondern Bewegung im schmerzarmen Rahmen und Physiotherapie. Die meisten Bandscheibenvorfälle bessern sich innerhalb von sechs bis zwölf Wochen. Bei Lähmungen oder Störungen beim Wasserlassen sofort wiederkommen.",kw:["NSAR|Analgesie|Schmerzmittel","Magenschutz|PPI","keine Bettruhe|Bewegung","Physiotherapie","sechs|6|zwölf|12 Wochen","wiederkommen|Warnzeichen"]}],
 traps:"The red flags (Reithosenanästhesie, bladder, bowel, weakness) must be asked explicitly and documented as 'verneint'. Lifting at work = Arbeitsunfall question: Berufsgenossenschaft and D-Arzt. Lay terms: 'Bandscheibenvorfall', 'eingeklemmter Nerv', 'Taubheit im Schritt'.",
 terms:["Bandscheibenvorfall","Radikulopathie","Lumbago","Kaudasyndrom","Parese"],
 lay:{open:"Ich habe mir vor drei Tagen beim Heben eines Pakets den Rücken verrissen, und jetzt zieht es bis in den linken Fuß.",pmh:"Ich habe immer wieder Rückenschmerzen, aber nie so schlimm.",ops:"Nein, noch nie.",meds:"Seit drei Tagen nehme ich dreimal am Tag Ibuprofen 600.",all:"Nein, keine.",fam:"Mein Vater hatte einen Bandscheibenvorfall.",
  nox:"Ich rauche fünfzehn Zigaretten am Tag. Am Wochenende trinke ich Bier.",drugs:"Nein.",soc:"Ich bin Paketzusteller, ich trage den ganzen Tag schwere Pakete. Ich bin verheiratet und habe zwei Kinder.",
  char:"Es ist ein elektrisierender, stechender Schmerz, der ins Bein schießt.",rad:"Vom Rücken hinten über das linke Bein bis in den Fuß, außen.",mod:"Husten, Niesen und Sitzen machen es schlimmer. Am besten geht es im Liegen mit angezogenen Beinen.",prev:"Hexenschüsse hatte ich schon öfter, aber nie mit Schmerzen bis in den Fuß.",self:"Ibuprofen und eine Wärmflasche. Es hat nur ein bisschen geholfen.",
  vacc:"Ja.",reise:"Nein.",veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Der Stuhlgang ist normal, ich kann ihn halten.",wasser:"Das Wasserlassen ist normal, ich spüre, wann ich muss.",schlaf:"Wegen der Schmerzen schlafe ich schlecht.",fieber:"Nein."}},
 brief:"Herr Becker ist ein 45-jähriger Patient, der sich mit seit drei Tagen bestehenden lumbalen Schmerzen mit Ausstrahlung in das linke Bein vorstellte. Er berichtete, die Beschwerden hätten beim Heben eines schweren Pakets bei der Arbeit plötzlich begonnen. Der Schmerz ziehe dorsal bis zum lateralen Fußrand; dort bestünden Kribbeln und Taubheit. Husten und Niesen verstärkten die Schmerzen (8/10). Blasen- und Mastdarmstörungen sowie eine Reithosenanästhesie wurden verneint.\nAn Vorerkrankungen sind rezidivierende Lumbalgien bekannt. Voroperationen wurden verneint. Medikation: Ibuprofen 600 mg 1-1-1 seit drei Tagen. Allergien sind nicht bekannt. Der Patient rauche 15 Zigaretten pro Tag. Der Vater habe einen Bandscheibenvorfall gehabt. Der Patient ist Paketzusteller, verheiratet und hat zwei Kinder; das Ereignis geschah bei der Arbeit.\nDie Anamnese spricht für einen lumbalen Bandscheibenvorfall L5/S1 links mit S1-Radikulopathie ohne Hinweis auf ein Kaudasyndrom. Differenzialdiagnostisch kommen eine Spinalkanalstenose und ein Facettensyndrom in Betracht. Wir empfehlen: neurologische Untersuchung, Analgesie mit Magenschutz, Bewegung statt Bettruhe, Physiotherapie, ein MRT bei Paresen oder Persistenz sowie die Prüfung eines Arbeitsunfalls im D-Arzt-Verfahren."},

{id:"fy21",age:58,sex:"w",name:"Frau Krause",vn:"Heike",geb:"11.11.1967",cm:164,kg:66,ha:"Herr Doktor Wenzel in Leimen",sys:"muskulo",job:"Reinigungskraft in einer Schule",scale:7,
 cc:"vor einer Stunde bei der Arbeit auf nassem Boden ausgerutscht, Sturz auf die ausgestreckte rechte Hand, Schmerzen und Fehlstellung am Handgelenk",
 hpi:"Ich habe vor einer Stunde in der Schule den Flur gewischt und bin auf dem nassen Boden ausgerutscht. Ich habe mich mit der rechten Hand abgefangen. Jetzt ist das Handgelenk geschwollen und sieht schief aus, wie eine Gabel. Ich kann die Hand kaum bewegen. Die Finger kribbeln ein bisschen. Den Kopf habe ich nicht angeschlagen.",
 pmh:"Osteopenie (DXA 2024); Hypothyreose",meds:"L-Thyroxin 50 µg 1-0-0, Calcium/Vitamin D 1-0-0",all:"keine bekannt",soc:"Reinigungskraft in einer Schule (Arbeitsunfall), Rechtshänderin, verheiratet; Nichtraucherin; Alkohol selten",fam:"Mutter Osteoporose mit Wirbelkörperfrakturen",
 vit:"RR 142/84 mmHg · HF 92/min · AF 16/min · SpO₂ 98 % · Temp. 36,6 °C · NRS 7/10 · DMS: Sensibilität Dig. I–III leicht vermindert",
 dx:"Distale Radiusfraktur rechts, extensionsbedingt (Colles-Fraktur), Arbeitsunfall; DD: Skaphoidfraktur, Luxation, Kontusion; Hinweis auf Osteoporose",
 plan:"Durchblutung, Motorik und Sensibilität prüfen und dokumentieren (N. medianus), Röntgen Handgelenk in zwei Ebenen, ggf. CT; Analgesie, Reposition in Bruchspaltanästhesie und Gipsschiene bzw. operative Versorgung (winkelstabile Plattenosteosynthese) je nach Frakturtyp; Hochlagern, Kühlen; Tetanusstatus prüfen; D-Arzt-Verfahren (Arbeitsunfall, Berufsgenossenschaft/Unfallkasse); Osteoporose-Abklärung",
 patientQs:["Ist das gebrochen? Muss das operiert werden?","Wer bezahlt das, wenn ich bei der Arbeit gefallen bin?","Wie lange kann ich nicht putzen?"],
 oa:[{q:"Was prüfen und dokumentieren Sie vor und nach jeder Reposition?",a:"Durchblutung, Motorik und Sensibilität, kurz DMS, besonders die Funktion des Nervus medianus, also das Gefühl an Daumen, Zeige- und Mittelfinger. Bei zunehmender Taubheit kann ein akutes Karpaltunnelsyndrom vorliegen.",kw:["Durchblutung","Motorik","Sensibilität","DMS","medianus","Karpaltunnel"]},
  {q:"Welche Besonderheit hat die Versorgung eines Arbeitsunfalls?",a:"Arbeits- und Wegeunfälle laufen über die gesetzliche Unfallversicherung, also die Berufsgenossenschaft oder Unfallkasse. Die Patientin muss einem Durchgangsarzt (D-Arzt) vorgestellt werden, der den Bericht erstellt und die Heilbehandlung steuert. Die Kosten trägt die Unfallversicherung.",kw:["Arbeitsunfall|Wegeunfall","Unfallversicherung|Berufsgenossenschaft|Unfallkasse","D-Arzt|Durchgangsarzt","Bericht|Kosten"]},
  {q:"Was veranlassen Sie wegen der Knochenstruktur?",a:"Eine distale Radiusfraktur nach einem Bagatellsturz bei einer Frau über 50 ist eine Indikatorfraktur für Osteoporose. Ich empfehle eine Osteoporose-Abklärung mit DXA-Messung, Labor und Sturzrisikobewertung sowie gegebenenfalls eine spezifische Therapie, zum Beispiel ein Bisphosphonat.",kw:["Osteoporose","Indikatorfraktur|Fragilität|Bagatell","DXA|Knochendichte","Bisphosphonat|Therapie","Sturz"]}],
 traps:"The work accident is the exam trap: ask where and when it happened and say 'D-Arzt' and 'Berufsgenossenschaft'. Document neurovascular status before and after anything you do. Lay terms: 'Handgelenk gebrochen', 'einrenken', 'Gips'.",
 terms:["Distale Radiusfraktur","Reposition","Osteosynthese","Osteoporose","Durchgangsarzt"],
 lay:{open:"Ich bin vor einer Stunde bei der Arbeit ausgerutscht und auf die rechte Hand gefallen. Das Handgelenk ist dick und schief.",pmh:"Meine Knochen sind etwas dünn, das hat man letztes Jahr gemessen. Und ich habe eine Schilddrüsenunterfunktion.",ops:"Nein, noch nie.",meds:"Eine Schilddrüsentablette und eine Tablette mit Calcium und Vitamin D, beide morgens.",all:"Nein, keine.",
  fam:"Meine Mutter hatte starke Osteoporose, ihr sind Wirbel eingebrochen.",nox:"Ich rauche nicht. Alkohol trinke ich selten.",drugs:"Nein.",soc:"Ich arbeite als Reinigungskraft in einer Schule. Ich bin Rechtshänderin. Ich bin verheiratet.",
  char:"Es ist ein starker, pochender Schmerz im Handgelenk.",rad:"Es zieht in den Unterarm.",mod:"Jede Bewegung tut weh. Wenn ich die Hand hochhalte und kühle, ist es besser.",prev:"Nein, gebrochen hatte ich mir noch nie etwas.",self:"Die Hausmeisterin hat mir ein Kühlpack gegeben.",
  vacc:"Tetanus ist, glaube ich, über zehn Jahre her.",reise:"Nein.",lastmeal:"Um sieben Uhr habe ich gefrühstückt, seitdem nur Wasser.",veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Gut.",fieber:"Nein."},
  gyn:"Die Wechseljahre sind seit sechs Jahren vorbei."},
 brief:"Frau Krause ist eine 58-jährige Patientin, die sich etwa eine Stunde nach einem Sturz auf die ausgestreckte rechte Hand vorstellte. Sie berichtete, sie sei bei der Arbeit als Reinigungskraft in einer Schule auf nassem Boden ausgerutscht (Arbeitsunfall). Seitdem bestünden starke Schmerzen (7/10), eine Schwellung und eine Fehlstellung des rechten Handgelenks; die Finger kribbelten leicht. Ein Kopfanprall wurde verneint. Der letzte Tetanusschutz liege vermutlich über zehn Jahre zurück.\nAn Vorerkrankungen bestehen eine Osteopenie und eine Hypothyreose. Voroperationen wurden verneint. Medikation: L-Thyroxin 50 µg 1-0-0, Calcium/Vitamin D 1-0-0. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint. Die Mutter habe an einer Osteoporose mit Wirbelkörperfrakturen gelitten. Die Patientin ist Rechtshänderin und verheiratet.\nEs besteht der Verdacht auf eine distale Radiusfraktur rechts vom Extensionstyp. Differenzialdiagnostisch kommen eine Skaphoidfraktur und eine Luxation in Betracht. Wir empfehlen: Dokumentation von Durchblutung, Motorik und Sensibilität, Röntgen des Handgelenks in zwei Ebenen, Analgesie, Reposition und Ruhigstellung bzw. operative Versorgung, eine Tetanusauffrischung, die Vorstellung beim Durchgangsarzt und eine Osteoporose-Abklärung."},

{id:"fy22",age:24,sex:"m",name:"Herr Winkler",vn:"Lukas",geb:"29.06.2002",cm:186,kg:72,ha:"Frau Doktor Fuchs in Heidelberg-Bergheim",sys:"haem",job:"Student (Maschinenbau)",scale:1,
 cc:"seit zwei Monaten schmerzlose Schwellung am Hals links, Nachtschweiß, Juckreiz, fünf Kilo Gewichtsverlust",
 hpi:"Vor zwei Monaten habe ich beim Rasieren eine Beule links am Hals bemerkt. Sie tut nicht weh und ist langsam größer geworden. Seit ein paar Wochen schwitze ich nachts stark, und die Haut juckt am ganzen Körper. Ich habe fünf Kilo abgenommen, obwohl ich normal esse. Abends habe ich manchmal Fieber. Wenn ich Alkohol trinke, tut die Beule komischerweise weh.",
 pmh:"bisher gesund; Pfeiffersches Drüsenfieber mit 17",meds:"keine",all:"keine bekannt",soc:"Maschinenbaustudent, lebt in einer WG, feste Partnerin; Nichtraucher; Alkohol am Wochenende; keine Haustiere, keine Reisen",fam:"Großvater Leukämie",
 vit:"RR 122/72 mmHg · HF 88/min · AF 14/min · SpO₂ 99 % · Temp. 37,9 °C · Lymphknoten links zervikal 3 cm, derb, nicht verschieblich, indolent",
 dx:"V. a. malignes Lymphom, am ehesten Hodgkin-Lymphom mit B-Symptomatik; DD: Non-Hodgkin-Lymphom, reaktive Lymphadenitis (EBV, CMV, HIV, Toxoplasmose), Tuberkulose, Metastase, Sarkoidose",
 plan:"Körperliche Untersuchung aller Lymphknotenstationen, Leber und Milz; Labor (Blutbild mit Differenzialblutbild, BSG, LDH, CRP, Leber- und Nierenwerte, HIV, EBV, Hepatitis-Serologie); Sonographie Hals und Abdomen; Lymphknotenexstirpation zur Histologie (keine Feinnadelpunktion); Staging mit PET-CT; vor Therapie Fertilitätserhalt (Kryokonservierung) besprechen; Vorstellung Hämatologie/Onkologie",
 patientQs:["Ist das Krebs?","Kann ich danach noch Kinder bekommen?","Muss ich mein Studium abbrechen?"],
 oa:[{q:"Welche Befunde sprechen für ein Malignom und gegen eine reaktive Lymphknotenschwellung?",a:"Größe über zwei Zentimeter, derbe Konsistenz, schlechte Verschieblichkeit, Schmerzlosigkeit, Wachstum über Wochen ohne Infekt sowie eine B-Symptomatik mit Fieber, Nachtschweiß und Gewichtsverlust. Juckreiz und Alkoholschmerz sind typisch für das Hodgkin-Lymphom.",kw:["2 cm|zwei Zentimeter|Größe","derb|hart","verschieblich","schmerzlos|indolent","B-Symptom|Nachtschweiß|Gewichtsverlust","Alkoholschmerz|Juckreiz|Pruritus"]},
  {q:"Wie sichern Sie die Diagnose?",a:"Durch die vollständige Entnahme eines Lymphknotens zur histologischen Untersuchung, denn eine Feinnadelpunktion reicht für die Lymphomdiagnostik nicht aus. Beim Hodgkin-Lymphom zeigen sich Hodgkin- und Reed-Sternberg-Zellen. Danach folgt das Staging mit PET-CT.",kw:["Exstirpation|Entnahme|Biopsie","Histolog","Feinnadel","Reed-Sternberg|Sternberg","PET|Staging"]},
  {q:"Was müssen Sie mit dem jungen Patienten vor Therapiebeginn besprechen?",a:"Die Chemo- und Strahlentherapie kann die Fruchtbarkeit dauerhaft schädigen. Deshalb biete ich vor Therapiebeginn eine Kryokonservierung von Spermien an. Außerdem kläre ich über Prognose – das Hodgkin-Lymphom ist meist heilbar –, Nebenwirkungen und Unterstützung im Studium auf.",kw:["Fruchtbarkeit|Fertilität","Kryokonservierung|Spermien|einfrieren","heilbar|Prognose","Nebenwirkung|Chemotherapie"]}],
 traps:"Ask all B symptoms one by one and about alcohol pain and itching – examiners count them. Fertility preservation must come up before the Oberarzt asks. Lay terms: 'Lymphknoten', 'Lymphdrüsenkrebs' only when you must; 'Gewebeprobe', 'Chemotherapie'.",
 terms:["Lymphadenopathie","Hodgkin-Lymphom","B-Symptomatik","Pruritus","Kryokonservierung"],
 lay:{open:"Ich habe seit zwei Monaten eine Beule links am Hals, die größer wird. Und nachts schwitze ich sehr stark.",pmh:"Ich war immer gesund. Mit siebzehn hatte ich Pfeiffersches Drüsenfieber.",ops:"Nein, noch nie.",meds:"Ich nehme keine Medikamente.",all:"Nein, keine.",fam:"Mein Opa ist an Leukämie gestorben.",
  nox:"Ich rauche nicht. Am Wochenende trinke ich ein paar Bier, aber seit die Beule da ist, tut sie nach dem Alkohol weh.",drugs:"Nein.",soc:"Ich studiere Maschinenbau und wohne in einer WG. Ich habe eine feste Freundin.",
  char:"Die Beule selbst tut nicht weh, nur nach Alkohol.",mod:"Nach Alkohol schmerzt sie, sonst spüre ich sie nicht.",prev:"Nein, so etwas hatte ich noch nie.",self:"Nein, ich habe nichts genommen.",
  vacc:"Ja, ich habe alle Impfungen.",reise:"Nein, ich war dieses Jahr nicht weg. Haustiere haben wir auch keine.",
  veg:{appetit:"Ich esse normal.",gewicht:"Ich habe trotzdem fünf Kilo abgenommen.",stuhl:"Normal.",wasser:"Normal.",schlaf:"Ich wache nachts klatschnass auf. Und die Haut juckt überall.",fieber:"Abends manchmal 37,9."}},
 brief:"Herr Winkler ist ein 24-jähriger Patient, der sich mit einer seit zwei Monaten bestehenden, langsam größenprogredienten, schmerzlosen Schwellung links zervikal vorstellte. Er berichtete über ausgeprägten Nachtschweiß, generalisierten Juckreiz, abendliche subfebrile Temperaturen und einen ungewollten Gewichtsverlust von fünf Kilogramm. Nach Alkoholgenuss schmerze die Schwellung. Infektzeichen, Reisen und Tierkontakte wurden verneint.\nVorerkrankungen: Mononukleose im Alter von 17 Jahren. Voroperationen wurden verneint. Keine Medikation. Allergien sind nicht bekannt. Nikotinkonsum wurde verneint, Alkohol am Wochenende. Der Großvater sei an einer Leukämie verstorben. Der Patient ist Student und lebt in einer Wohngemeinschaft.\nDie Anamnese mit B-Symptomatik spricht für ein malignes Lymphom, am ehesten ein Hodgkin-Lymphom. Differenzialdiagnostisch kommen ein Non-Hodgkin-Lymphom, eine reaktive Lymphadenitis und eine Tuberkulose in Betracht. Wir empfehlen: Untersuchung aller Lymphknotenstationen, Blutbild, LDH, BSG, Infektserologie, Sonographie, eine Lymphknotenexstirpation zur Histologie, ein Staging mit PET-CT und vor Therapiebeginn die Beratung zur Kryokonservierung."},

{id:"fy23",age:52,sex:"m",name:"Herr Arnold",vn:"Jürgen",geb:"15.09.1974",cm:173,kg:104,ha:"Herr Doktor Schmitt in St. Leon-Rot",sys:"endo",job:"Speditionskaufmann",scale:1,
 cc:"seit Wochen starker Durst, häufiges Wasserlassen, Müdigkeit, wiederkehrende Pilzinfektion",
 hpi:"Seit ein paar Wochen habe ich ständig Durst und trinke bestimmt vier Liter am Tag. Ich muss dauernd auf die Toilette, auch nachts dreimal. Ich bin müde und kann mich schlecht konzentrieren. Seit Monaten habe ich immer wieder einen juckenden Pilz in der Leiste, der nicht weggeht. Manchmal sehe ich verschwommen. Ein Betriebsarzt hat mir gesagt, mein Zucker ist zu hoch, und mich hergeschickt.",
 pmh:"Adipositas (BMI 35), arterielle Hypertonie, Fettleber",meds:"Amlodipin 5 mg 1-0-0",all:"keine bekannt",soc:"Speditionskaufmann (Büro, wenig Bewegung), verheiratet, zwei Kinder; raucht 10 Zigaretten/Tag; Alkohol 1–2 Bier abends; viele Softdrinks",fam:"Mutter und Bruder Diabetes mellitus Typ 2",
 vit:"RR 152/94 mmHg · HF 84/min · AF 14/min · SpO₂ 97 % · Temp. 36,7 °C · BZ 286 mg/dl (nicht nüchtern) · Urin-Stix: Glukose +++, Ketone negativ",
 dx:"Erstdiagnose Diabetes mellitus Typ 2 mit Hyperglykämie, ohne Ketoazidose; metabolisches Syndrom; DD: Typ-1- oder LADA-Diabetes, sekundärer Diabetes (Pankreas, Cortison), hyperosmolares Syndrom (ausgeschlossen)",
 plan:"Bestätigung mit HbA1c (≥ 6,5 %) oder Nüchternglukose (≥ 126 mg/dl); Labor (Kreatinin/eGFR, Lipide, Leberwerte, Urin-Albumin); Fußuntersuchung, Augenarzt (Retinopathie); Lebensstiländerung (Ernährung, Bewegung, Gewichtsreduktion, Rauchstopp), Diabetesschulung; Metformin einschleichend, bei hohem kardiovaskulärem Risiko SGLT2-Hemmer oder GLP-1-Agonist; Blutdruck- und Lipideinstellung; Behandlung der Intertrigo/Candidose; Disease-Management-Programm",
 patientQs:["Muss ich jetzt Insulin spritzen?","Kann der Zucker wieder weggehen, wenn ich abnehme?","Darf ich noch Auto fahren?"],
 oa:[{q:"Wie stellen Sie die Diagnose eines Diabetes mellitus?",a:"Mit einem HbA1c von mindestens 6,5 %, einer Nüchternglukose von mindestens 126 mg/dl, einem Zwei-Stunden-Wert im oralen Glukosetoleranztest von mindestens 200 mg/dl oder einem Gelegenheitsblutzucker von mindestens 200 mg/dl mit typischen Symptomen, wie hier.",kw:["HbA1c","6,5","126","200","oGTT|Glukosetoleranz","Symptom"]},
  {q:"Welche Untersuchungen auf Folgeschäden gehören zur Erstdiagnose?",a:"Augenärztliche Untersuchung auf Retinopathie, Nierenfunktion mit eGFR und Albumin im Urin auf Nephropathie, Fußuntersuchung mit Sensibilität und Pulsen auf Neuropathie und pAVK, dazu EKG, Blutdruck und Lipide zur Einschätzung des kardiovaskulären Risikos.",kw:["Augen|Retinopathie","Niere|Albumin|eGFR","Fuß|Neuropathie|Monofilament","Pulse|pAVK","Lipide|kardiovaskulär|EKG"]},
  {q:"Wie beginnen Sie die Therapie?",a:"Grundlage ist die Lebensstiländerung mit Ernährungsumstellung, Bewegung, Gewichtsreduktion und Rauchstopp sowie eine Diabetesschulung. Medikamentös beginne ich mit Metformin, einschleichend dosiert. Bei hohem kardiovaskulärem Risiko kommt früh ein SGLT2-Hemmer oder GLP-1-Rezeptoragonist hinzu. Insulin ist ohne Ketose zunächst nicht nötig.",kw:["Lebensstil|Ernährung|Bewegung","Gewicht","Schulung","Metformin","SGLT2|GLP-1|Empagliflozin|Semaglutid","Insulin.{0,40}nicht|ohne Ketose"]}],
 traps:"Ask about the classic triad and infections, the eyes and the feet; ask about softdrinks without moralising. Driving: as a car driver he may drive if there are no severe hypoglycaemias – answer carefully. Lay terms: 'Zuckerkrankheit', 'Blutzuckerlangzeitwert'.",
 terms:["Diabetes mellitus Typ 2","Polyurie","Polydipsie","HbA1c","Metformin"],
 lay:{open:"Ich habe seit Wochen ständig Durst und muss dauernd auf die Toilette. Der Betriebsarzt sagt, mein Zucker ist zu hoch.",pmh:"Ich habe hohen Blutdruck und eine Fettleber. Und ich wiege zu viel, das weiß ich.",ops:"Nein, noch nie.",meds:"Nur eine Blutdrucktablette am Morgen.",all:"Nein, keine.",
  fam:"Meine Mutter und mein Bruder haben Zucker.",nox:"Ich rauche zehn Zigaretten am Tag. Abends trinke ich ein, zwei Bier. Und ehrlich gesagt viel Cola.",drugs:"Nein.",soc:"Ich bin Speditionskaufmann, ich sitze den ganzen Tag im Büro. Ich bin verheiratet und habe zwei Kinder.",
  char:"Schmerzen habe ich keine.",mod:"Wenn ich viel Süßes trinke, habe ich noch mehr Durst.",prev:"Nein, so etwas kannte ich bisher nicht.",self:"Gegen den Pilz habe ich eine Creme aus der Apotheke benutzt, der kommt aber immer wieder.",
  vacc:"Ich glaube, ja.",reise:"Nein.",veg:{appetit:"Ich habe eher mehr Hunger.",gewicht:"Ich habe in letzter Zeit zwei, drei Kilo abgenommen, ohne es zu wollen.",stuhl:"Normal.",wasser:"Ich muss ständig, auch nachts dreimal.",schlaf:"Ich schlafe schlecht, weil ich nachts raus muss, und schnarche, sagt meine Frau.",fieber:"Nein.",durst:"Ja, ich trinke bestimmt vier Liter am Tag und habe trotzdem Durst."}},
 brief:"Herr Arnold ist ein 52-jähriger Patient, der sich auf Veranlassung des Betriebsarztes wegen erhöhter Blutzuckerwerte vorstellte. Er berichtete über seit Wochen bestehende Polydipsie mit einer Trinkmenge von etwa vier Litern pro Tag, Polyurie mit dreimaliger Nykturie, Müdigkeit, Konzentrationsstörungen und gelegentlich verschwommenes Sehen. Seit Monaten bestehe eine rezidivierende juckende Pilzinfektion in der Leiste. Er habe ungewollt zwei bis drei Kilogramm abgenommen.\nAn Vorerkrankungen bestehen eine Adipositas, eine arterielle Hypertonie und eine Steatosis hepatis. Voroperationen wurden verneint. Medikation: Amlodipin 5 mg 1-0-0. Allergien sind nicht bekannt. Der Patient rauche zehn Zigaretten pro Tag, trinke abends ein bis zwei Bier und konsumiere reichlich zuckerhaltige Getränke. Mutter und Bruder litten an Diabetes mellitus Typ 2. Der Patient ist Speditionskaufmann und verheiratet.\nEs handelt sich um die Erstdiagnose eines Diabetes mellitus Typ 2 ohne Hinweis auf eine Ketoazidose bei metabolischem Syndrom. Differenzialdiagnostisch ist ein LADA-Diabetes zu bedenken. Wir empfehlen: HbA1c, Nierenwerte, Lipide und Urin-Albumin, eine augenärztliche und eine Fußuntersuchung, eine Lebensstiländerung mit Diabetesschulung, Metformin, die Behandlung der Candidose und die Optimierung der Blutdruckeinstellung."},

{id:"fy24",age:38,sex:"m",name:"Herr Stein",vn:"Daniel",geb:"18.02.1988",cm:182,kg:80,ha:"Frau Doktor Lorenz in Ladenburg",sys:"neuro",job:"Außendienstmitarbeiter",via:"Ehefrau",scale:3,
 cc:"heute Morgen erstmaliger Krampfanfall laut Ehefrau, jetzt wach, Zungenbiss, Kopfschmerzen, Muskelkater",
 hpi:"Mein Mann ist heute früh um sechs im Bett plötzlich ganz steif geworden, hat einen Schrei ausgestoßen, und dann haben Arme und Beine gezuckt, vielleicht zwei Minuten lang. Die Augen waren offen und verdreht, die Lippen etwas blau. Danach hat er geschnarcht und war eine Viertelstunde lang verwirrt, er wusste nicht, wo er ist. Er hat sich auf die Zunge gebissen, und das Bett war nass. Jetzt hat er Kopfschmerzen und Muskelkater. Er hat in den letzten Nächten kaum geschlafen und gestern auf einer Feier viel getrunken.",
 pmh:"bisher gesund; Schädel-Hirn-Trauma ohne Folgen mit 16 (Fahrradunfall)",meds:"keine",all:"keine bekannt",soc:"Außendienstmitarbeiter, fährt beruflich täglich 200 km; verheiratet, ein Kind; Nichtraucher; Alkohol am Wochenende, gestern ca. 8 Bier; Schlafmangel",fam:"Cousin Epilepsie",
 vit:"RR 138/84 mmHg · HF 92/min · AF 16/min · SpO₂ 97 % · Temp. 37,2 °C · BZ 98 mg/dl · GCS 15 · lateraler Zungenbiss",
 dx:"Erstmaliger generalisierter tonisch-klonischer Anfall, provoziert durch Schlafentzug und Alkohol; DD: Synkope mit Myoklonien, strukturelle Ursache (Tumor, Blutung, Narbe nach SHT), Elektrolytstörung, Alkoholentzug, Hypoglykämie, psychogener Anfall",
 plan:"Neurologische Untersuchung, Labor (Blutzucker, Elektrolyte inkl. Natrium, Calcium, Magnesium, CK, Prolaktin, Alkoholspiegel, Blutbild, Leberwerte), EKG; zerebrale Bildgebung (MRT, akut cCT), EEG; Neurologie-Konsil; Aufklärung über Fahrverbot (Begutachtungsleitlinien: nach erstem provoziertem Anfall in der Regel 3 Monate, unprovoziert 6 Monate, Berufskraftfahrer länger) und Dokumentation; Schlafhygiene, Alkoholkarenz; Verhalten bei erneutem Anfall erklären",
 patientQs:["Ist das jetzt Epilepsie? Muss er für immer Tabletten nehmen?","Darf er morgen wieder zur Arbeit fahren? Er braucht das Auto für den Job.","Was soll ich tun, wenn das wieder passiert?"],
 oa:[{q:"Welche Befunde sprechen für einen epileptischen Anfall und gegen eine Synkope?",a:"Lateraler Zungenbiss, ein Initialschrei, offene, verdrehte Augen, rhythmische Zuckungen über mehr als eine Minute, Zyanose und eine längere postiktale Verwirrtheit sprechen für einen epileptischen Anfall. Bei einer Synkope sind Myoklonien kurz und die Reorientierung erfolgt rasch.",kw:["Zungenbiss","Initialschrei|Schrei","Augen offen|verdreht","postiktal|Verwirrtheit|Reorientierung","Synkope.{0,60}(kurz|rasch|schnell)|Myoklonien","Einnässen|Urinabgang"]},
  {q:"Welche Diagnostik veranlassen Sie nach einem ersten Anfall?",a:"Labor mit Blutzucker, Elektrolyten, CK und Prolaktin sowie Alkohol, ein EKG, eine zerebrale Bildgebung – bevorzugt MRT, im Notfall CT – zum Ausschluss einer strukturellen Ursache, hier auch wegen des früheren Schädel-Hirn-Traumas, und ein EEG.",kw:["Blutzucker|Elektrolyt|Natrium","CK|Prolaktin","EKG","MRT|CT|Bildgebung","EEG","Schädel-Hirn-Trauma|strukturell"]},
  {q:"Was müssen Sie zur Fahreignung sagen und dokumentieren?",a:"Nach einem ersten Anfall besteht zunächst keine Fahreignung. Nach den Begutachtungsleitlinien zur Kraftfahreignung darf ein privater Fahrer nach einem provozierten ersten Anfall in der Regel nach drei Monaten, nach einem unprovozierten nach sechs Monaten anfallsfrei wieder fahren; für Berufskraftfahrer gelten strengere Regeln. Die Aufklärung muss schriftlich dokumentiert werden.",kw:["Fahrverbot|keine Fahreignung|nicht fahren","Begutachtungsleitlinien","drei Monate|3 Monate","sechs Monate|6 Monate","Berufskraftfahrer|beruflich","dokumentier"]}],
 traps:"A Fremdanamnese: ask the wife what she saw minute by minute, but also talk to the patient. Document the driving ban explicitly – examiners always ask. Ask about sleep, alcohol, drugs and the old head injury. Lay terms: 'Krampfanfall', 'Hirnstromkurve', 'Fahrverbot'.",
 terms:["Epileptischer Anfall","Postiktale Phase","Zungenbiss","Elektroenzephalographie","Fahreignung"],
 lay:{open:"Ich bin die Ehefrau. Mein Mann hatte heute früh im Bett einen Krampfanfall, ungefähr zwei Minuten lang.",name:"Mein Mann heißt Daniel Stein. Ich bin Sarah Stein, seine Frau.",dob:"Er ist am achtzehnten Zweiten neunzehnhundertachtundachtzig geboren, also achtunddreißig.",size:"Er ist eins zweiundachtzig groß und wiegt ungefähr achtzig Kilo.",
  pmh:"Er war immer gesund. Mit sechzehn hatte er einen Fahrradunfall mit einer Gehirnerschütterung, aber ohne Folgen.",ops:"Nein, er wurde noch nie operiert.",meds:"Er nimmt keine Medikamente.",all:"Nein, keine.",fam:"Sein Cousin hat Epilepsie.",
  nox:"Er raucht nicht. Am Wochenende trinkt er Bier, gestern auf einer Geburtstagsfeier bestimmt acht Flaschen.",drugs:"Nein, Drogen nimmt er nicht. Soweit ich weiß.",soc:"Er ist im Außendienst und fährt jeden Tag über zweihundert Kilometer mit dem Auto. Wir haben eine kleine Tochter, die zahnt gerade, deshalb schlafen wir beide kaum.",
  char:"Er hat Kopfschmerzen, und alle Muskeln tun ihm weh, wie Muskelkater.",mod:"Ich weiß nicht, was den Anfall ausgelöst hat. Er hat wenig geschlafen und gestern viel getrunken.",prev:"Nein, so etwas hatte er noch nie. Auch keine Abwesenheiten oder Zuckungen, soweit ich weiß.",self:"Ich habe ihn auf die Seite gedreht und den Notruf gewählt.",
  vacc:"Ja, er ist geimpft.",reise:"Nein.",veg:{appetit:"Normal.",gewicht:"Unverändert.",stuhl:"Normal.",wasser:"Beim Anfall hat er ins Bett gemacht, sonst ist alles normal.",schlaf:"Seit Wochen schläft er nur vier, fünf Stunden.",fieber:"Nein, Fieber hatte er nicht."}},
 brief:"Herr Stein ist ein 38-jähriger Patient, der nach einem erstmaligen Krampfanfall in Begleitung seiner Ehefrau vorgestellt wurde (Fremdanamnese). Die Ehefrau berichtete, ihr Mann sei gegen sechs Uhr im Bett nach einem Initialschrei tonisch erstarrt; anschließend seien für etwa zwei Minuten generalisierte Zuckungen bei geöffneten, verdrehten Augen und perioraler Zyanose aufgetreten. Danach sei er etwa 15 Minuten desorientiert gewesen. Es bestünden ein lateraler Zungenbiss und ein Einnässen; aktuell klage der Patient über Kopfschmerzen und Muskelschmerzen. Am Vorabend habe er reichlich Alkohol getrunken, zudem bestehe seit Wochen ein Schlafmangel.\nVorerkrankungen: Schädel-Hirn-Trauma im Alter von 16 Jahren ohne Folgen. Voroperationen wurden verneint. Keine Medikation. Allergien sind nicht bekannt. Nikotin- und Drogenkonsum wurden verneint. Ein Cousin leide an Epilepsie. Der Patient ist Außendienstmitarbeiter mit täglicher Fahrtätigkeit, verheiratet und hat ein Kind.\nEs handelt sich um einen ersten generalisierten tonisch-klonischen Anfall, am ehesten provoziert durch Schlafentzug und Alkohol. Differenzialdiagnostisch kommen eine konvulsive Synkope, eine strukturelle Ursache und eine Elektrolytstörung in Betracht. Wir empfehlen: Labor mit Elektrolyten, CK und Prolaktin, EKG, zerebrale Bildgebung, ein EEG, ein neurologisches Konsil sowie die dokumentierte Aufklärung über das Fahrverbot."}
);

